Object.assign(window.TEM8_DICTIONARY, {"fa":{"oxford":{"phon":"fɑː","pos":"noun","senses":[{"en":"the fourth note of a major scale","cn":"大调音阶的第 4 音"},{"en":"Football Association (the organization that controls the sport of football (soccer) in England and Wales)","cn":"（英格兰和威尔士的）足球协会","pos":"abbreviation"}]},"media":{"uk":"media/uk/fa__gb_1.mp3","us":"media/us/fa__us_1.mp3"},"examples":[{"en":"the FA Cup","cn":"足总杯"}]},"faintly":{"oxford":{"phon":"ˈfeɪntli","pos":"adverb","senses":[{"en":"in a way that cannot be clearly seen, heard or smelt","cn":"（光、声、味）微弱的，不清楚的","ex":{"en":"She could faintly hear music playing.","cn":"她隐隐约约听到音乐在演奏。"}},{"en":"slightly; to a small degree","cn":"微弱地 在某种程度上","ex":{"en":"He looked faintly embarrassed.","cn":"他显得有点难堪。"}},{"en":"in a way that is not enthusiastic","cn":"不热情的；不积极的","ex":{"en":"She smiled faintly.","cn":"她淡淡一笑。"}}]},"media":{"uk":"media/uk/faintly__gb_1.mp3","us":"media/us/faintly__us_1.mp3"},"examples":[{"en":"She smiled faintly.","cn":"她淡淡地笑了一下。"},{"en":"He looked faintly embarrassed.","cn":"他显得有点难堪。"}]},"fairground":{"oxford":{"phon":"ˈfeəɡraʊnd","pos":"noun","senses":[{"en":"an outdoor area where a fair with entertainments is held","cn":"露天游乐场"},{"en":"a place where a fair showing farm animals, farm products, etc. is held","cn":"农畜产品集市场地","g":"[usually plural]","lab":"North American English","ex":{"en":"the Ohio State Fairgrounds","cn":"俄亥俄州农畜产品集市场地"}},{"en":"a place where companies and businesses hold a fair to show their products","cn":"商品交易会场址；展销会场地","g":"[usually plural]","lab":"North American English","ex":{"en":"the Milan trade fairgrounds","cn":"米兰交易会场址"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"展销会场地;集市场地","en":"A fairground is an area of land where a fair is held."}]},"media":{"uk":"media/uk/fairground__gb_1.mp3","us":"media/us/fairground__us_1.mp3"},"examples":[{"en":"the Ohio State Fairgrounds","cn":"俄亥俄州农畜产品集市场地"},{"en":"the Milan trade fairgrounds","cn":"米兰交易会场址"}]},"fact":{"media":{"uk":"media/uk/fact__gb_1.mp3","us":"media/us/fact__us_1.mp3"},"oxford":{"phon":"fækt","pos":"noun","senses":[{"en":"a thing that is known to be true, especially when it can be proved","cn":"（可证实的）事实，真相","g":"[countable]","lab":"informal","ex":{"en":"First, some basic facts about healthy eating.","cn":"首先，说说健康饮食的几点基本事实。"}},{"en":"things that are true rather than things that have been invented","cn":"真实的事物；真实情况","g":"[uncountable]","ex":{"en":"The story is based on fact.","cn":"这个故事是根据真人真事写的。"}},{"en":"used to refer to a particular situation that exists","cn":"现实；实际情况","g":"[singular]","ex":{"en":"I could no longer ignore the fact that he was unhappy.","cn":"我再也不能无视他不高兴这一事实了。"}}]},"collins":{"senses":[{"pos":"PHRASE 短语","cn":"考虑到…／除…外／虽然…","en":"You use the fact that after some verbs or prepositions, especially in expressions such as in view of the fact that ,apart from the fact that, and despite the fact that, to link the verb or preposition with a clause.","ex":{"en":"His chances do not seem good in view of the fact that the Chief Prosecutor has already voiced his public disapproval","cn":"鉴于检察长已公开表示反对，他的机会看来不大了。"}},{"pos":"PHRASE 短语","cn":"(用于强调或当从句为句子主语时)","en":"You use the fact that instead of a simple that-clause either for emphasis or because the clause is the subject of your sentence.","ex":{"en":"My family now accepts the fact that I don't eat sugar or bread","cn":"我的家人现在都接受了我不吃糖和面包这件事。"}},{"pos":"PHRASE 短语","cn":"准确地说;确切地说","en":"You use in fact ,in actual fact, or in point of fact to indicate that you are giving more detailed information about what you have just said.","ex":{"en":"We've had a pretty bad time while you were away. In fact, we very nearly split up this time","cn":"你不在的时候我们相处得很不愉快，确切地说这次我们差点就分手了。"}},{"pos":"PHRASE 短语","cn":"(用于修正、引出相反意见或对比等)事实上，其实","en":"You use in fact ,in actual fact, or in point of fact to introduce or draw attention to a comment that modifies, contradicts, or contrasts with a previous statement.","ex":{"en":"That sounds rather simple, but in fact it's very difficult","cn":"那听来简单，但实际上很难。"}},{"pos":"N-VAR 可变名词","cn":"事实;真相;实情","en":"When you refer to something as a fact or as fact, you mean that you think it is true or correct.","ex":{"en":"...a statement of verifiable historical fact","cn":"对有据可查的史实的讲述"}},{"pos":"N-COUNT 可数名词","cn":"资料;实情","en":"Facts are pieces of information that can be discovered.","ex":{"en":"There is so much information you can almost effortlessly find the facts for yourself","cn":"资料这么多，你几乎可以毫不费力地找到事实真相。"}},{"pos":"PHRASE 短语","cn":"确切地说;事实上;恰恰相反","en":"You use as a matter of fact to introduce a statement that gives more details about what has just been said, or an explanation of it, or something that contrasts with it.","ex":{"en":"It's not that difficult. As a matter of fact, it's quite easy","cn":"这并不那么困难，实际上，容易得很。"}},{"pos":"PHRASE 短语","cn":"(强调对真实性确信无疑)确确实实，的的确确","en":"If you say that you know something for a fact, you are emphasizing that you are completely certain that it is true.","ex":{"en":"I know for a fact that baby corn is very expensive in Europe","cn":"我知道玉米笋在欧洲的确价格不菲。"}},{"pos":"PHRASE 短语","cn":"(用于引出对所说重点的概括或陈述，或引起注意)总而言之，最重要的是，关键是","en":"You use the fact is or the fact of the matter is to introduce and draw attention to a summary or statement of the most important point about what you have been saying.","ex":{"en":"The fact is blindness hadn't stopped the children doing many of the things that sighted children enjoy","cn":"实际上，失明并没有妨碍这些孩子去做健全孩子喜欢做的事情。"}},{"pos":"PHRASE 短语","cn":"(用于强调必须接受某种情况)必须承认，无可否认","en":"You say the fact remains that something is the case when you want to emphasize that the situation must be accepted.","ex":{"en":"The fact remains that inflation, however you measure it, is unacceptably high","cn":"必须承认，无论怎么衡量，通货膨胀率都高得难以接受。"}},{"pos":"PHRASE 短语","cn":"(用以强调所说内容的真实性或正确性)事实就是如此，本来就是这样，说得一点不错","en":"You say and that's a fact to emphasize the truth or correctness of a statement that you have just made.","ex":{"en":"We aren't playing well as a team, and that's a fact","cn":"我们作为一个球队打得并不好，事实就是如此。"}},{"pos":"CONVENTION 惯用语","cn":"真的吗？不会吧！","en":"You say is that a fact? as a response to a statement which you find surprising, interesting, or unlikely.","ex":{"en":"'I'm still staff colonel.' — 'Is that a fact?'","cn":"“我还是参谋上校。”——“不会吧？”"}}]},"examples":[{"en":"Voluntary work was particularly important in view of the fact that women were often forced to give up paid work on marriage.","cn":"鉴于妇女一结婚就常常被迫放弃有报酬工作的事实，义务工作尤其重要。"},{"en":"‘She says I'm one of the best students she's ever taught.’ ‘Is that a fact?’ “","cn":"她说我是她教过的最好的学生之一。” “真的是这样吗？”"}]},"farther":{"media":{"uk":"media/uk/farther__gb_1.mp3","us":"media/us/farther__us_1.mp3"},"oxford":{"phon":"ˈfɑːðə(r)","pos":"adverb","senses":[{"en":"at or to a greater distance in space or time","cn":"（时间或空间上）更远，较远","lab":"British English","ex":{"en":"farther north/south","cn":"再往北／南"}},{"en":"at a greater distance in space, direction or time","cn":"（空间、方向或时间上）更远的，较远的","lab":"British English","ex":{"en":"the farther shore of the lake","cn":"湖的彼岸"},"pos":"adjective"}]},"examples":[{"en":"We watched their ship moving gradually farther away.","cn":"我们望着他们的船渐渐远去。"},{"en":"I have to travel further/farther to work now.","cn":"现在我得走更远的路去上班。"}]},"fasten":{"oxford":{"phon":"ˈfɑːsn","pos":"verb","senses":[{"en":"to close or join together the two parts of something; to become closed or joined together","cn":"（使两部分）系牢，扎牢，结牢，扣紧","g":"[transitive, intransitive]","ex":{"en":"Fasten your seat belts, please.","cn":"请系好安全带。"}},{"en":"to close something so that it will not open; to be closed in this way","cn":"（使）关好，盖好","g":"[transitive, intransitive]","ex":{"en":"Fasten the gates securely so that they do not blow open.","cn":"把大门闩好以免被风吹开。"}},{"en":"to fix something in a particular position","cn":"使固定；系牢","g":"[transitive]","ex":{"en":"He fastened back the shutters.","cn":"他关上百叶窗并将其扣紧。"}},{"en":"to attach or tie one thing to another thing","cn":"（使两物）系牢，扎牢，结牢，扣牢","g":"[transitive]","ex":{"en":"He fastened the papers together with a paper clip.","cn":"他用回形针别好了文件。"}},{"en":"if you fasten your arms around somebody, your teeth into something, etc., or if your arms, teeth, etc. fasten around, into, etc. somebody/something, you hold the person/thing strongly with your arms, etc.","cn":"握住；抓牢；咬住","g":"[transitive, intransitive]","ex":{"en":"The dog fastened its teeth in his leg.","cn":"狗死死咬着他的腿。"}},{"en":"if you fasten your eyes on somebody/something or your eyes fasten on somebody/something, you look at them for a long time","cn":"盯住","g":"[transitive, intransitive]","ex":{"en":"He fastened his gaze on her face.","cn":"他盯着她的脸。"}}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"扣牢;系牢","en":"When you fasten something, you close it by means of buttons or a strap, or some other device. If something fastens with buttons or straps, you can close it in this way.","ex":{"en":"She got quickly into her Mini and fastened the seat-belt","cn":"她迅速钻进她的 Mini 车里并系紧安全带。"}},{"pos":"VERB 动词","cn":"(用绳、带等)系上，拴上","en":"If you fasten one thing to another, you attach the first thing to the second, for example with a piece of string or tape.","ex":{"en":"There were no instructions on how to fasten the carrying strap to the box","cn":"没有如何将背带系在盒子上的说明。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(注意力)集中于…","en":"If someone or something fastens your attention on a particular thing or if your attention fastens on it, you start to concentrate on it rather than on anything else.","ex":{"en":"More and more her memory and all her thoughts fastened on one event","cn":"她越来越多地把记忆和心思都集中在一件事上。"}},{"pos":"VERB 动词","cn":"集中注意力于;专注于","en":"If someone or something fastens on a particular thing, they start to concentrate on it.","ex":{"en":"My mind attempted to calm itself by fastening on this trivial detail","cn":"我尝试将注意力集中在这个小细节上以让自己平静下来。"}},{"pos":"VERB 动词","cn":"纠缠;缠住","en":"If someone fastens on you, they keep following, talking to, or staying with you, when you want them to go away.","ex":{"en":"He's fastening on that poor girl like a leech.","cn":"他像蚂蟥一样缠着那个可怜的姑娘。"}}]},"media":{"uk":"media/uk/fasten__gb_1.mp3","us":"media/us/fasten__us_1.mp3"},"examples":[{"en":"The dress fastens at the back.","cn":"这件连衣裙是在后背系扣的。"},{"en":"He fastened up his coat and hurried out.","cn":"他扣好大衣就匆匆出去了。"}]},"face-to-face":{"oxford":{"phon":"ˌfeɪs tə ˈfeɪs","pos":"adverb","senses":[{"en":"in a way that involves people who are close together and looking at each other","cn":"面对面的","lab":"figurative","ex":{"en":"He opened the door and came face to face with a burglar.","cn":"他打开门和窃贼打了个照面。"}},{"en":"involving people who are close together and looking at each other","cn":"面对面的","ex":{"en":"a face-to-face conversation","cn":"面谈"},"pos":"adjective"}]},"media":{"uk":"media/uk/face_to_face_1_gb_1.mp3","us":"media/us/face_to_face_1_us_1.mp3"},"examples":[{"en":"I deal with customers on the phone and rarely meet them face-to-face.","cn":"我用电话和客户打交道，很少和他们见面。"},{"en":"He opened the door and came face-to-face with a burglar.","cn":"他打开门和窃贼打了个照面。"}]},"facebook":{"oxford":{"phon":"ˈfeɪsbʊk","pos":"noun","senses":[{"en":"a very popular social media website","cn":"脸书（社交媒体网站）","ex":{"en":"Are you on Facebook?","cn":"你有脸书帐号吗？"}}]},"media":{"uk":"media/uk/facebook_1_gb_1.mp3","us":"media/us/facebook_1_us_1.mp3"}},"farming":{"media":{"uk":"media/uk/farming__gb_1.mp3","us":"media/us/farming__us_1.mp3"},"oxford":{"phon":"ˈfɑːmɪŋ","pos":"noun","senses":[{"en":"the business of managing or working on a farm","cn":"务农；农场经营","lab":"North American English","ex":{"en":"to take up farming","cn":"从事农业"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"耕种;养殖","en":"Farming is the activity of growing crops or keeping animals on a farm."}]},"examples":[{"en":"sheep/fish, etc. farming","cn":"牧羊、养鱼等"},{"en":"modern farming methods","cn":"现代耕作方法"}],"base":"farm"},"favoured":{"media":{"uk":"media/uk/favoured__gb_1.mp3","us":"media/us/favoured__us_1.mp3"},"oxford":{"phon":"ˈfeɪvəd","pos":"adjective","senses":[{"en":"treated in a special way or receiving special help or advantages in a way that may seem unfair","cn":"受到宠爱的；得到偏爱的；获得优惠的","ex":{"en":"a member of the President’s favoured circle of advisers","cn":"总统宠爱的顾问班子中的一员"}},{"en":"preferred by most people","cn":"大众喜爱的","ex":{"en":"the favoured candidate","cn":"公众喜爱的候选人"}},{"en":"particularly pleasant and worth having","cn":"称心如意的；中意的","lab":"formal","ex":{"en":"Their house is in a very favoured position near the park.","cn":"他们的房子在公园附近一个很惬意的地段。"}}]},"examples":[{"en":"Their house is in a very favoured position near the park.","cn":"他们的房子在公园附近一个很惬意的地段。"},{"en":"a member of the President's favoured circle of advisers","cn":"总统宠爱的顾问班子中的一员"}],"base":"favour"},"fastened":{"lemma":"fasten"},"failing":{"media":{"uk":"media/uk/failing__gb_1.mp3","us":"media/us/failing__us_1.mp3"},"oxford":{"phon":"ˈfeɪlɪŋ","pos":"noun","senses":[{"en":"a weakness or fault in somebody/something","cn":"弱点；缺点","ex":{"en":"She is aware of her own failings.","cn":"她了解自己的弱点。"}},{"en":"not achieving something; unsuccessful","cn":"未做到的；失败的","ex":{"en":"More support is needed to improve failing schools.","cn":"运营不善的学校，要多加支持，助其改进。"},"pos":"adjective"},{"en":"becoming weak","cn":"变弱的；变差的","ex":{"en":"His last months in office were marred by failing health.","cn":"他在任期的最后数月健康状况每况愈下。"},"pos":"adjective"},{"en":"used to introduce a suggestion that could be considered if the one just mentioned is not possible","cn":"如果不能；如果没有","ex":{"en":"Ask a friend to recommend a doctor or, failing that, ask for a list in your local library.","cn":"请朋友推荐一位医生，如果办不到就向当地图书馆要一份名单。"},"pos":"preposition"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"过错;缺陷;不足","en":"The failings of someone or something are their faults or unsatisfactory features.","ex":{"en":"Like many in Russia, she blamed the country's failings on futile attempts to catch up with the West","cn":"像俄罗斯很多人一样，她认为国家的错误就在于徒然地竭力追赶西方。"}},{"pos":"PHRASE 短语","cn":"(引出另一种选择)如果不能的话，万一不行的话","en":"You say failing that to introduce an alternative, in case what you have just said is not possible.","ex":{"en":"Find someone who will let you talk things through, or failing that, write down your thoughts.","cn":"找个能让你把事情说清楚的人，如果不行的话，就把你所想的写下来。"}}]},"examples":[{"en":"Ask a friend to recommend a doctor or, failing that, ask for a list in your local library.","cn":"请朋友推荐一位医生，如果办不到就向当地图书馆要一份名单。"},{"en":"The inquiry acknowledges failings in the judicial system.","cn":"这次调查承认司法制度有缺陷。"}],"base":"fail"},"fallen":{"media":{"uk":"media/uk/fallen__gb_2.mp3","us":"media/us/fallen__us_2.mp3"},"oxford":{"phon":"ˈfɔːlən","pos":"adjective","senses":[{"en":"lying on the ground, after falling","cn":"倒下的；落下的；落在地上的","ex":{"en":"a fallen tree","cn":"倒下的树"}},{"en":"killed in a war","cn":"阵亡的","lab":"formal","ex":{"en":"Each year on the anniversary of the battle he remembered his fallen comrades.","cn":"每年的战斗周年纪念日，他都会纪念阵亡的战友。"}}]},"collins":{"senses":[{"pos":"","cn":"","en":"Fallen is the past participle of fall ."},{"pos":"N-PLURAL 复数名词","cn":"阵亡士兵","en":"The fallen are soldiers who have died in battle.","ex":{"en":"Work began on establishing the cemeteries as permanent memorials to the fallen.","cn":"把公墓建成阵亡战士的永久性纪念碑的工作已经开始。"}},{"pos":"ADJ 形容词","cn":"(基督教中指人或天使)堕落的,有罪的","en":"In the Christian religion, fallen can be used to describe people or angels after the time when they sinned and were punished by God.","ex":{"en":"...Lucifer, the fallen angel.","cn":"堕落天使路西法"}},{"pos":"ADJ 形容词","cn":"(女子)失贞的，失身的","en":"In the past, people described a woman as a fallen woman when she was no longer respected because she had had sex with someone that she was not married to."}]},"examples":[{"en":"a fallen tree","cn":"倒下的树"},{"en":"The road was blocked by a fallen tree.","cn":"马路被倒下的一棵树堵住了。"}],"base":"fall"},"fantastically":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"extremely good, in a way that makes you feel excited and happy – used mainly in spoken English","cn":""},{"en":"extremely good – used mainly in spoken English","cn":""}]},"examples":[{"en":"It’s a fantastic place, really beautiful!","cn":"","src":"ld"},{"en":"‘I’ve passed my driving test.’ ‘Fantastic!’","cn":"","src":"ld"}],"media":{"uk":"media/uk/fantastically__gb_1.mp3","us":"media/us/fantastically__us_1.mp3"},"oxford":{"phon":"fænˈtæstɪkli","pos":"adverb","senses":[{"en":"extremely well","cn":"极好地；出色地；了不起地","lab":"informal","ex":{"en":"You did fantastically.","cn":"你做得非常出色。"}},{"en":"to an extremely large degree","cn":"奇妙地：极大地，巨大地，难以置信地成为","lab":"informal","ex":{"en":"fantastically successful","cn":"非常成功"}},{"en":"very strangely","cn":"奇妙地：非常奇怪地","ex":{"en":"a fantastically shaped piece of stone","cn":"一块奇形怪状的石头"}}]}},"far-reaching":{"oxford":{"phon":"ˌfɑː ˈriːtʃɪŋ","pos":"adjective","senses":[{"en":"likely to have a lot of influence or many effects","cn":"影响深远的；广泛的","ex":{"en":"far-reaching consequences/implications","cn":"影响深远的后果；意味深长"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"影响深远的;意义重大的","en":"If you describe actions, events, or changes as far-reaching, you mean that they have a very great influence and affect a great number of things.","ex":{"en":"The economy is in danger of collapse unless far-reaching reforms are implemented.","cn":"如果不实施影响深远的改革，经济就面临崩溃的危险。"}}]},"media":{"uk":"media/uk/far_reaching_1_gb_1.mp3","us":"media/us/far_reaching_1_us_1.mp3"},"examples":[{"en":"far-reaching consequences/implications","cn":"影响深远的后果；意味深长"},{"en":"far-reaching changes/reforms","cn":"意义深远的变革/改革"}]},"fatal":{"oxford":{"phon":"ˈfeɪtl","pos":"adjective","senses":[{"en":"causing or ending in death","cn":"致命的","ex":{"en":"a fatal accident/blow/illness","cn":"致命的事故／一击／疾病"}},{"en":"causing disaster or failure","cn":"灾难性的；毁灭性的；导致失败的","ex":{"en":"a fatal error/mistake","cn":"灾难性的错误"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(行为)致命的，后果极严重的，毁灭性的","en":"A fatal action has very undesirable effects.","ex":{"en":"It would clearly be fatal for Europe to quarrel seriously with America","cn":"欧洲若与美国反目显然会有致命的后果。"}},{"pos":"ADJ 形容词","cn":"(事故或疾病)致命的，致死的","en":"A fatal accident or illness causes someone's death.","ex":{"en":"...the fatal stabbing of a police sergeant","cn":"对警官致命的一刺"}}]},"media":{"uk":"media/uk/fatal__gb_1.mp3","us":"media/us/fatal__us_1.mp3"},"examples":[{"en":"It'd be fatal to try and stop them now.","cn":"现在要试图制止他们就会导致灾难性后果。"},{"en":"If she gets ill again it could prove fatal.","cn":"如果她再患病，就会有性命之忧。"}]},"fantasy":{"media":{"uk":"media/uk/fantasy__gb_1.mp3","us":"media/us/fantasy__us_1.mp3"},"oxford":{"phon":"ˈfæntəsi","pos":"noun","senses":[{"en":"a pleasant situation that you imagine but that is unlikely to happen","cn":"幻想；想象","g":"[countable]","ex":{"en":"He spoke of his childhood fantasies about becoming a famous football player.","cn":"他谈起儿时想成为足球明星的幻想。"}},{"en":"a product of your imagination","cn":"想象的产物；幻想作品","g":"[countable]","ex":{"en":"Her books are usually escapist fantasies.","cn":"她的书通常是逃避现实的幻想作品。"}},{"en":"the act of imagining things; a person’s imagination","cn":"幻想；想象","g":"[uncountable]","ex":{"en":"This is a work of fantasy.","cn":"这是部幻想作品。"}},{"en":"a type of story that is set in a world, or a version of our world, that does not really exist and involves magic, monsters, etc.","cn":"奇幻小说","g":"[uncountable]","ex":{"en":"She wrote a series of fantasy novels filled with wizards, witches and dragons.","cn":"她写了一系列充满巫师、女巫和龙的奇幻小说。"}},{"en":"a competition in which you choose players to make your own imaginary team, and score points according to the performance of the real players","cn":"梦幻足球（虚拟比赛方式，组成想象中的球队，根据球员的实际比赛表现计算得分）","g":"[uncountable]","ex":{"en":"In his personal time, Stephen blogs for several fantasy hockey leagues.","cn":"在他的个人时间里，斯蒂芬为几个梦幻曲棍球联盟撰写博客。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"憧憬;幻想","en":"A fantasy is a pleasant situation or event that you think about and that you want to happen, especially one that is unlikely to happen.","ex":{"en":"...fantasies of romance and true love.","cn":"对浪漫和真爱的憧憬"}},{"pos":"N-VAR 可变名词","cn":"奇幻故事;幻想的场景","en":"You can refer to a story or situation that someone creates from their imagination and that is not based on reality as fantasy .","ex":{"en":"The film is more of an ironic fantasy than a horror story.","cn":"这部影片与其说是恐怖片，不如说是带有讽刺意味的奇幻片。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"幻想;想象","en":"Fantasy is the activity of imagining things.","ex":{"en":"...a world of imagination, passion, fantasy, reflection.","cn":"一个充满想象、激情、梦幻和沉思的世界"}},{"pos":"ADJ 形容词","cn":"虚拟比赛(游戏)(玩家选择一个虚拟的团队，以团队成员在真实比赛中的实际表现来计分)","en":"Fantasy football, baseball, or another sport is a game in which players choose an imaginary team and score points based on the actual performances of the members of their team in real games.","ex":{"en":"Haskins said he has been playing fantasy baseball for the past five years.","cn":"哈斯金斯说过去 5 年他一直在玩虚拟棒球。"}}]},"examples":[{"en":"his childhood fantasies about becoming a famous football player","cn":"他儿时想成为著名足球运动员的幻想"},{"en":"Her books are usually escapist fantasies.","cn":"她的书通常是逃避现实的幻想作品。"}]},"faraway":{"media":{"uk":"media/uk/faraway__gb_1.mp3","us":"media/us/faraway__us_1.mp3"},"oxford":{"phon":"ˈfɑːrəweɪ","pos":"adjective","senses":[{"en":"a long distance away","cn":"遥远的","ex":{"en":"a war in a faraway country","cn":"在一个远方国家发生的战争"}},{"en":"an expression on your face that shows that your thoughts are far away from your present situation","cn":"心不在焉的；恍惚的；出神的","ex":{"en":"There was a faraway look in her eyes.","cn":"她的眼里闪过一丝遥远的神色。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"远的;遥远的;远方的","en":"A faraway place is a long distance from you or from a particular place.","ex":{"en":"They have just returned from faraway places with wonderful stories to tell.","cn":"他们刚从遥远的地方回来，有很多精彩的故事要讲。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"思绪飘远的;心不在焉的","en":"If you describe someone or their thoughts as faraway, you mean that they are thinking about something that is very different from the situation around them.","ex":{"en":"She smiled with a faraway look in her eyes.","cn":"她微笑着，眼神缥缈恍惚。"}}]},"examples":[{"en":"a war in a faraway country","cn":"在一个远方国家发生的战争"},{"en":"She dreamed of flying away to exotic faraway places.","cn":"她梦想着飞到遥远的异国。"}]},"familiar":{"media":{"uk":"media/uk/familiar__gb_1.mp3","us":"media/us/familiar__us_1.mp3"},"oxford":{"phon":"fəˈmɪliə(r)","pos":"adjective","senses":[{"en":"well known to you; often seen or heard and therefore easy to recognize","cn":"熟悉的；常见到的；常听说的","ex":{"en":"to look/sound/seem familiar","cn":"眼熟；耳熟；似曾相识"}},{"en":"knowing something very well","cn":"通晓；熟悉","ex":{"en":"an area with which I had been familiar since childhood","cn":"我自幼就了若指掌的一个地区"}},{"en":"very informal, sometimes in a way that is unpleasant","cn":"随便的","ex":{"en":"You seem to be on very familiar terms with your tutor.","cn":"你似乎和你的导师之间很随便。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"熟悉的;熟知的","en":"If someone or something is familiar to you, you recognize them or know them well.","ex":{"en":"He talked of other cultures as if they were more familiar to him than his own","cn":"他谈起其他文化时似乎比对他自己的文化还要熟悉。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"熟悉;熟知","en":"If you are familiar with something, you know or understand it well.","ex":{"en":"Lesinko is quite familiar with Central Television. He worked there for 25 years","cn":"莱辛科对中央电视台相当熟悉。他在那儿工作了25年。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"过分亲昵的;过于随便的;放肆的","en":"If someone you do not know well behaves in a familiar way towards you, they treat you very informally in a way that you might find offensive.","ex":{"en":"The driver of that taxi-cab seemed to me familiar to the point of impertinence","cn":"那辆出租车的司机在我看来放肆到了无礼的地步。"}}]},"examples":[{"en":"After a few drinks her boss started getting too familiar for her liking.","cn":"老板几杯酒下肚以后就开始令她觉得过分亲昵。"},{"en":"The smell is very familiar to everyone who lives near a bakery.","cn":"住在面包店附近的人都很熟悉这种气味。"}]},"failed":{"media":{"uk":"media/uk/failed__gb_1.mp3","us":"media/us/failed__us_1.mp3"},"oxford":{"phon":"feɪld","pos":"adjective","senses":[{"en":"not successful","cn":"失败的；不成功的","ex":{"en":"a failed writer","cn":"不成功的作家"}}]},"examples":[{"en":"a failed writer","cn":"不成功的作家"},{"en":"a failed coup","cn":"流产政变"}],"base":"fail"},"famous":{"media":{"uk":"media/uk/famous__gb_1.mp3","us":"media/us/famous__us_1.mp3"},"oxford":{"phon":"ˈfeɪməs","pos":"adjective","senses":[{"en":"known about by many people","cn":"著名的；出名的","ex":{"en":"a famous artist/actor","cn":"著名艺术家／演员"}},{"en":"people who are known about by many people","cn":"名人","g":"[plural]","ex":{"en":"the lifestyles of the rich and famous","cn":"富豪名流的生活方式"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"著名的;有名的","en":"Someone or something that is famous is very well known.","ex":{"en":"New Orleans is famous for its cuisine.","cn":"新奥尔良以其美食而著称。"}}]},"examples":[{"en":"‘Everything's under control.’ ‘Famous last words!’ “","cn":"一切都在掌握之中。” “净吹牛！”"},{"en":"She was more famous as a writer than as a singer.","cn":"她作为作家比作为歌手名声要大。"}]},"favourable":{"media":{"uk":"media/uk/favourable__gb_1.mp3","us":"media/us/favourable__us_1.mp3"},"oxford":{"phon":"ˈfeɪvərəbl","pos":"adjective","senses":[{"en":"making people have a good opinion of somebody/something","cn":"给人好印象的","ex":{"en":"She made a favourable impression on his parents.","cn":"她给他的父母留下了好印象。"}},{"en":"positive and showing your good opinion of somebody/something","cn":"肯定的；赞同的；支持的","ex":{"en":"The performance drew a lot of favourable comments from reviewers.","cn":"那场演出获得评论家的许多好评。"}},{"en":"expressing your agreement; giving permission","cn":"赞同的；支持的；准许的","ex":{"en":"Their demands received a favourable response.","cn":"他们的要求获准了。"}},{"en":"good for something and making it likely to be successful or have an advantage","cn":"有利的；有助于…的","ex":{"en":"favourable economic conditions","cn":"有利的经济环境"}},{"en":"fairly good and not too expensive","cn":"好而不贵的；优惠的","ex":{"en":"They offered me a loan on very favourable terms.","cn":"他们提出以十分优惠的条件贷款给我。"}},{"en":"blowing in the direction of travel","cn":"顺的","lab":"figurative","ex":{"en":"They could not sail without a favourable wind.","cn":"没有顺风，他们就无法航行。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"赞成的;赞同的","en":"If your opinion or your reaction is favourable to something, you agree with it and approve of it.","ex":{"en":"His recently completed chapel for Fitzwilliam is attracting favourable comment","cn":"他最近为菲茨威廉建成的小教堂赢得了好评。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"良好的;肯定的;讨人喜欢的","en":"If something makes a favourable impression on you or is favourable to you, you like it and approve of it.","ex":{"en":"His ability to talk tough while eating fast made a favourable impression on his dining companions","cn":"他能一面快速地吃饭,一面言辞强硬地说话，给同他一起就餐的人留下了很好的印象。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(条件)有利的，适宜的","en":"Favourable conditions make something more likely to succeed or seem more attractive.","ex":{"en":"It's believed the conditions in which the elections are being held are too favourable to the government.","cn":"人们认为举行选举的条件对政府过于有利。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"优于…的;不逊于…的","en":"If you make a favourable comparison between two things, you say that the first is better than or as good as the second.","ex":{"en":"The film bears favourable technical comparison with Hollywood productions costing 10 times as much.","cn":"该片与耗资为其 10 倍的好莱坞制作相比在技术上毫不逊色。"}}]},"examples":[{"en":"They offered me a loan on very favourable terms.","cn":"他们提出以十分优惠的条件贷款给我。"},{"en":"I was very favourably impressed with her work.","cn":"她的工作给我留下了很好的印象。"}]},"factual":{"media":{"uk":"media/uk/factual__gb_1.mp3","us":"media/us/factual__us_1.mp3"},"oxford":{"phon":"ˈfæktʃuəl","pos":"adjective","senses":[{"en":"based on or containing facts","cn":"根据事实的；事实的；真实的","ex":{"en":"The story is a factual account of events in early aviation.","cn":"这个故事是对早期航空事件的真实描述。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"与事实有关的;真实的","en":"Something that is factual is concerned with facts or contains facts, rather than giving theories or personal interpretations.","ex":{"en":"The editorial contained several factual errors","cn":"社论里有几处事实性错误。"}}]},"examples":[{"en":"The essay contains a number of factual errors.","cn":"文章中有一些与事实不符的错误。"},{"en":"a factual account of events","cn":"事件的如实报道"}]},"fashionable":{"media":{"uk":"media/uk/fashionable__gb_1.mp3","us":"media/us/fashionable__us_1.mp3"},"oxford":{"phon":"ˈfæʃnəbl","pos":"adjective","senses":[{"en":"following a style that is popular at a particular time","cn":"流行的；时兴的；时髦的","ex":{"en":"fashionable clothes/ideas/styles","cn":"时髦的服装／观念／式样"}},{"en":"used or visited by people following a current fashion, especially by rich people","cn":"时髦人物使用的；（尤指）有钱人常光顾的","ex":{"en":"a fashionable address/resort/restaurant","cn":"时髦人物常去的地点／度假地／餐馆"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"时髦的;时兴的;流行的","en":"Something or someone that is fashionable is popular or approved of at a particular time.","ex":{"en":"It became fashionable to eat certain kinds of fish","cn":"吃某些种类的鱼开始流行起来。"}}]},"examples":[{"en":"Such thinking is fashionable among right-wing politicians.","cn":"在政界右翼人士中这种想法很流行。"},{"en":"His wife was blonde and fashionably thin.","cn":"他的妻子一头金发，苗条入时。"}]},"farmer":{"oxford":{"phon":"ˈfɑːmə(r)","pos":"noun","senses":[{"en":"a person who owns or manages a farm","cn":"农场主；农人","ex":{"en":"My parents are dairy farmers.","cn":"我父母是奶农。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"农场主;农民","en":"A farmer is a person who owns or manages a farm."}]},"media":{"uk":"media/uk/farmer__gb_1.mp3","us":"media/us/farmer__us_1.mp3"}},"falls":{"lemma":"fall","media":{"uk":"media/uk/fall__gb_1.mp3","us":"media/us/fall__us_1.mp3"}},"fatherly":{"media":{"uk":"media/uk/fatherly__gb_1.mp3","us":"media/us/fatherly__us_1.mp3"},"oxford":{"phon":"ˈfɑːðəli","pos":"adjective","senses":[{"en":"typical of a good father","cn":"父亲的；慈父般的","ex":{"en":"fatherly advice","cn":"慈父般的忠告"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"慈父般的;像父亲一样的","en":"Fatherly feelings or actions are like those of a kind father.","ex":{"en":"His voice filled with fatherly concern","cn":"他的声音充满了慈父般的关切。"}}]},"examples":[{"en":"He keeps a fatherly eye on his players.","cn":"他像父亲一样照管着他的球员。"},{"en":"fatherly advice","cn":"慈父般的忠告"}]},"fabric":{"media":{"uk":"media/uk/fabric__gb_1.mp3","us":"media/us/fabric__us_1.mp3"},"oxford":{"phon":"ˈfæbrɪk","pos":"noun","senses":[{"en":"material made by weaving wool, cotton, silk, etc., used for making clothes, curtains, etc. and for covering furniture","cn":"织物；布料","g":"[uncountable, countable]","ex":{"en":"They sell a wide variety of printed cotton fabric.","cn":"他们出售多种印花棉布料。"}},{"en":"the basic structure of a society, an organization, etc. that enables it to function successfully","cn":"（社会、机构等的）结构","g":"[singular]","lab":"formal","ex":{"en":"a trend which threatens the very fabric of society","cn":"威胁社会基本结构的趋势"}},{"en":"the basic structure of a building, such as the walls, floor and roof","cn":"（建筑物的）结构（如墙、地面、屋顶）","g":"[singular]","ex":{"en":"The city retains much of its historic fabric.","cn":"这座城市保留着其历史结构的大部份。"}}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"织物;布料","en":"Fabric is cloth or other material produced by weaving together cotton, nylon, wool, silk, or other threads. Fabrics are used for making things such as clothes, curtains, and sheets.","ex":{"en":"...small squares of red cotton fabric","cn":"小块方形红棉布"}},{"pos":"N-SING 单数名词","cn":"(社会或体系的)基本结构","en":"The fabric of a society or system is its basic structure, with all the customs and beliefs that make it work successfully.","ex":{"en":"The fabric of society has been deeply damaged by the previous regime","cn":"社会结构已遭到上届政府极大的破坏。"}},{"pos":"N-SING 单数名词","cn":"(建筑的)结构，构造","en":"The fabric of a building is its walls, roof, and the materials with which it is built.","ex":{"en":"Condensation will eventually cause the fabric of the building to rot away.","cn":"冷凝作用将最终使建筑结构腐朽掉。"}}]},"examples":[{"en":"‘What material is this dress made of?’ ‘Cotton.’ “","cn":"这件裙子是用什么料子做的？” “棉布。”"},{"en":"He owns a factory producing a range of textiles.","cn":"他拥有一家工厂，生产一系列纺织品。"}]},"faint":{"oxford":{"phon":"feɪnt","pos":"adjective","senses":[{"en":"that cannot be clearly seen, heard or smelt","cn":"（光、声、味）微弱的，不清楚的","ex":{"en":"a faint glow/glimmer/light","cn":"微弱的光亮／闪光／光"}},{"en":"very small; possible but unlikely","cn":"微小的；可能性不大的","ex":{"en":"There is still a faint hope that she may be cured.","cn":"她的病还有一点点希望可以治愈。"}},{"en":"not enthusiastic","cn":"不热情的；不积极的","ex":{"en":"a faint show of resistance","cn":"软弱无力装模作样的抵抗"}},{"en":"feeling weak and tired and likely to become unconscious","cn":"昏眩；快要昏厥","g":"[not before noun]","ex":{"en":"She suddenly felt faint.","cn":"她突然感到快要昏倒。"}},{"en":"to become unconscious when not enough blood is going to your brain, usually because of the heat, a shock, etc.","cn":"昏厥","lab":"informal","ex":{"en":"to faint from hunger","cn":"饿昏过去"},"pos":"verb"},{"en":"the state of becoming unconscious","cn":"昏厥","ex":{"en":"He fell to the ground in a dead faint.","cn":"他跌倒在地，昏死过去。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(声音、颜色、标记、感觉或特性)微弱的，暗淡的，虚弱的","en":"A faint sound, colour, mark, feeling, or quality has very little strength or intensity.","ex":{"en":"He became aware of the soft, faint sounds of water dripping","cn":"他开始注意到轻微的水滴声。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不尽力的;敷衍的;半心半意的","en":"A faint attempt at something is one that is made without proper effort and with little enthusiasm.","ex":{"en":"Caroline made a faint attempt at a laugh","cn":"卡罗琳敷衍地笑了一下。"}},{"pos":"VERB 动词","cn":"晕厥;晕倒","en":"If you faint, you lose consciousness for a short time, especially because you are hungry, or because of pain, heat, or shock.","ex":{"en":"She suddenly fell forward on to the table and fainted","cn":"她突然向前栽倒在桌上，晕了过去。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"晕眩的;虚弱无力的","en":"Someone who is faint feels weak and unsteady as if they are about to lose consciousness.","ex":{"en":"Other signs of angina are nausea, sweating, feeling faint and shortness of breath.","cn":"心绞痛的其他征兆有恶心、出汗、头昏和气短。"}}]},"media":{"uk":"media/uk/faint__gb_1.mp3","us":"media/us/faint__us_1.mp3"},"examples":[{"en":"We could hear their voices growing fainter as they walked down the road.","cn":"他们沿路走远时我们听见他们的说话声逐渐模糊。"},{"en":"There is still a faint hope that she may be cured.","cn":"她的病还有一点点希望可以治愈。"}]},"fall":{"media":{"uk":"media/uk/fall__gb_1.mp3","us":"media/us/fall__us_1.mp3"},"oxford":{"phon":"fɔːl","pos":"verb","senses":[{"en":"to drop down from a higher level to a lower level","cn":"落下；下落；掉落；跌落","g":"[intransitive]","sc":"drop down","ex":{"en":"The rain was falling steadily.","cn":"雨不停地下着。"}},{"en":"to suddenly stop standing","cn":"突然倒下；跌倒；倒塌","g":"[intransitive]","sc":"stop standing","ex":{"en":"She slipped on the ice and fell.","cn":"她在冰上滑了一跤。"}},{"en":"to decrease in amount, number or strength","cn":"（数量）减少，下降；（强度）减小","g":"[intransitive]","sc":"decrease","ex":{"en":"Prices continued to fall on the stock market today.","cn":"今天股票市场价格继续下跌。"}},{"en":"to pass into a particular state; to begin to be something","cn":"进入（某状态）；开始变成（某事物）","g":"[intransitive]","sc":"become","ex":{"en":"He had fallen asleep on the sofa.","cn":"他在沙发上睡着了。"}},{"en":"to hang down","cn":"下垂；低垂","g":"[intransitive]","sc":"of hair/material","ex":{"en":"Her hair fell over her shoulders in a mass of curls.","cn":"她的鬈发披肩。"}},{"en":"to slope downwards","cn":"向下倾斜","g":"[intransitive]","sc":"slope downwards","ex":{"en":"The land falls away sharply towards the river.","cn":"地势向河边陡然倾斜。"}},{"en":"to be defeated or captured","cn":"被打败；沦陷；失守","g":"[intransitive]","sc":"be defeated","ex":{"en":"The coup failed but the government fell shortly afterwards.","cn":"政变虽然流产，但是不久以后政府便垮台了。"}},{"en":"to die in battle; to be shot","cn":"阵亡；被击毙","g":"[intransitive]","lab":"literary","sc":"die in battle","ex":{"en":"a memorial to those who fell in the two world wars","cn":"两次世界大战阵亡将士纪念碑"}},{"en":"to come quickly and suddenly","cn":"突然来到；突然出现","g":"[intransitive]","lab":"literary","sc":"happen/occur","ex":{"en":"A sudden silence fell.","cn":"突然一片鸦雀无声。"}},{"en":"to happen or take place","cn":"发生","g":"[intransitive]","sc":"happen/occur","ex":{"en":"My birthday falls on a Monday this year.","cn":"今年我的生日适逢星期一。"}},{"en":"to move in a particular direction or come in a particular position","cn":"（向某方向）移动；落（在某位置上）","g":"[intransitive]","sc":"happen/occur","ex":{"en":"My eye fell on (= I suddenly saw) a curious object.","cn":"我突然见到了一样奇怪的东西。"}},{"en":"to belong to a particular class, group or area of responsibility","cn":"属于（某类、群体、责任范围）","g":"[intransitive]","sc":"belong to group","ex":{"en":"Out of over 400 staff there are just seven that fall into this category.","cn":"400 多个职员中只有 7 人属于这一类。"}},{"en":"an act of falling","cn":"落下；下落；跌落；掉落","g":"[countable]","sc":"act of falling","ex":{"en":"I had a bad fall and broke my arm.","cn":"我重重地跌了一跤，摔断了手臂。"},"pos":"noun"},{"en":"an amount of snow, rain, rocks, etc. that falls or has fallen","cn":"（雪、雨、岩石等的）降落","g":"[countable]","sc":"of snow/rain/rocks","ex":{"en":"a heavy fall of snow","cn":"一场大雪"},"pos":"noun"},{"en":"the season of the year between summer and winter, when leaves change colour and the weather becomes colder","cn":"秋天；秋季","g":"[countable, uncountable]","lab":"North American English","sc":"autumn","ex":{"en":"in the fall of 2019","cn":"在 2019 年的秋天"},"pos":"noun"},{"en":"a decrease in size, number, rate or level","cn":"（大小）减小；（数量）减少；（比率、水平）降低","g":"[countable]","sc":"decrease","ex":{"en":"Share prices suffered a slight fall yesterday.","cn":"股票价格昨日微幅下挫。"},"pos":"noun"},{"en":"a loss of political, economic, etc. power or success; the loss or defeat of a city, country, etc. in war","cn":"（政权的）垮台；（经济的）崩溃；（城市、国家等的）沦陷，灭亡","g":"[singular]","sc":"defeat","ex":{"en":"the fall of the Roman Empire","cn":"罗马帝国的灭亡"},"pos":"noun"},{"en":"a situation in which a person, an organization, etc. loses the respect of other people because they have done something wrong","cn":"（威信的）骤降","g":"[singular]","sc":"loss of respect","ex":{"en":"the TV preacher’s spectacular fall from grace","cn":"电视布道者威信的遽降"},"pos":"noun"},{"en":"a large amount of water falling down from a height","cn":"瀑布","g":"[plural]","sc":"of water","ex":{"en":"The falls upstream are full of salmon.","cn":"上游瀑布一带盛产鲑鱼。"},"pos":"noun"},{"en":"the way in which something falls or happens","cn":"下落；发生","g":"[singular]","sc":"way something falls/happens","ex":{"en":"the fall of the dice","cn":"骰子的掷出"},"pos":"noun"},{"en":"the occasion when Adam and Eve did not obey God and had to leave the Garden of Eden","cn":"人类堕落（指亚当和夏娃违背上帝意旨而被迫离开伊甸园）","g":"[singular]","sc":"in Bible","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"落下;坠落;掉落","en":"If someone or something falls, they move quickly downwards onto or towards the ground, by accident or because of a natural force.","ex":{"en":"Her father fell into the sea after a massive heart attack","cn":"她父亲在一次严重的心脏病发作后坠入海中。"}},{"pos":"VERB 动词","cn":"摔倒;跌倒;倒塌","en":"If a person or structure that is standing somewhere falls, they move from their upright position, so that they are then lying on the ground.","ex":{"en":"The woman gripped the shoulders of her man to stop herself from falling","cn":"这个女人抓住丈夫的肩膀，以免摔倒。"}},{"pos":"VERB 动词","cn":"(雨或雪)落下,下落","en":"When rain or snow falls, it comes down from the sky.","ex":{"en":"Winds reached up to 100mph in some places with an inch of rain falling within 15 minutes.","cn":"风力在一些地方达到了每小时 100 英里，15 分钟内降雨量达一英寸。"}},{"pos":"VERB 动词","cn":"(常因疲乏)一头倒下，一下躺倒","en":"If you fall somewhere, you allow yourself to drop there in a hurried or disorganized way, often because you are very tired.","ex":{"en":"Totally exhausted, he tore his clothes off and fell into bed","cn":"他疲惫至极，扯下衣服，一头倒在床上。"}},{"pos":"VERB 动词","cn":"(数量)减少;(价值)下降;(力量)减弱","en":"If something falls, it decreases in amount, value, or strength.","ex":{"en":"Output will fall by 6%","cn":"产量将减少 6％。"}},{"pos":"VERB 动词","cn":"垮台;失势","en":"If a powerful or successful person falls, they suddenly lose their power or position.","ex":{"en":"There's a danger of the government falling because it will lose its majority","cn":"政府将因失去其占多数的优势而有倒台的危险。"}},{"pos":"VERB 动词","cn":"陷落;失守;(竞选)失利","en":"If a place falls in a war or election, an enemy army or a different political party takes control of it.","ex":{"en":"Croatian army troops retreated from northern Bosnia and the area fell to the Serbs","cn":"克罗地亚军队从波斯尼亚北部撤军后，该地区落入塞尔维亚人手里。"}},{"pos":"VERB 动词","cn":"战死;阵亡","en":"If someone falls in battle, they are killed.","ex":{"en":"Another wave of troops followed the first, running past those who had fallen.","cn":"又一批士兵跟着第一批士兵从阵亡者身边跑过。"}},{"pos":"V-LINK 连系动词","cn":"进入，陷入(某种状态)","en":"You can use fall to show that someone or something passes into another state. For example, if someone falls ill, they become ill, and if something falls into disrepair, it is then in a state of disrepair.","ex":{"en":"It is almost impossible to visit Florida without falling in love with the state","cn":"去佛罗里达观光而不爱上这个州几乎不可能。"}},{"pos":"VERB 动词","cn":"属于;被划分为","en":"If you say that something or someone falls into a particular group or category, you mean that they belong in that group or category.","ex":{"en":"The problems generally fall into two categories","cn":"问题大致分成两类。"}},{"pos":"VERB 动词","cn":"(责任或责备)由…承担，由…负责","en":"If the responsibility or blame for something falls on someone, they have to take the responsibility or the blame for it.","ex":{"en":"That responsibility falls on the local office of the United Nations High Commissioner for Refugees","cn":"那由联合国高级难民署的地方分部负责。"}},{"pos":"VERB 动词","cn":"(人群)变得(安静、悲哀或疲倦)","en":"If silence or a feeling of sadness or tiredness falls on a group of people, they become silent, sad, or tired.","ex":{"en":"The bus was stopped and silence fell on the passengers as the police checked identity cards.","cn":"公交车被拦住了，警察检查身份证时，乘客们鸦雀无声。"}},{"pos":"VERB 动词","cn":"(庆典或特别事件)在，适逢(某日)","en":"If a celebration or other special event falls on a particular day or date, it happens to be on that day or date.","ex":{"en":"...the oddly named Quasimodo Sunday which falls on the first Sunday after Easter.","cn":"适逢复活节后第一个星期天的名字古怪的“卸白衣主日”"}},{"pos":"VERB 动词","cn":"(光)射向;(影子)投在","en":"When light or shadow falls on something, it covers it.","ex":{"en":"Nancy, out of the corner of her eye, saw the shadow that suddenly fell across the doorway.","cn":"南希从眼角的余光里看见突然有个影子落在门道上。"}},{"pos":"VERB 动词","cn":"(头发或衣服)垂坠，下垂","en":"If someone's hair or a garment falls in a certain way, it hangs downwards in that way.","ex":{"en":"...a slender boy with black hair falling across his forehead.","cn":"一个身材颀长的男孩儿，黑发垂在额上"}},{"pos":"VERB 动词","cn":"(目光)落在…上;注意到","en":"If you say that someone's eyes fell on something, you mean they suddenly noticed it.","ex":{"en":"As he laid the flowers on the table, his eye fell upon a note in Grace's handwriting.","cn":"他把花放在桌上时，目光落在一张写有格雷斯笔迹的字条上。"}},{"pos":"VERB 动词","cn":"(夜晚或黑暗)降临，来临","en":"When night or darkness falls, night begins and it becomes dark.","ex":{"en":"As darkness fell outside, they sat down to eat at long tables.","cn":"屋外夜幕降临，他们坐到长桌旁开始吃饭。"}},{"pos":"N-PLURAL; N-IN-NAMES 复数名词；名称名词","cn":"瀑布","en":"You can refer to a waterfall as the falls .","ex":{"en":"...panoramic views of the falls.","cn":"瀑布的全景"}},{"pos":"N-VAR 可变名词","cn":"秋季;秋天","en":"Fall is the season between summer and winter when the weather becomes cooler.","ex":{"en":"He was elected judge in the fall of 1991","cn":"1991 年秋他当选为法官。"}},{"pos":"N-PROPER 专有名词","cn":"人类堕落(基督教中指亚当、夏娃违反戒律，被上帝逐出伊甸园)","en":"In the Christian religion, the Fall was the occasion when Adam and Eve sinned and God made them leave the Garden of Eden."},{"pos":"N-COUNT 可数名词","cn":"(摔跤中)双肩着地;(柔道中)体落","en":"In some sports such as judo and wrestling, a fall is the act of throwing or forcing your opponent to the floor."},{"pos":"VERB 动词","cn":"(板球中，三柱门)失陷(指击球员出局)","en":"In cricket, when a wicket falls, the team who are fielding get one of the batsmen out.","ex":{"en":"The last seven wickets fell for ten runs.","cn":"最后 7 次三柱门失陷得了10分。"}},{"pos":"PHRASE 短语","cn":"偶然打开;意外开启","en":"If something falls open, it opens accidentally.","ex":{"en":"By chance the book beside him fell open to St. Paul's warning to the Romans","cn":"他身旁的书偶然翻开到写着圣保罗对罗马人的告诫那页。"}},{"pos":"PHRASE 短语","cn":"卖力;煞费苦心;不遗余力","en":"If you say that people are falling over themselves to do something, you mean that they are very enthusiastic about doing it, and often that you disapprove of this.","ex":{"en":"Within days of his death those same people were falling over themselves to denounce him.","cn":"他尸骨未寒，还是那些人又大肆谴责起他来。"}},{"pos":"PHRASE 短语","cn":"fall to pieces (英国英语中作 fall to bits) 同 fall apart","en":"To fall to pieces, or in British English to fall to bits, means the same as to fall apart .","ex":{"en":"At that point the radio handset fell to pieces.","cn":"就在那一刻，无线电遥控器摔得粉碎。"}},{"pos":"","cn":"","en":"to fall on your feet→see: ; to fall foul of→see: ; to fall flat→see: ; to fall from grace→see: ; to fall into place→see: ; to fall short→see: ; to fall into the trap→see: ; to fall by the wayside→see: ;"},{"pos":"PHRASAL VERB 短语动词","cn":"散架;垮掉;摔碎","en":"If something falls apart, it breaks into pieces because it is old or badly made.","ex":{"en":"The work was never finished and bit by bit the building fell apart.","cn":"工程一直没有完工，于是楼一点点地坍塌了。"}},{"pos":"PHRASAL VERB 短语动词","cn":"(机构或体系)解散,瓦解","en":"If an organization or system falls apart, it becomes disorganized or unable to work effectively, or breaks up into its different parts.","ex":{"en":"Europe's monetary system is falling apart","cn":"欧洲货币体系正在走向瓦解。"}},{"pos":"PHRASAL VERB 短语动词","cn":"(情感上)崩溃，垮掉","en":"If you say that someone is falling apart, you mean that they are becoming emotionally disturbed and are unable to think calmly or to deal with the difficult or unpleasant situation that they are in.","ex":{"en":"I was falling apart. I wasn't getting any sleep.","cn":"我要崩溃了，我一直都没合眼。"}},{"pos":"PHRASAL VERB 短语动词","cn":"脱落;分离","en":"If something falls away from the thing it is attached to, it breaks off.","ex":{"en":"Officials say that one or two engines fell away from the plane shortly after takeoff.","cn":"官员们说飞机起飞后不久就有一两台引擎脱落了。"}},{"pos":"PHRASAL VERB 短语动词","cn":"(地面自某处)向下倾斜","en":"If you say that land falls away, you mean it slopes downwards from a particular point.","ex":{"en":"On either side of the tracks the ground fell away sharply.","cn":"跑道两侧都是很陡的斜坡。"}},{"pos":"PHRASAL VERB 短语动词","cn":"(程度)降低，减弱;(数量、规模)减少，减小","en":"If the degree, amount, or size of something falls away, it decreases.","ex":{"en":"His coalition may hold a clear majority but this could quickly fall away","cn":"他的联盟也许会占绝对多数，但这种优势可能会很快丧失。"}},{"pos":"PHRASAL VERB 短语动词","cn":"略微退后;稍稍后退","en":"If you fall back, you move backwards a short distance away from someone or something.","ex":{"en":"He fell back in embarrassment when he saw that Ross had no hair at all","cn":"看见罗斯的光头，他尴尬地后退了几步。"}},{"pos":"PHRASAL VERB 短语动词","cn":"(军队)撤退，后撤","en":"If an army falls back during a battle or war, it withdraws.","ex":{"en":"The Prussian garrison at Charleroi was falling back.","cn":"普鲁士驻沙勒罗瓦的部队正在撤退。"}},{"pos":"PHRASAL VERB 短语动词","cn":"落后;跟不上","en":"If you fall behind, you do not make progress or move forward as fast as other people.","ex":{"en":"Evans had rheumatic fever, missed school and fell behind","cn":"伊万斯得了风湿热，没去上课，功课也落下了。"}},{"pos":"PHRASAL VERB 短语动词","cn":"(使)不能按时完成(或交付)","en":"If you fall behind with something or let it fall behind, you do not do it or produce it when you should, according to an agreement or schedule.","ex":{"en":"He faces losing his home after falling behind with the payments","cn":"他没能按时付款，面临着失去房子的危险。"}},{"pos":"","cn":"","en":"→see: ;"},{"pos":"PHRASAL VERB 短语动词","cn":"(在…上)薄弱，不尽如人意","en":"If an argument, organization, or person falls down on a particular point, they are weak or unsatisfactory on that point.","ex":{"en":"Service was outstandingly friendly and efficient, falling down on only one detail","cn":"服务态度极佳，效率也蛮高，仅在一个小地方不尽人意。"}},{"pos":"PHRASAL VERB 短语动词","cn":"迷恋;爱上","en":"If you fall for someone, you are strongly attracted to them and start loving them.","ex":{"en":"He was fantastically handsome — I just fell for him right away.","cn":"他帅极了——我一下子就爱上了他。"}},{"pos":"PHRASAL VERB 短语动词","cn":"上…的当;受…的骗;对…信以为真","en":"If you fall for a lie or trick, you believe it or are deceived by it.","ex":{"en":"It was just a line to get you out here, and you fell for it!","cn":"那不过是为了骗你到这儿来的一句谎言，你居然信了！"}},{"pos":"PHRASAL VERB 短语动词","cn":"(屋顶、天花板)塌陷，坍塌","en":"If a roof or ceiling falls in, it collapses and falls to the ground.","ex":{"en":"Part of my bedroom ceiling has fallen in.","cn":"我卧室的天花板有些地方塌下来了。"}},{"pos":"PHRASAL VERB 短语动词","cn":"走在…的后面(或身边)","en":"If you fall in behind or beside someone who is walking along, you start walking behind them or beside them.","ex":{"en":"Prentice saw Goss fall in behind the informer.","cn":"普伦蒂斯看见戈斯走在密探身后。"}},{"pos":"PHRASAL VERB 短语动词","cn":"赞成，接受(思想、计划、体系)","en":"If you fall in with an idea, plan, or system, you accept it and do not try to change it.","ex":{"en":"Carmen's reluctance to fall in with Driver's plans led to trouble.","cn":"卡门不愿接受德赖弗的计划，由此引来了麻烦。"}},{"pos":"PHRASAL VERB 短语动词","cn":"与…来往密切","en":"If you fall in with someone, you become friends with them and start seeing them a lot.","ex":{"en":"At university, Taylor had fallen in with a small clique of literature students.","cn":"在大学里，泰勒曾经频繁参与一个文学小团体的活动。"}},{"pos":"PHRASAL VERB 短语动词","cn":"(从接合处)脱落，掉落","en":"If something falls off, it separates from the thing to which it was attached and moves towards the ground.","ex":{"en":"When your exhaust falls off, you have to replace it.","cn":"如果你的排气管脱落，应将其更换。"}},{"pos":"PHRASAL VERB 短语动词","cn":"(程度)降低，减弱;(数量、规模)减少","en":"If the degree, amount, or size of something falls off, it decreases.","ex":{"en":"Unemployment is rising again and retail buying has fallen off.","cn":"失业率再次上升，零售品购买量下降。"}},{"pos":"PHRASAL VERB 短语动词","cn":"(头发、牙齿)掉落，脱落","en":"If something such as a person's hair or a tooth falls out, it comes out.","ex":{"en":"Her hair started falling out as a result of radiation treatment.","cn":"由于放疗，她开始掉头发。"}},{"pos":"PHR-V-RECIP 相互动词短语","cn":"(与…)争吵，失和","en":"If you fall out with someone, you have an argument and stop being friendly with them. You can also say that two people fall out .","ex":{"en":"She fell out with her husband","cn":"她与丈夫闹翻了。"}},{"pos":"PHRASAL VERB 短语动词","cn":"(责任、职责、机会)落到…的头上;应由…做","en":"If a responsibility, duty, or opportunity falls to someone, it becomes their responsibility, duty, or opportunity.","ex":{"en":"He's been very unlucky that no chances have fallen to him.","cn":"他很不走运，机会一次也没有落到他头上。"}},{"pos":"PHRASAL VERB 短语动词","cn":"开始(做…)","en":"If someone falls to doing something, they start doing it.","ex":{"en":"When she had departed, they fell to fighting among themselves.","cn":"她走后，他们便互相打了起来。"}},{"pos":"","cn":"","en":"相关词组：fall about fall apart fall away fall back fall back on fall behind fall down fall for fall in fall into fall in with fall off fall on fall out fall over fall through fall to"}]},"examples":[{"en":"The houses fell away as we left the city.","cn":"随着我们离城市越来越远，房屋也逐渐在视线中消失了。"},{"en":"An expectant hush fell on the guests.","cn":"客人们即时安静了下来，期待着将要发生的事。"}]},"faithful":{"media":{"uk":"media/uk/faithful__gb_1.mp3","us":"media/us/faithful__us_1.mp3"},"oxford":{"phon":"ˈfeɪθfl","pos":"adjective","senses":[{"en":"staying with or supporting a particular person, organization or belief","cn":"忠实的；忠诚的","ex":{"en":"a faithful servant/friend/dog","cn":"忠诚的仆人／朋友／狗"}},{"en":"people who believe in a religion; strong supporters of a political party who will not change their views","cn":"（宗教的）信徒；（政党的）忠诚支持者","g":"[plural]","ex":{"en":"The president will keep the support of the party faithful.","cn":"总统将继续获得忠诚党员的拥护。"}},{"en":"not having a sexual relationship with anyone else","cn":"忠诚的；忠贞的","ex":{"en":"He had remained entirely faithful to his wife.","cn":"他对妻子一直绝对忠诚。"}},{"en":"true and accurate; not changing anything","cn":"如实的；丝毫不变的","ex":{"en":"a faithful copy/account/description","cn":"精确的副本；如实的叙述／描述"}},{"en":"able to be trusted; that you can rely on","cn":"可信任的；可信赖的","g":"[only before noun]","ex":{"en":"my faithful old car","cn":"我那可靠的老爷车"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"忠实的;忠诚的;忠贞不渝的","en":"Someone who is faithful to a person, organization, idea, or activity remains firm in their belief in them or support for them.","ex":{"en":"She had been faithful to her promise to guard this secret","cn":"她一直信守承诺，保守着这个秘密。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(对丈夫、妻子或恋人)忠诚的，忠贞的","en":"Someone who is faithful to their husband, wife, or lover does not have a sexual relationship with anyone else.","ex":{"en":"She insisted that she had remained faithful to her husband","cn":"她坚持说自己对丈夫一直是忠诚的。"}},{"pos":"N-PLURAL 复数名词","cn":"(宗教的)忠实信徒，虔诚信徒","en":"The faithful are the group of people who believe in a particular religion.","ex":{"en":"The faithful revered him then as a prophet.","cn":"那时，信徒们尊他为先知。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(叙述、翻译或抄本)如实的，忠实原文的","en":"A faithful account, translation, or copy of something represents or reproduces the original accurately.","ex":{"en":"Colin Welland's screenplay is faithful to the novel.","cn":"科林·韦兰的电影剧本忠实于原小说。"}},{"pos":"PHRASE 短语","cn":"(尤指值得信赖的)旧有物品，老牌产品","en":"You can refer to something that has been used or has existed for a long time as an old faithful, especially when it is something you can rely on.","ex":{"en":"We tested a selection of vacuum cleaners, from old faithfuls to those with the latest features.","cn":"我们测试了各种真空吸尘器，从值得信赖的老牌子到有着最新特色的产品，不一而足。"}}]},"examples":[{"en":"She was rewarded for her 40 years' faithful service with the company.","cn":"她为公司忠诚服务了 40 年，因而获得奖赏。"},{"en":"The president will keep the support of the party faithful.","cn":"总统将继续获得忠诚党员的拥护。"}]},"fair":{"media":{"uk":"media/uk/fair__gb_1.mp3","us":"media/us/fair__us_1.mp3"},"oxford":{"phon":"feə(r)","pos":"adjective","senses":[{"en":"acceptable and appropriate in a particular situation","cn":"可以接受的；合乎情理的；公道的","lab":"especially British English","sc":"acceptable/appropriate","ex":{"en":"a fair deal/wage/price","cn":"公平交易；合理的工资；公道的价格"}},{"en":"treating everyone equally and according to the rules or law","cn":"（按法律、规定）平等待人的，秉公办事的，公正的","sc":"treating people equally","ex":{"en":"She has always been scrupulously fair.","cn":"她总是一丝不苟地秉公办事。"}},{"en":"pale in colour","cn":"浅色的；白皙的","sc":"hair/skin","ex":{"en":"a fair complexion","cn":"白皙的肤色"}},{"en":"quite large in number, size or amount","cn":"（数量、大小）相当大的","g":"[only before noun]","sc":"quite large","ex":{"en":"A fair number of people came along.","cn":"有相当多的人来了。"}},{"en":"quite good","cn":"相当好","lab":"especially British English","sc":"quite good","ex":{"en":"There's a fair chance that we might win this time.","cn":"这次我们可能胜算很大。"}},{"en":"bright and not raining","cn":"晴朗的","sc":"weather","ex":{"en":"It was a fair and breezy day.","cn":"这是一个风和日丽、风和日丽的日子。"}},{"en":"not too strong and blowing in the right direction","cn":"顺风的","lab":"literary","sc":"weather","ex":{"en":"They set sail with the first fair wind.","cn":"顺风一起他们就扬帆出航了。"}},{"en":"beautiful","cn":"美丽","lab":"literary or old use","sc":"beautiful","ex":{"en":"a fair maiden","cn":"美丽的少女"}},{"en":"according to the rules; in a way that is considered to be acceptable and appropriate","cn":"按照规则；公正地；公平合理地","ex":{"en":"Come on, you two, fight fair!","cn":"得了，你们俩，要按规则比赛！"},"pos":"adverb"},{"en":"a type of entertainment in a field or park at which people can ride on large machines and play games to win prizes","cn":"露天游乐场","lab":"British English also","sc":"entertainment","ex":{"en":"Let's take the kids to the fair.","cn":"咱们带孩子们去游乐场吧。"},"pos":"noun"},{"en":"a type of entertainment in a field or park at which farm animals and products are shown and take part in competitions","cn":"（评比农畜产品的）集市","lab":"North American English","sc":"entertainment","ex":{"en":"the county/state fair","cn":"县／州农畜产品集市"},"pos":"noun"},{"en":"an outdoor entertainment at which people can play games to win prizes, buy food and drink, etc., usually arranged to make money for a special purpose","cn":"露天游乐会；义卖游乐会","lab":"all British English","sc":"entertainment","pos":"noun"},{"en":"an event at which people, businesses, etc. show and sell their goods","cn":"商品交易会；展销会","sc":"business","ex":{"en":"a world trade fair","cn":"世界交易会"},"pos":"noun"},{"en":"(in the past) a market at which animals were sold","cn":"（旧时）牲畜市场","lab":"British English","sc":"animal market","ex":{"en":"a horse fair","cn":"马市"},"pos":"noun"},{"en":"an event at which people who are looking for jobs can get information about companies who might employ them","cn":"职业介绍会；就业展览会","sc":"jobs","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"合理的;公平的;公正的","en":"Something or someone that is fair is reasonable, right, and just.","ex":{"en":"It didn't seem fair to leave out her father","cn":"将她父亲排除在外似乎不公平。"}},{"pos":"ADJ 形容词","cn":"(数量、程度、尺寸或距离)相当多(或大、长)的","en":"A fair amount, degree, size, or distance is quite a large amount, degree, size, or distance.","ex":{"en":"My neighbours across the street travel a fair amount","cn":"我街对面的邻居游历甚广。"}},{"pos":"ADJ 形容词","cn":"(猜测、想法)正确的，合理的","en":"A fair guess or idea about something is one that is likely to be correct.","ex":{"en":"It's a fair guess to say that the damage will be extensive","cn":"说损失会很严重想必猜得不错。"}},{"pos":"ADJ 形容词","cn":"(水平、质量)一般的，尚可的，不错的","en":"If you describe someone or something as fair, you mean that they are average in standard or quality, neither very good nor very bad.","ex":{"en":"Reimar had a fair command of English.","cn":"赖马尔的英语说得还不错。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(头发)浅色的，淡色的","en":"Someone who is fair, or who has fair hair, has light-coloured hair.","ex":{"en":"Both children were very like Robina, but were much fairer than she was.","cn":"两个孩子都很像罗比娜，但头发颜色比她浅得多。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(皮肤)白皙的","en":"Fair skin is very pale and usually burns easily.","ex":{"en":"It's important to protect my fair skin from the sun.","cn":"保护我白皙的皮肤不受日晒是很紧要的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(天气)晴朗的，晴好的","en":"When the weather is fair, it is quite sunny and not raining.","ex":{"en":"Weather conditions were fair.","cn":"天气晴好。"}},{"pos":"N-COUNT 可数名词","cn":"集市;市场","en":"A county, state, or country fair is an event where there are, for example, displays of goods and animals, and amusements, games, and competitions."},{"pos":"N-COUNT 可数名词","cn":"同 funfair","en":"A fair is the same as a funfair ."},{"pos":"N-COUNT 可数名词","cn":"(尤指某类商品的)展销会,交易会","en":"A fair is an event at which people display and sell goods, especially goods of a particular type.","ex":{"en":"...an antiques fair.","cn":"古玩交易会"}},{"pos":"PHRASE 短语","cn":"说句公道话;平心而论","en":"You use fair in expressions such as to be fair and let's be fair when you want to add a favourable comment about someone or something that you have just mentioned and to correct a false impression that you might have given.","ex":{"en":"To be fair, the team is young and not yet settled","cn":"说句公道话，这个队还年轻，还没有成型。"}},{"pos":"PHRASE 短语","cn":"(说法、决定或行为)有些道理，说得过去","en":"You use fair enough when you want to say that a statement, decision, or action seems reasonable to a certain extent, but that perhaps there is more to be said or done.","ex":{"en":"If you don't like it, fair enough, but that's hardly a justification to attack the whole thing","cn":"如果你不喜欢，这说得过去，但把它批得一无是处就没什么道理了。"}},{"pos":"CONVENTION 惯用语","cn":"有道理;说得对;敢情好","en":"You say fair enough to acknowledge what someone has just said and to indicate that you understand it.","ex":{"en":"'I'm taking it to our local police station.' — 'Oh right, fair enough.'","cn":"“我要告到本地警察局。”——“呵，对，干得有理。”"}},{"pos":"PHRASE 短语","cn":"做事光明正大;行事正直","en":"If you say that someone plays fair, you mean that they behave or act in a reasonable and honest way.","ex":{"en":"The government is not playing fair, one union official told me.","cn":"政府在搞鬼，一位工会官员告诉我。"}},{"pos":"PHRASE 短语","cn":"可以说;应该说","en":"You use fair in expressions such as It would be fair to say in order to introduce a statement which you believe to be true and reasonable.","ex":{"en":"It would be fair to say he had one or two unhappy moments out there","cn":"可以这么说，他在那里有过一两次不愉快。"}},{"pos":"PHRASE 短语","cn":"光明正大地;诚实地","en":"If you say that someone won a competition fair and square, you mean that they won honestly and without cheating.","ex":{"en":"There are no excuses. We were beaten fair and square.","cn":"没话说，我们是给正大光明地打败的。"}},{"pos":"","cn":"","en":"a fair crack of the whip→see: ;"}]},"examples":[{"en":"It's only fair to add that they were not told about the problem until the last minute.","cn":"要补充说明以下情况才合理，即他们是最后一刻才获知这个问题。"},{"en":"Fair's fair — you can't expect them to cancel everything just because you can't make it.","cn":"彼此都要公平，不可能就因为你不能出席就指望他们取消一切。"}]},"falter":{"media":{"uk":"media/uk/falter__gb_1.mp3","us":"media/us/falter__us_1.mp3"},"oxford":{"phon":"ˈfɔːltə(r)","pos":"verb","senses":[{"en":"to become weaker or less effective","cn":"衰弱；衰退；衰落","g":"[intransitive]","ex":{"en":"The economy shows no signs of faltering.","cn":"经济没有衰退的迹象。"}},{"en":"to speak in a way that shows that you are not confident","cn":"（嗓音）颤抖；结巴地说；支吾其词","g":"[intransitive, transitive]","ex":{"en":"His voice faltered as he began his speech.","cn":"他开始演讲时说话结结巴巴。"}},{"en":"to walk or behave in a way that shows that you are not confident","cn":"蹒跚；摇晃；犹豫；畏缩","g":"[intransitive]","ex":{"en":"She walked up to the platform without faltering.","cn":"她健步走上了讲台。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"衰退;停步不前","en":"If something falters, it loses power or strength in an uneven way, or no longer makes much progress.","ex":{"en":"Normal life is at a standstill, and the economy is faltering","cn":"正常生活陷于瘫痪，经济止步不前。"}},{"pos":"VERB 动词","cn":"(因不自信)畏缩不前，开始出错;犹疑","en":"If you falter, you lose your confidence and stop doing something or start making mistakes.","ex":{"en":"I have not faltered in my quest for a new future","cn":"我对新的未来的追求从未动摇过。"}},{"pos":"VERB 动词","cn":"(说话)迟疑，吞吞吐吐，支吾","en":"If your voice falters when you are speaking, you hesitate or pause, because you are unsure about what you are saying or are upset.","ex":{"en":"Her voice faltered and she had to stop a moment to control it.","cn":"她声音发颤，只好稍作停顿以有所控制。"}}]},"examples":[{"en":"His voice faltered as he began his speech.","cn":"他开始演讲时说话结结巴巴。"},{"en":"The economy shows no signs of faltering.","cn":"经济没有衰退的迹象。"}]},"fare":{"media":{"uk":"media/uk/fare__gb_1.mp3","us":"media/us/fare__us_1.mp3"},"oxford":{"phon":"feə(r)","pos":"noun","senses":[{"en":"the money that you pay to travel by bus, plane, taxi, etc.","cn":"车费；飞机票价；船费","g":"[countable, uncountable]","ex":{"en":"bus/taxi fares","cn":"公共汽车费；出租汽车费"}},{"en":"a passenger in a taxi","cn":"出租车乘客","g":"[countable]","ex":{"en":"The taxi driver picked up a fare at the station.","cn":"出租车司机在车站接了一名乘客。"}},{"en":"a range of food of a particular type","cn":"饭菜；食物","g":"[uncountable]","ex":{"en":"The restaurant provides good traditional fare.","cn":"这家餐厅提供传统风味佳馔。"}},{"en":"something that is offered to the public, especially as a form of entertainment","cn":"（尤指娱乐用的）产品，出品","g":"[uncountable]","ex":{"en":"This movie is perfect family fare.","cn":"这部电影是完美的家庭片。"}},{"en":"to be successful/unsuccessful in a particular situation","cn":"成功（或不成功、更好等）","ex":{"en":"The party fared very badly in the last election.","cn":"该党上次竞选情况很糟。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"旅费;路费;车费","en":"A fare is the money that you pay for a journey that you make, for example, in a bus, train, or taxi.","ex":{"en":"He could barely afford the railway fare.","cn":"他几乎买不起火车票。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(饭店或咖啡店的)餐点，饮食，饭菜","en":"The fare at a restaurant or caff is the type of food that is served there.","ex":{"en":"The fare has much improved since Hugh has taken charge of the kitchen.","cn":"自从休主厨以来，伙食大为改进。"}},{"pos":"VERB 动词","cn":"进展;进行","en":"If you say that someone or something fares well or badly, you are referring to the degree of success they achieve in a particular situation or activity.","ex":{"en":"It is unlikely that the marine industry will fare any better in September","cn":"海运业在9月份不可能有好转。"}}]},"examples":[{"en":"The taxi driver picked up a fare at the station.","cn":"计程车司机在车站接了一名乘客。"},{"en":"The restaurant provides good traditional fare.","cn":"这家餐厅提供传统风味佳馔。"}]},"failure":{"media":{"uk":"media/uk/failure__gb_1.mp3","us":"media/us/failure__us_1.mp3"},"oxford":{"phon":"ˈfeɪljə(r)","pos":"noun","senses":[{"en":"lack of success in doing or achieving something","cn":"失败","g":"[uncountable, countable]","sc":"not successful","ex":{"en":"The success or failure of the plan depends on you.","cn":"这项计划的成败取决于你。"}},{"en":"a person or thing that is not successful","cn":"失败的人（或事物）","g":"[countable]","sc":"not successful","ex":{"en":"The whole thing was a complete failure.","cn":"整个事情彻底失败了。"}},{"en":"an act of not doing something, especially something that you are expected to do","cn":"未做，未履行（应做之事）","g":"[uncountable, countable]","sc":"not doing something","ex":{"en":"Failure to comply with the regulations will result in prosecution.","cn":"不遵守规章制度将被起诉。"}},{"en":"the state of not working correctly or as expected; an occasion when this happens","cn":"故障；失灵","g":"[uncountable, countable]","sc":"of machine/part of body","ex":{"en":"patients suffering from heart/kidney/liver failure","cn":"患心力／肾／肝衰竭的病人"}},{"en":"a situation in which a business has to close because it is not successful","cn":"倒闭","g":"[countable, uncountable]","sc":"of business","ex":{"en":"There has been an alarming increase in business failures.","cn":"企业倒闭数字的上升令人担忧。"}},{"en":"a situation in which crops do not grow correctly and do not produce food","cn":"歉收","g":"[uncountable, countable]","sc":"of crop/harvest","ex":{"en":"Bad weather has resulted in crop failure.","cn":"恶劣的天气导致农作物歉收。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"失败;不成功","en":"Failure is a lack of success in doing or achieving something, especially in relation to a particular activity.","ex":{"en":"This policy is doomed to failure","cn":"这项政策注定会失败。"}},{"pos":"N-COUNT 可数名词","cn":"失败的事;败绩","en":"If something is a failure, it is not a success.","ex":{"en":"The marriage was a failure and they both wanted to be free of it","cn":"他们的婚姻很失败，两人都想摆脱它。"}},{"pos":"N-COUNT 可数名词","cn":"失败者;一事无成的人","en":"If you say that someone is a failure, you mean that they have not succeeded in a particular activity, or that they are unsuccessful at everything they do.","ex":{"en":"Elgar received many honors and much acclaim and yet he often considered himself a failure","cn":"人们对埃尔加赞誉有加，但他却常觉得自己是个失败者。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"没做到;不履行","en":"Your failure to do a particular thing is the fact that you do not do it, even though you were expected to do it.","ex":{"en":"She accused the Foreign Office of disgraceful failure to support British citizens arrested overseas.","cn":"她指责说，外交部未能给在海外被捕的英国公民提供支持是可耻的。"}},{"pos":"N-VAR 可变名词","cn":"(机器的)故障，失灵;(身体机能的)衰竭","en":"If there is a failure of something, for example a machine or part of the body, it goes wrong and stops working or developing properly.","ex":{"en":"There were also several accidents mainly caused by engine failures on take-off","cn":"还有几次事故主要是起飞时引擎出现故障造成的。"}},{"pos":"N-VAR 可变名词","cn":"破产;倒闭","en":"If there is a failure of a business or bank, it is no longer able to continue operating.","ex":{"en":"Business failures rose 16% last month.","cn":"上个月倒闭公司的数量上升了 16％。"}},{"pos":"N-VAR 可变名词","cn":"缺乏;不足;不够","en":"If you say that someone has a failure of a particular quality or ability, you mean that they do not have enough of it.","ex":{"en":"There is, too, a simple failure of imagination","cn":"还有，就是纯粹缺乏想象力。"}}]},"examples":[{"en":"The cause of the crash was given as engine failure.","cn":"撞车事故的原因被认定是发动机故障。"},{"en":"She is still coming to terms with the failure of her marriage.","cn":"她还在努力适应婚姻失败的事实。"}]},"familiarity":{"media":{"uk":"media/uk/familiarity__gb_1.mp3","us":"media/us/familiarity__us_1.mp3"},"oxford":{"phon":"fəˌmɪliˈærəti","pos":"noun","senses":[{"en":"the state of knowing somebody/something well; the state of recognizing somebody/something","cn":"熟悉；通晓；认识","ex":{"en":"His familiarity with the language helped him enjoy his stay.","cn":"他通晓这种语言，所以逗留期间过得很惬意。"}},{"en":"a friendly informal manner","cn":"友好随便；亲近","ex":{"en":"She addressed me with an easy familiarity that made me feel at home.","cn":"她和我谈话亲切随和，使我不感到拘束。"}}]},"collins":{"senses":[{"pos":"PHRASE 短语","cn":"亲密生嫌隙；亲不敬，熟生蔑","en":"Familiarity is used especially in the expression familiarity breeds contempt to say that if you know a person or situation very well, you can easily lose respect for that person or become careless in that situation.","ex":{"en":"Familiarity with evil breeds not contempt but acceptance.","cn":"对罪恶熟悉之后，生出的不是蔑视，而是习以为常。"}}]},"examples":[{"en":"His familiarity with the language helped him enjoy his stay.","cn":"他通晓这种语言，所以逗留期间过得很惬意。"},{"en":"She addressed me with an easy familiarity that made me feel at home.","cn":"她和我谈话亲切随和，使我不感到拘束。"}]},"fame":{"media":{"uk":"media/uk/fame__gb_1.mp3","us":"media/us/fame__us_1.mp3"},"oxford":{"phon":"feɪm","pos":"noun","senses":[{"en":"the state of being known and talked about by many people","cn":"名声；声誉；名气","ex":{"en":"to achieve/win instant fame","cn":"一夜成名"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"声誉;名望","en":"If you achieve fame, you become very well-known. claim to fame→see: ;","ex":{"en":"At the height of his fame, his every word was valued","cn":"在他声名鼎盛之时，他的每句话都受到重视。"}}]},"examples":[{"en":"Andrew Lloyd Webber of ‘Evita’ fame (= famous for ‘Evita’)","cn":"以《埃维塔》成名的安德鲁 · 劳埃德 · 韦伯"},{"en":"The town's only claim to fame is that there was once a riot there.","cn":"这个镇唯一出名之处就是那里有过一次暴乱。"}]},"fascinated":{"media":{"uk":"media/uk/fascinated__gb_1.mp3","us":"media/us/fascinated__us_1.mp3"},"oxford":{"phon":"ˈfæsɪneɪtɪd","pos":"adjective","senses":[{"en":"very interested","cn":"入迷的；极感兴趣的","ex":{"en":"The children watched, fascinated, as the picture began to appear.","cn":"电影开始以后孩子们入迷地观看着。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极感兴趣的;入迷的","en":"If you are fascinated by something, you find it very interesting and attractive, and your thoughts tend to concentrate on it.","ex":{"en":"I sat on the stairs and watched, fascinated","cn":"我坐在楼梯上出神地观望。"}}]},"examples":[{"en":"They were fascinated to see that it was similar to one they had at home.","cn":"他们发现这个和他们家中的那个相似，极感兴趣。"},{"en":"The children watched, fascinated, as the picture began to appear.","cn":"电影开始以后孩子们入迷地观看着。"}]},"fairy":{"oxford":{"phon":"ˈfeəri","pos":"noun","senses":[{"en":"(in stories) a creature like a small person, who has magic powers","cn":"（故事中的）小仙人，仙子，小精灵","ex":{"en":"a good/wicked fairy","cn":"善良的仙子；邪恶的精灵"}},{"en":"an offensive word for a gay man","cn":"兔子（男同性恋者）","lab":"taboo, offensive, slang，，，，"},{"en":"a British make of liquid soap used for washing dishes, etc. and often advertised as lasting twice as long as other brands","cn":"Fairy 牌洗洁精（英国品牌的餐具清洁剂，常以使用时间比其他品牌长一倍为卖点作宣传）"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"仙人;小精灵","en":"A fairy is an imaginary creature with magical powers. Fairies are often represented as small people with wings."},{"pos":"N-COUNT 可数名词","cn":"兔子(指男同性恋者)","en":"If someone describes a man as a fairy, they mean that he is a homosexual and they disapprove of this."}]},"media":{"uk":"media/uk/fairy__gb_1.mp3","us":"media/us/fairy__us_1.mp3"},"examples":[{"en":"a good/wicked fairy","cn":"善良的仙子；邪恶的精灵"}]},"farmhand":{"media":{"uk":"media/uk/farmhand__gb_1.mp3","us":"media/us/farmhand__us_1.mp3"},"oxford":{"phon":"ˈfɑːmhænd","pos":"noun","senses":[{"en":"a person who works for a farmer","cn":"农场工人"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"农场工人","en":"A farmhand is a person who is employed to work on a farm."}]}},"fastens":{"lemma":"fasten"},"far-off":{"oxford":{"phon":"ˈfɑːr ɒf","pos":"adjective","senses":[{"en":"a long distance away","cn":"遥远的","ex":{"en":"a far-off land","cn":"一个遥远的国度"}},{"en":"a long time ago","cn":"很久以前的；久远的","ex":{"en":"memories of those far-off days","cn":"久远往昔的回忆"}}]},"media":{"uk":"media/uk/far_off_1_gb_1.mp3","us":"media/us/far_off_1_us_1.mp3"},"examples":[{"en":"a far-off land","cn":"一个遥远的国度"},{"en":"memories of those far-off days","cn":"久远往昔的回忆"}]},"family":{"media":{"uk":"media/uk/family__gb_1.mp3","us":"media/us/family__us_1.mp3"},"oxford":{"phon":"ˈfæməli","pos":"noun","senses":[{"en":"a group consisting of one or two parents and their children","cn":"家，家庭（包括父母一方或双方与子女）","g":"[countable + singular or plural verb]","ex":{"en":"I introduced Neil to the other members of my family.","cn":"我把尼尔介绍给我家里的其他成员。"}},{"en":"a group consisting of one or two parents, their children and close relations","cn":"（大）家庭（包括父母一方或双方与子女、近亲）；亲属","g":"[countable + singular or plural verb, uncountable]","lab":"informal","ex":{"en":"All our family came to Grandad's eightieth birthday party.","cn":"我们所有亲属都来参加了祖父的八十寿宴。"}},{"en":"all the people who are related to each other, including those who are now dead","cn":"家族","g":"[countable + singular or plural verb]","ex":{"en":"Some families have farmed in this area for hundreds of years.","cn":"有些家族在这个地区务农有几百年了。"}},{"en":"a couple’s or a person’s children, especially young children","cn":"子女；（尤指）年幼子女","g":"[countable + singular or plural verb, uncountable]","lab":"especially US English","ex":{"en":"They have a large family.","cn":"他们子女成群。"}},{"en":"a group into which animals, plants, etc. that have similar characteristics are divided, smaller than an order and larger than a genus","cn":"（动植物等分类的）科","g":"[countable]","ex":{"en":"Lions belong to the cat family.","cn":"狮属于猫科。"}},{"en":"a group of related languages","cn":"语系","ex":{"en":"the Germanic family of languages","cn":"日耳曼语系"}},{"en":"connected with the family or a particular family","cn":"家庭的","ex":{"en":"family life","cn":"家庭生活"},"pos":"adjective"},{"en":"owned by a family","cn":"一家所有的","ex":{"en":"They had to sell the family home.","cn":"他们不得不卖掉家里的房子。"},"pos":"adjective"},{"en":"suitable for all members of a family, both adults and children","cn":"适合全家人的","ex":{"en":"a family show","cn":"家庭节目"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"家;家庭;家族","en":"A family is a group of people who are related to each other, especially parents and their children.","ex":{"en":"There's room in there for a family of five","cn":"那儿能住下五口之家。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"子女;孩子","en":"When people talk about a family, they sometimes mean children.","ex":{"en":"They decided to start a family.","cn":"他们决定要孩子。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"祖先;祖辈","en":"When people talk about their family, they sometimes mean their ancestors.","ex":{"en":"Her family came to Los Angeles at the turn of the century.","cn":"她的祖先在世纪之交时来到洛杉矶。"}},{"pos":"ADJ 形容词","cn":"家族的;家庭的;家里的","en":"You can use family to describe things that belong to a particular family.","ex":{"en":"He returned to the family home","cn":"他回到自己家里。"}},{"pos":"ADJ 形容词","cn":"全家共用的;全家共享的","en":"You can use family to describe things that are designed to be used or enjoyed by both parents and children.","ex":{"en":"It had been designed as a family house","cn":"这房子的设计适合一家老小共同居住。"}},{"pos":"N-COUNT 可数名词","cn":"(动植物的)科","en":"A family of animals or plants is a group of related species.","ex":{"en":"...foods in the cabbage family, such as Brussels sprouts.","cn":"抱子甘蓝之类的十字花科食物"}}]},"examples":[{"en":"All our family came to Grandad's eightieth birthday party.","cn":"我们所有亲属都来参加了祖父的八十寿宴。"},{"en":"Some families have farmed in this area for hundreds of years.","cn":"有些家族在这个地区务农有几百年了。"}]},"favourite":{"media":{"uk":"media/uk/favourite__gb_1.mp3","us":"media/us/favourite__us_1.mp3"},"oxford":{"phon":"ˈfeɪvərɪt","pos":"verb","senses":[{"en":"to show that you like something that somebody has put on a social media site","cn":"特别喜爱的人（或事物）","ex":{"en":"It wasn't long until their original post was favourited over 1 200 times.","cn":"没过多久，他们的原创帖子就被点赞了 1 200 多次。"}},{"en":"to save the address of a website or other online data so that you can easily find it again","cn":"（收藏应用程序或网址的）我的最爱，收藏夹","ex":{"en":"The ‘Favourites’ tab lets you access places you've favourited.","cn":"“收藏夹”选项卡可让您访问您收藏的地方。"}},{"en":"liked more than others of the same kind","cn":"特别受喜爱的","ex":{"en":"It's one of my favourite movies.","cn":"这是我特别喜欢的电影之一。"},"pos":"adjective"},{"en":"a person or thing that you like more than the others of the same type","cn":"特别喜爱的人（或事物）","ex":{"en":"Which one's your favourite?","cn":"你最喜欢哪一个？"},"pos":"noun"},{"en":"a person who is liked better by somebody and receives better treatment than others","cn":"受宠的人；得到偏爱的人","ex":{"en":"She loved all her grandchildren but Ann was her favourite.","cn":"她爱所有的孙儿孙女，但最宠安。"},"pos":"noun"},{"en":"a record of a section of an app or the address of a website that enables you to find it quickly","cn":"（收藏应用程序或网址的）我的最爱，收藏夹","ex":{"en":"Add the website as a favourite.","cn":"将这个网站加到收藏夹。"},"pos":"noun"},{"en":"the horse, runner, team, etc. that is expected to win","cn":"（比赛中）最有望获胜者","ex":{"en":"The favourite came third.","cn":"那个有望夺魁者得了第三名。"},"pos":"noun"},{"en":"the person who is expected by most people to get a particular job or position","cn":"（取得职位等的）最有希望者","ex":{"en":"She's the favourite for the job.","cn":"她最有希望得到这份工作。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"最喜爱的;最喜欢的","en":"Your favourite thing or person of a particular type is the one you like most.","ex":{"en":"...a bottle of his favourite champagne","cn":"一瓶他最喜爱的香槟"}},{"pos":"N-COUNT 可数名词","cn":"受宠的人;宠儿;亲信","en":"If you describe one person as the favourite of another, you mean that the second person likes the first person a lot and treats them with special kindness.","ex":{"en":"...Robert Carr, Earl of Somerset, a favourite of King James I","cn":"罗伯特·卡尔——萨默塞特伯爵，国王詹姆斯一世的亲信"}},{"pos":"N-COUNT 可数名词","cn":"夺标热门;夺冠热门","en":"The favourite in a race or contest is the competitor that is expected to win. In a team game, the team that is expected to win is referred to as the favourites .","ex":{"en":"The Belgian Cup has been won by the favourites F.C. Liege.","cn":"比利时杯被夺冠热门列日队夺得。"}}]},"examples":[{"en":"The programme has become a firm favourite with young people.","cn":"这个节目已着实赢得了年轻人的喜爱。"},{"en":"Her horse is the hot favourite for the race.","cn":"她的马在这次赛马中夺魁的呼声最高。"}]},"fat":{"media":{"uk":"media/uk/fat__gb_1.mp3","us":"media/us/fat__us_1.mp3"},"oxford":{"phon":"fæt","pos":"adjective","senses":[{"en":"having too much flesh on it and weighing too much","cn":"肥的；肥胖的","ex":{"en":"a big fat man/woman","cn":"大胖男人／女人"}},{"en":"containing a lot of fat","cn":"肥的；多脂肪的","ex":{"en":"fat bacon/sausages","cn":"肥培根肉；肥香肠"}},{"en":"thick or wide","cn":"厚的；宽大的","ex":{"en":"a fat volume on American history","cn":"厚厚的一册美国史"}},{"en":"large in quantity; worth a lot of money","cn":"大量的；值钱的","g":"[only before noun]","lab":"informal","ex":{"en":"a fat sum/profit","cn":"一大笔款子；丰厚的利润"}},{"en":"a white or yellow substance in the bodies of animals and humans, stored under the skin","cn":"脂肪；肥肉","g":"[uncountable]","lab":"British English","ex":{"en":"excess body fat","cn":"多余的体内脂肪"},"pos":"noun"},{"en":"a solid or liquid substance from animals or plants, treated so that it becomes pure for use in cooking","cn":"（烹调用的）动植物油","g":"[countable, uncountable]","ex":{"en":"Cook the meat in shallow fat.","cn":"用少许油煎肉。"},"pos":"noun"},{"en":"animal and vegetable fats, when you are thinking of them as part of what a person eats","cn":"（人体摄入的动植物）脂肪","g":"[countable, uncountable]","ex":{"en":"You should cut down on fats and carbohydrates.","cn":"你应该减少摄入脂肪和碳水化合物。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人或动物)肥胖的，肥的","en":"If you say that a person or animal is fat, you mean that they have a lot of flesh on their body and that they weigh too much. You usually use the word fat when you think that this is a bad thing.","ex":{"en":"I could eat what I liked without getting fat","cn":"我怎么吃都不胖。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(动物或人的)肥肉,脂肪","en":"Fat is the extra flesh that animals and humans have under their skin, which is used to store energy and to help keep them warm.","ex":{"en":"Because you're not burning calories, everything you eat turns to fat.","cn":"由于没有消耗卡路里，你吃的所有东西都会变成脂肪。"}},{"pos":"N-MASS 物质名词","cn":"(烹饪用的)动植物油","en":"Fat is a solid or liquid substance obtained from animals or vegetables, which is used in cooking.","ex":{"en":"When you use oil or fat for cooking, use as little as possible.","cn":"烹调时不论是植物油还是动物油，都要尽量少用。"}},{"pos":"N-MASS 物质名词","cn":"(食物中的)脂肪","en":"Fat is a substance contained in foods such as meat, cheese, and butter which forms an energy store in your body.","ex":{"en":"An easy way to cut the amount of fat in your diet is to avoid eating red meats","cn":"减少饮食中脂肪摄入量的简单方法就是避免吃红肉。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(尤指书)厚的，宽的","en":"A fat object, especially a book, is very thick or wide.","ex":{"en":"...'Europe in Figures', a fat book published on September 22nd","cn":"9 月 22 日出版的大部头书《数说欧洲》"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(利润或费用)巨大的，丰厚的","en":"A fat profit or fee is a large one.","ex":{"en":"They are set to make a big fat profit.","cn":"他们下定决心要大赚一笔。"}},{"pos":"PHRASE 短语","cn":"可能性不大;无甚可能","en":"If you say that there is fat chance of something happening, you mean that you do not believe that it will happen.","ex":{"en":"'Would your car be easy to steal?' — 'Fat chance. I've got a device that shuts down the gas and ignition.'","cn":"“你的汽车容易被盗吗？”——“不太可能。有个装置，可关闭油门和点火开关。”"}},{"pos":"PHRASE 短语","cn":"(靠…)发财，致富，大发横财，肥起来","en":"If you say that a person or organization has grown fat on something, you mean that they have become very rich as a result of it.","ex":{"en":"Liverpool grew fat on the basis of the slave trade.","cn":"利物浦是靠奴隶贸易肥起来的。"}},{"pos":"PHRASE 短语","cn":"无济于事;于事无补;毫无用处","en":"If you say that something is a fat lot of good or a fat lot of help, you are saying rudely that it is no good or no help at all.","ex":{"en":"'I think we should go in and hammer them.' — 'And a fat lot of good that would do us.'","cn":"“我觉得我们应该进去把他们狠揍一顿。”——“那对我们有个屁用。”"}}]},"examples":[{"en":"‘They might let us in without tickets.’ ‘Fat chance of that!’ “","cn":"他们也许会让我们免票入场。” “别痴心妄想了！”"},{"en":"Paul can't drive so he was a fat lot of use when I broke my arm.","cn":"保罗不会开车，所以我手臂骨折时他一点忙也没帮上。"}]},"facility":{"media":{"uk":"media/uk/facility__gb_1.mp3","us":"media/us/facility__us_1.mp3"},"oxford":{"phon":"fəˈsɪləti","pos":"noun","senses":[{"en":"buildings, services, equipment, etc. that are provided for a particular purpose","cn":"设施；设备","g":"[plural]","ex":{"en":"leisure/sports facilities","cn":"休闲／体育设施"}},{"en":"a place, usually including buildings, used for a particular purpose or activity","cn":"（供特定用途的）场所","g":"[countable]","ex":{"en":"the world’s largest nuclear waste facility","cn":"世界最大的核废料处理场"}},{"en":"a special feature of a machine, service, etc. that makes it possible to do something extra","cn":"（机器等的）特别装置；（服务等的）特色","g":"[countable]","ex":{"en":"a bank account with an overdraft facility","cn":"提供透支服务的银行账户"}},{"en":"a natural ability to learn or do something easily","cn":"（学习、做事的）天资，才能，天赋","g":"[singular, uncountable]","ex":{"en":"She has a facility for languages.","cn":"她有语言天赋。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"设备;设施","en":"Facilities are buildings, pieces of equipment, or services that are provided for a particular purpose.","ex":{"en":"What recreational facilities are now available?","cn":"现在有些什么娱乐设施？"}},{"pos":"N-COUNT 可数名词","cn":"（组织提供的）附加服务，特色服务;(机器的)功能","en":"A facility is something such as an additional service provided by an organization or an extra feature on a machine which is useful but not essential.","ex":{"en":"It is very useful to have an overdraft facility","cn":"有透支功能用处很大。"}},{"pos":"N-COUNT 可数名词","cn":"天资;才能;天赋","en":"If you have a facility for something, for example learning a language, you find it easy to do.","ex":{"en":"He and Marcia shared a facility for languages","cn":"他和马西娅都有语言天赋。"}}]},"examples":[{"en":"The hotel has special facilities for welcoming disabled people.","cn":"这家旅馆有专供残疾人使用的设施。"},{"en":"All rooms have private facilities (= a private bathroom).","cn":"每一个房间都有专用的浴室。"}]},"far":{"media":{"uk":"media/uk/far__gb_1.mp3","us":"media/us/far__us_1.mp3"},"oxford":{"phon":"fɑː(r)","pos":"adverb","senses":[{"en":"a long distance away","cn":"远","lab":"figurative","sc":"distance","ex":{"en":"We didn't go far.","cn":"我们没有走远。"}},{"en":"used when you are asking or talking about the distance between two places or the distance that has been travelled or is to be travelled","cn":"（问到或谈及距离时说）有多远，远（至）","sc":"distance","ex":{"en":"How far is it to your house from here?","cn":"从这儿到你家有多远？"}},{"en":"a long time from the present; for a large part of a particular period of time","cn":"久；远","sc":"time","ex":{"en":"The band had their first hit as far back as 2012.","cn":"这支乐队早在 2012 年就推出了第一首大热的歌曲。"}},{"en":"very much; to a great degree","cn":"非常；很大程度上；远远；大大","sc":"degree","ex":{"en":"That's a far better idea.","cn":"那个主意好得多。"}},{"en":"used when you are asking or talking about the degree to which something is true or possible","cn":"（问到或谈及程度时说）有多大，直（至）","sc":"degree","ex":{"en":"How far can we trust him?","cn":"我们能够信任他到什么程度？"}},{"en":"used to talk about how much progress has been made in doing or achieving something","cn":"进展程度","sc":"progress","ex":{"en":"How far have you got with that report?","cn":"你那个报告写得怎么样了？"}},{"en":"at a greater distance away from you","cn":"较远的","ex":{"en":"I saw her on the far side of the road.","cn":"我看见她在马路那头。"},"pos":"adjective"},{"en":"at the furthest point in a particular direction","cn":"（某方向的）最远的，远端的","ex":{"en":"the far north of Scotland","cn":"苏格兰的最北边"},"pos":"adjective"},{"en":"a long distance away","cn":"远","lab":"old-fashioned or literary","ex":{"en":"a far country","cn":"远方的国家"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"远;遥远地","en":"If one place, thing, or person is far away from another, there is a great distance between them.","ex":{"en":"I know a nice little Italian restaurant not far from here","cn":"我知道有家不错的意大利小餐馆离这儿不远。"}},{"pos":"ADV-GRADED 副词","cn":"(用于问及距离或位置)有多远，远至","en":"If you ask how far a place is, you are asking what distance it is from you or from another place. If you ask how far someone went, you are asking what distance they travelled, or what place they reached.","ex":{"en":"How far is Pawtucket from Providence?","cn":"波塔基特离普罗维登斯有多远？"}},{"pos":"ADJ 形容词","cn":"(同一处的两物)离得较远的，那一边的","en":"When there are two things of the same kind in a place, the far one is the one that is a greater distance from you.","ex":{"en":"He had wandered to the far end of the room","cn":"他转到屋子的那一头。"}},{"pos":"ADJ 形容词","cn":"(某个方向上)最远的，最…端的","en":"You can use far to refer to the part of an area or object that is the greatest distance from the centre in a particular direction. For example, the far north of a country is the part of it that is the greatest distance to the north.","ex":{"en":"I've spent a lot of time walking around Britain from the far north of Scotland down to Cornwall","cn":"我花了很长时间在英国徒步漫游，从苏格兰的最北端一直走到康沃尔。"}},{"pos":"ADV-GRADED 副词","cn":"(时间或事件)久，远","en":"A time or event that is far away in the future or the past is a long time from the present or from a particular point in time.","ex":{"en":"...hidden conflicts whose roots lie far back in time","cn":"很久以前就埋下祸根的潜在冲突"}},{"pos":"ADV-GRADED 副词","cn":"(用于谈及程度或范围)到…程度(或范围)","en":"You can use far to talk about the extent or degree to which something happens or is true.","ex":{"en":"How far did the film tell the truth about Barnes Wallis?","cn":"影片讲述的巴恩斯·沃利斯的故事有多少真实的成分？"}},{"pos":"ADV-GRADED 副词","cn":"(用于谈及进展)到…程度，到…阶段","en":"You can talk about how far someone or something gets to describe the progress that they make.","ex":{"en":"Discussions never progressed very far","cn":"讨论一直没多大进展。"}},{"pos":"ADV-GRADED 副词","cn":"(用于谈论行为)过分到，过分得","en":"You can talk about how far a person or action goes to describe the degree to which someone's behaviour or actions are extreme.","ex":{"en":"It's still not clear how far the Russian parliament will go to implement its own plans","cn":"俄罗斯议院在实施自己的计划时到底会采取怎样的极端措施尚不明了。"}},{"pos":"ADV-GRADED 副词","cn":"(用于表示在多大程度上赞成)我可不那样认为/我这样认为","en":"You can use far in expressions like 'I wouldn't go that far' and 'I would go so far' to indicate to what extent you agree with something.","ex":{"en":"'Does it sound like music?' — 'I wouldn't go that far.'","cn":"“这听上去像音乐吗？”——“我可不那样认为。”"}},{"pos":"ADV 副词","cn":"(比较时用作强调)…得多，非常，太","en":"You can use far to mean 'very much' when you are comparing two things and emphasizing the difference between them. For example, you can say that something is far better or far worse than something else to indicate that it is very much better or worse. You can also say that something is, for example, far too big to indicate that it is very much too big.","ex":{"en":"Women who eat plenty of fresh vegetables are far less likely to suffer anxiety or depression","cn":"吃新鲜蔬菜多的女性患焦虑症或抑郁症的几率要小很多。"}},{"pos":"ADJ 形容词","cn":"(政治观点)极端的，偏激的","en":"You can describe people with extreme left-wing or right-wing political views as the far left or the far right.","ex":{"en":"The far right is now a greater threat than the extreme left","cn":"现在极右派比极左派威胁更大。"}},{"pos":"ADV-GRADED 副词","cn":"(用于表示不太确信)据我所知/就我记得的","en":"You can use far in expressions like 'as far as I know' and 'so far as I remember' to indicate that you are not absolutely sure of the statement you are about to make or have just made, and you may be wrong.","ex":{"en":"It only lasted a couple of years, as far as I know","cn":"据我所知，它仅仅维持了两三年。"}},{"pos":"PHRASE 短语","cn":"(比较时用作强调)显然,…得多，大大地","en":"You use the expression far and away when you are comparing something or someone with others of the same kind, in order to emphasize how great the difference is between them. For example, you can say that something is far and away the best to indicate that it is definitely the best.","ex":{"en":"He's still far and away the best we have.","cn":"他仍然是我们最最优秀的人才。"}},{"pos":"PHRASE 短语","cn":"(比较时用作强调)显然,…得多，大大地","en":"You use the expression by far when you are comparing something or someone with others of the same kind, in order to emphasize how great the difference is between them. For example, you can say that something is by far the best or the best by far to indicate that it is definitely the best.","ex":{"en":"By far the most important issue for them is unemployment","cn":"对他们来说最重要的无疑就是失业问题。"}},{"pos":"PHRASE 短语","cn":"根本不;远远不","en":"If you say that something is far from a particular thing or far from being the case, you are emphasizing that it is not that particular thing or not at all the case, especially when people expect or assume that it is.","ex":{"en":"It was obvious that much of what they recorded was far from the truth","cn":"显然，他们所记录的很多根本不是事实。"}},{"pos":"PHRASE 短语","cn":"(用于加强否定)远非如此，绝非这样","en":"You can use the expression 'far from it' to emphasize a negative statement that you have just made.","ex":{"en":"Being dyslexic does not mean that one is unintelligent. Far from it.","cn":"患有诵读困难症并不意味着智力低下。两者相差甚远。"}},{"pos":"PHRASE 短语","cn":"(表示委婉地反对或批评)不是我要，不是我想","en":"You say far be it from me to disagree, or far be it from me to criticize, when you are disagreeing or criticizing and you want to appear less hostile.","ex":{"en":"Far be it from me to criticise, but shouldn't their mother take a share of the blame?","cn":"不是我要挑理，他们的母亲难道就不应该负点责任吗？"}},{"pos":"PHRASE 短语","cn":"在一定程度上，在有限程度上(不错或正确)","en":"If you say that something is good as far as it goes or true so far as it goes, you mean that it is good or true only to a limited extent.","ex":{"en":"His plan for tax relief is fine as far as it goes but will not be sufficient to get the economy moving again.","cn":"他的减税方案还算不错，但并不足以促使经济再次发展。"}},{"pos":"PHRASE 短语","cn":"前程远大;很有前途","en":"If you say that someone will go far, you mean that they will be very successful in their career.","ex":{"en":"I was very impressed with the talent of Michael Ball. He will go far.","cn":"我对迈克尔·鲍尔的才华印象非常深刻，他将来会前途无量。"}},{"pos":"PHRASE 短语","cn":"病入膏肓的;无可救药的;积重难返的","en":"Someone or something that is far gone is in such a bad state or condition that not much can be done to help or improve them.","ex":{"en":"In his last few days the pain seemed to have stopped, but by then he was so far gone that it was no longer any comfort","cn":"在他弥留人世的最后几天里，疼痛似乎止住了，但那时他已奄奄一息，不再感到丝毫安慰。"}},{"pos":"PHRASE 短语","cn":"几近正确;相差无几;仅差毫厘","en":"Someone or something that is not far wrong ,not far out, or not far off is almost correct or almost accurate.","ex":{"en":"I hadn't been far wrong in my estimate","cn":"我过去的估计大致正确。"}},{"pos":"PHRASE 短语","cn":"就我看来;依我之见","en":"You can use the expression 'as far as I can see' when you are about to state your opinion of a situation, or have just stated it, to indicate that it is your personal opinion.","ex":{"en":"That's the problem as far as I can see","cn":"在我看来，那就是问题所在。"}},{"pos":"PHRASE 短语","cn":"(只能到)如此程度，这个地步","en":"If you say that something only goes so far or can only go so far, you mean that its extent, effect, or influence is limited.","ex":{"en":"Their loyalty only went so far","cn":"他们的忠诚只能到这个程度。"}},{"pos":"PHRASE 短语","cn":"迄今为止;到目前为止","en":"If you tell or ask someone what has happened so far, you are telling or asking them what has happened up until the present point in a situation or story, and often implying that something different might happen later.","ex":{"en":"It's been quiet so far","cn":"到现在为止还算安静。"}},{"pos":"PHRASE 短语","cn":"目前情况良好;现在还算不错","en":"You can say so far so good to express satisfaction with the way that a situation or activity is progressing, developing, or happening.","ex":{"en":"Of course, it's a case of so far, so good, but it's only one step.","cn":"当然，目前情况还算不错，但这也只是一步而已。"}},{"pos":"PHRASE 短语","cn":"(故事)说到这儿;(情势)到这一刻","en":"Thus far means up until the present point in a situation or story.","ex":{"en":"Thus far, the two prime ministers have achieved no concrete results.","cn":"到目前为止，两位首相还没有取得实质性成果。"}},{"pos":"PHRASE 短语","cn":"四面八方;五湖四海","en":"If people come from far and wide, they come from a large number of places, some of them far away. If things spread far and wide, they spread over a very large area or distance.","ex":{"en":"Volunteers came from far and wide","cn":"志愿者来自四面八方。"}},{"pos":"PHRASE 短语","cn":"差不多;八九不离十","en":"If you say that someone won't go far wrong or can't go far wrong with a particular thing or course of action, you mean that it is likely to be successful or satisfactory.","ex":{"en":"If you remember these three golden rules you won't go far wrong.","cn":"记住这三条金律，就不会错到哪儿。"}},{"pos":"","cn":"","en":"as far as I am concerned→see: ; a far cry from→see: ; in so far as→see: ; near and far→see: ;"}]},"examples":[{"en":"‘You're not angry then?’ ‘Far from it. I've never laughed so much in my life.’ “","cn":"那么你不生气？” “非但没有生气，我一生中还没有这样笑过呢。”"},{"en":"The band made their first record as far back as 1990.","cn":"这个乐队早在 1990 年就录制了他们的第一张唱片。"}]},"fancy":{"media":{"uk":"media/uk/fancy__gb_1.mp3","us":"media/us/fancy__us_1.mp3"},"oxford":{"phon":"ˈfænsi","pos":"verb","senses":[{"en":"to want something or want to do something","cn":"想要；想做","g":"[transitive]","lab":"British English, informal，，","ex":{"en":"Fancy a drink?","cn":"想喝一杯吗？"}},{"en":"to be sexually attracted to somebody","cn":"对某人有情欲；倾慕","g":"[transitive]","lab":"British English, informal，，","ex":{"en":"I think she fancies me.","cn":"我觉得她对我动心了。"}},{"en":"to think that you are very popular, attractive or intelligent","cn":"自负；自命不凡","g":"[transitive]","lab":"British English, informal, disapproving，，，，","ex":{"en":"He started to chat to me and I could tell that he really fancied himself.","cn":"他和我聊起天来，我看得出他确实自以为了不起。"}},{"en":"to like the idea of being something or to believe, often wrongly, that you are something","cn":"自认为是；自命为","g":"[transitive]","lab":"British English","ex":{"en":"She fancies herself (as) a serious actress.","cn":"她自以为是严肃的演员。"}},{"en":"used to show that you are surprised or shocked by something","cn":"（表示惊奇或震惊）真想不到，竟然","g":"[intransitive, transitive]","lab":"informal, becoming old-fashioned，，","ex":{"en":"Fancy! She's never been in a plane before.","cn":"真想不到！她竟然从未坐过飞机。"}},{"en":"to think that somebody/something will win or be successful at something, especially in a race","cn":"认为…会成功；（尤指速度竞赛）认为…要赢","g":"[transitive]","lab":"British English","ex":{"en":"Which horse do you fancy in the next race?","cn":"下一轮赛马你认为哪匹马会赢？"}},{"en":"to believe or imagine something","cn":"认为；想象","g":"[transitive]","lab":"literary","ex":{"en":"She fancied (that) she could hear footsteps.","cn":"她觉得好像听到了脚步声。"}},{"en":"unusually complicated, often in an unnecessary way; intended to impress other people","cn":"异常复杂的；太花哨的","ex":{"en":"a kitchen full of fancy gadgets","cn":"有各式各样小器具的厨房"},"pos":"adjective"},{"en":"with a lot of decorations or bright colours","cn":"精致的；有精美装饰的；绚丽的；花哨的","g":"[only before noun]","ex":{"en":"fancy goods (= things sold as gifts or for decoration)","cn":"饰物礼品"},"pos":"adjective"},{"en":"expensive or connected with an expensive way of life","cn":"昂贵的；奢华的","lab":"sometimes disapproving","ex":{"en":"fancy restaurants with fancy prices","cn":"价格昂贵的豪华餐厅"},"pos":"adjective"},{"en":"of high quality","cn":"优质的；高档的","lab":"North American English","pos":"adjective"},{"en":"something that you imagine; your imagination","cn":"想象的事物；想象（力）","g":"[countable, uncountable]","ex":{"en":"night-time fancies that disappear in the morning","cn":"在早上逝去的夜间幻觉"},"pos":"noun"},{"en":"a feeling that you would like to have or to do something","cn":"想要；爱好","g":"[singular]","ex":{"en":"She said she wanted a dog but it was only a passing fancy.","cn":"她说想要一条狗，但这不过是一时心血来潮。"},"pos":"noun"},{"en":"a small decorated cake","cn":"花色小蛋糕","g":"[countable, usually plural]","lab":"British English","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"想要;想做","en":"If you fancy something, you want to have it or to do it.","ex":{"en":"What do you fancy doing, anyway?","cn":"你到底想干什么？"}},{"pos":"N-COUNT 可数名词","cn":"(尤指一时的)喜好，渴望","en":"A fancy is a liking or desire for someone or something, especially one that does not last long.","ex":{"en":"She did not suspect that his interest was just a passing fancy.","cn":"她相信这不过是他一时兴起。"}},{"pos":"VERB 动词","cn":"爱慕;对(异性)着迷","en":"If you fancy someone, you feel attracted to them, especially in a sexual way.","ex":{"en":"The boys would tease you to death if they didn't fancy you","cn":"如果男孩们不喜欢你的话，他们就会狠狠地捉弄你。"}},{"pos":"VERB 动词","cn":"想让自己成为;想让自己做","en":"If you fancy yourself as a particular kind of person or fancy yourself doing a particular thing, you like the idea of being that kind of person or doing that thing.","ex":{"en":"So you fancy yourself as the boss someday?","cn":"这么说，你是想有一天自己当上老板喽？"}},{"pos":"VERB 动词","cn":"以为(自己)是;把(自己)当成","en":"If you say that someone fancies themselves (as) a particular kind of person, you mean that they think, often wrongly, that they have the good qualities which that kind of person has.","ex":{"en":"She fancies herself a bohemian","cn":"她自以为是放荡不羁的艺术家。"}},{"pos":"VERB 动词","cn":"相信(参赛的某队或某人)会赢","en":"If you say that you fancy a particular competitor or team in a competition, you think they will win.","ex":{"en":"You have to fancy Bath because they are the most consistent team in England","cn":"巴斯队一定会赢，因为他们是英格兰表现最稳定的球队。"}},{"pos":"VERB 动词","cn":"认为;料想","en":"If you fancy that something is the case, you think or suppose that it is so.","ex":{"en":"When Ferris looked up he fancied that he saw a shadow pass close to the window","cn":"费里斯抬头向上看，感觉看见一个影子在窗子近旁经过。"}},{"pos":"N-VAR 可变名词","cn":"(不切实际的)想象，幻想","en":"A fancy is an idea that is unlikely, untrue, or imaginary.","ex":{"en":"His last book is a bold, at times surrealistic mixture of fact and fancy.","cn":"他的最后一部书把现实与梦幻大胆糅合在一起，有些地方表现出超现实主义色彩。"}},{"pos":"EXCLAM 感叹语","cn":"(表达惊奇或不赞成)真想不到，太意外","en":"You say 'fancy' or 'fancy that' when you want to express surprise or disapproval.","ex":{"en":"It was very tasteless. Fancy talking like that so soon after his death","cn":"这真是太不得体了。真想不到在他尸骨未寒时就那么说话。"}},{"pos":"PHRASE 短语","cn":"(通常指不知何故就)爱上，喜欢上","en":"If you take a fancy to someone or something, you start liking them, usually for no understandable reason.","ex":{"en":"Sylvia took quite a fancy to him","cn":"西尔维娅深深爱上了他。"}},{"pos":"PHRASE 短语","cn":"招…喜欢;逗…喜爱","en":"If something takes your fancy or tickles your fancy, you like it a lot when you see it or think of it.","ex":{"en":"She makes most of her own clothes, copying any fashion which takes her fancy.","cn":"她的衣服多是仿照她喜爱的时装自己缝制的。"}},{"pos":"","cn":"","en":"flight of fancy→see: ;"},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"别致的;精美的;花哨的","en":"If you describe something as fancy, you mean that it is special, unusual, or elaborate, for example because it has a lot of decoration.","ex":{"en":"It was packaged in a fancy plastic case with attractive graphics.","cn":"它装在一个别致的有漂亮图纹的塑料盒子里。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(过于)奢华的，豪华的，昂贵的","en":"If you describe something as fancy, you mean that it is very expensive or of very high quality, and you often dislike it because of this.","ex":{"en":"He owned a fancy house out on Lake Agawam","cn":"他在阿格瓦姆湖畔拥有一座豪宅。"}}]},"examples":[{"en":"‘She remembered my name after all those years.’ ‘ Fancy that! ’ “","cn":"过了那么多年她还记得我的名字。” “真是不可思议！”"},{"en":"We bought a camper van so we could go away whenever the fancy took us.","cn":"我们买了一辆野营车，所以我们啥时想去野营就可以去。"}]},"facing":{"media":{"uk":"media/uk/facing__gb_1.mp3","us":"media/us/facing__us_1.mp3"},"oxford":{"phon":"ˈfeɪsɪŋ","pos":"noun","senses":[{"en":"an outer layer that covers the surface of a wall to make it look more attractive","cn":"（建筑物的）饰面，面层","g":"[countable, uncountable]","ex":{"en":"marble/stone/brick facings","cn":"大理石/石材/砖饰面"}},{"en":"a layer of stiff material sewn around the inside of the neck, armholes, etc. of a piece of clothing to make them stronger","cn":"领口衬里，袖口贴边，镶边（使衣服耐穿）","g":"[countable, uncountable]","ex":{"en":"Cut the facings out of thinner material.","cn":"用较薄的材料切割饰面。"}},{"en":"the collar, cuffs, etc. of a piece of clothing that are made in a different colour or material","cn":"（不同质地或颜色的）领子（或袖口等）","g":"[plural]","ex":{"en":"a smoking jacket with green velvet facings","cn":"绿色天鹅绒饰面的吸烟夹克"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(衣服的)镶边，贴边，里子","en":"Facing is fabric which is stitched inside the edges of a piece of clothing in order to make them look neat and strengthen them."},{"pos":"N-PLURAL 复数名词","cn":"(夹克或大衣领口和袖口的)镶边，贴边","en":"The facings of a garment such as a jacket or coat are the parts around the neck and wrists when they are made of a different fabric from the main part, or are a different colour."},{"pos":"N-VAR 可变名词","cn":"(墙的)贴面，饰面","en":"A facing on a wall is a layer of stone, concrete, or other material that is spread over its surface in order to make it look attractive."}]},"base":"face"},"facial":{"oxford":{"phon":"ˈfeɪʃl","pos":"adjective","senses":[{"en":"connected with a person’s face; on a person’s face","cn":"面部的","ex":{"en":"a facial expression","cn":"面部表情"}},{"en":"a beauty treatment in which a person’s face is cleaned using creams, steam (= gas produced when water boils), etc. in order to improve the quality of the skin","cn":"面部护理；美容","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"面部的;脸上的","en":"Facial means appearing on or being part of your face.","ex":{"en":"Cross didn't answer; his facial expression didn't change","cn":"克罗斯没有答话，脸上的表情也毫无变化。"}},{"pos":"N-COUNT 可数名词","cn":"面部护理;美容","en":"A facial is a sort of beauty treatment in which someone's face is massaged, and creams and other substances are rubbed into it."}]},"media":{"uk":"media/uk/facial__gb_1.mp3","us":"media/us/facial__us_1.mp3"},"examples":[{"en":"Facially the two men were very different.","cn":"这两个男人的脸型迥异。"},{"en":"a facial expression","cn":"面部表情"}]},"farthing":{"media":{"uk":"media/uk/farthing__gb_1.mp3","us":"media/us/farthing__us_1.mp3"},"oxford":{"phon":"ˈfɑːðɪŋ","pos":"noun","senses":[{"en":"in the past, a British coin worth one quarter of an old penny","cn":"法寻（英国旧硬币，值 ¼ 旧便士）"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"法寻(英国小硬币，面值为旧制便士的 1/4)","en":"A farthing was a small British coin which was worth a quarter of an old penny."}]}},"fascinating":{"media":{"uk":"media/uk/fascinating__gb_1.mp3","us":"media/us/fascinating__us_1.mp3"},"oxford":{"phon":"ˈfæsɪneɪtɪŋ","pos":"adjective","senses":[{"en":"extremely interesting and attractive","cn":"极有吸引力的；迷人的","ex":{"en":"a fascinating story","cn":"精彩的故事"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"迷人的;让人着迷的;极有吸引力的","en":"If you describe something as fascinating, you find it very interesting and attractive, and your thoughts tend to concentrate on it.","ex":{"en":"Madagascar is the most fascinating place I have ever been to","cn":"马达加斯加是我去过的最迷人的地方。"}}]},"examples":[{"en":"It's fascinating to see how different people approach the problem.","cn":"看到不同的人怎样处理这个问题真是有趣极了。"},{"en":"I fail to see what women find so fascinating about him.","cn":"我就看不出他哪一点使女人神魂颠倒。"}]},"factor":{"media":{"uk":"media/uk/factor__gb_1.mp3","us":"media/us/factor__us_1.mp3"},"oxford":{"phon":"ˈfæktə(r)","pos":"noun","senses":[{"en":"one of several things that cause or influence something","cn":"因素；要素","g":"[countable]","ex":{"en":"Obesity is a major risk factor for heart disease.","cn":"肥胖是心脏病的主要危险因素。"}},{"en":"a number that divides into another number exactly","cn":"因子；因数","g":"[countable]","lab":"mathematics","ex":{"en":"1, 2, 3, 4, 6 and 12 are the factors of 12.","cn":"1、2、3、4、6 和 12 是 12 的因子。"}},{"en":"the amount by which something increases or decreases","cn":"（增或减的）数量，倍数","g":"[countable]","ex":{"en":"The real wage of the average worker has increased by a factor of over ten in the last 70 years.","cn":"近 70 年来工人的实际工资平均增长超过了十倍。"}},{"en":"a particular level on a scale of measurement","cn":"系数","g":"[countable]","ex":{"en":"a suntan lotion with a protection factor of 10","cn":"防护系数为 10 的防晒油"}},{"en":"a substance in the blood that helps the clotting process. There are several types of this substance.","cn":"凝血因子","g":"[uncountable]","lab":"medical","ex":{"en":"Haemophiliacs have no factor 8 in their blood.","cn":"血友病患者的血液中缺乏凝血因子 VIII。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"因素;要素","en":"A factor is one of the things that affects an event, decision, or situation.","ex":{"en":"Physical activity is an important factor in maintaining fitness.","cn":"进行体育活动是保持身体健康的一个重要因素。"}},{"pos":"N-COUNT 可数名词","cn":"(增长的)倍数","en":"If an amount increases by a factor of two, for example, or by a factor of eight, then it becomes two times bigger or eight times bigger.","ex":{"en":"The cost of butter quadrupled and bread prices increased by a factor of five.","cn":"黄油价格涨了 4 倍，面包价格涨了 5 倍。"}},{"pos":"N-SING 单数名词","cn":"系数","en":"You can use factor to refer to a particular level on a scale of measurement.","ex":{"en":"...suncream with a protection factor of 8.","cn":"防晒系数为 8 的防晒霜"}},{"pos":"N-COUNT 可数名词","cn":"因子;因数","en":"A factor of a whole number is a smaller whole number which can be multiplied with another whole number to produce the first whole number."},{"pos":"","cn":"","en":"相关词组：factor in"}]},"examples":[{"en":"The real wage of the average worker has increased by a factor of over ten in the last 70 years.","cn":"近 70 年来工人的实际工资平均增长超过了十倍。"},{"en":"Remember to factor in staffing costs when you are planning the project.","cn":"规划该项目时，记住要把雇人费用这个因素考虑进去。"}]},"faculty":{"media":{"uk":"media/uk/faculty__gb_1.mp3","us":"media/us/faculty__us_1.mp3"},"oxford":{"phon":"ˈfæklti","pos":"noun","senses":[{"en":"a department or group of related departments in a college or university","cn":"（高等院校的）系，院","g":"[countable]","ex":{"en":"the Faculty of Law","cn":"法学院"}},{"en":"all the teachers in a faculty of a college or university","cn":"（高等院校中院、系的）全体教师","g":"[countable + singular or plural verb]","ex":{"en":"the Law School faculty","cn":"法学院全体教师"}},{"en":"all the teachers of a particular university or college","cn":"（某高等院校的）全体教师","g":"[countable, uncountable]","lab":"North American English","ex":{"en":"faculty members","cn":"全系教师"}},{"en":"any of the physical or mental abilities that a person is born with","cn":"官能；天赋","g":"[countable, usually plural]","ex":{"en":"the faculty of sight","cn":"视觉"}},{"en":"a particular ability for doing something","cn":"才能；能力","g":"[singular]","lab":"formal","ex":{"en":"the faculty of understanding complex issues","cn":"理解复杂问题的能力"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"官能;能力","en":"Your faculties are your physical and mental abilities.","ex":{"en":"He was drunk and not in control of his faculties","cn":"他喝醉了，浑身都不听使唤了。"}},{"pos":"N-VAR 可变名词","cn":"(大学的)院系;(大学院系的)教职工","en":"A faculty is a group of related departments in some universities, or the people who work in them.","ex":{"en":"...the Faculty of Social and Political Sciences.","cn":"社会政治系"}},{"pos":"N-VAR 可变名词","cn":"(大学、学院或院系的)全体教员","en":"A faculty is all the teaching staff of a university or college, or of one department.","ex":{"en":"The faculty agreed on a change in the requirements","cn":"全体教师一致同意修改规定。"}}]},"examples":[{"en":"She retained her mental faculties (= the ability to think and understand) until the day she died.","cn":"她直到临终那天一直保持着思维和理解能力。"},{"en":"to be in full possession of your faculties (= be able to speak, hear, see, understand, etc.)","cn":"拥有一切官能（能够说、听、看见、理解等）"}]},"faith":{"media":{"uk":"media/uk/faith__gb_1.mp3","us":"media/us/faith__us_1.mp3"},"oxford":{"phon":"feɪθ","pos":"noun","senses":[{"en":"trust in somebody’s ability or knowledge; trust that somebody/something will do what has been promised","cn":"信任；相信；信心","g":"[uncountable]","ex":{"en":"If the company can retain its customers' faith, it could become the market leader.","cn":"如果这家公司能持续获得顾客的信任，就会成为市场的领导者。"}},{"en":"strong religious belief","cn":"宗教信仰","g":"[uncountable, singular]","lab":"North American English","ex":{"en":"to have faith","cn":"有信仰"}},{"en":"a particular religion","cn":"（某一）宗教","g":"[countable]","ex":{"en":"the Christian/Catholic/Islamic/Muslim/Jewish faith","cn":"基督教；天主教；伊斯兰教；犹太教"}},{"en":"the intention to do something right/wrong","cn":"诚意；善意；恶意","g":"[uncountable]","ex":{"en":"They handed over the weapons as a gesture of good faith.","cn":"他们交出武器以示诚意。"}},{"en":"a first name for girls","cn":"费丝（女子名）","pos":""}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"相信;信任","en":"If you have faith in someone or something, you feel confident about their ability or goodness.","ex":{"en":"She had placed a great deal of faith in Mr Penleigh","cn":"她对彭利先生极其信任。"}},{"pos":"N-COUNT 可数名词","cn":"宗教","en":"A faith is a particular religion, for example Christianity, Buddhism, or Islam.","ex":{"en":"England shifted officially from a Catholic to a Protestant faith in the 16th century.","cn":"英格兰于 16 世纪正式由天主教改信新教。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"宗教信仰","en":"Faith is strong religious belief in a particular God.","ex":{"en":"Umberto Eco's loss of his own religious faith is reflected in his novels.","cn":"翁贝托·艾柯个人宗教信仰的丧失反映在了他的小说里。"}},{"pos":"PHRASE 短语","cn":"背弃;对…不忠;脱离","en":"If you break faith with someone you made a promise to or something you believed in, you stop acting in a way that supports them.","ex":{"en":"If we don't, we're breaking faith with our people!","cn":"如果我们不这样，就是对我们的人民背信弃义！"}},{"pos":"PHRASE 短语","cn":"真诚地;真心实意地;好意地","en":"If you do something in good faith, you seriously believe that what you are doing is right, honest, or legal, even though this may not be the case.","ex":{"en":"This report was published in good faith but we regret any confusion which may have been caused.","cn":"我们发表这篇报道的初衷是好的，但对可能已造成的混乱深感歉意。"}},{"pos":"PHRASE 短语","cn":"信守(诺言);恪守","en":"If you keep faith with someone you have made a promise to or something you believe in, you continue to support them even when it is difficult to do so.","ex":{"en":"He has made one of the most powerful American films of the year by keeping faith with his radical principles.","cn":"他秉承自己一贯的激进风格，制作出了本年度美国最有感染力的影片之一。"}}]},"examples":[{"en":"We printed the report in good faith but have now learnt that it was incorrect.","cn":"我们好意印发了这份报告，但现在才知道它并不正确。"},{"en":"Her friend's kindness has restored her faith in human nature.","cn":"朋友的善意使她恢复了对人性的信心。"}]},"favour":{"media":{"uk":"media/uk/favour__gb_1.mp3","us":"media/us/favour__us_1.mp3"},"oxford":{"phon":"ˈfeɪvə(r)","pos":"noun","senses":[{"en":"a thing that you do to help somebody","cn":"帮助；好事；恩惠","g":"[countable]","lab":"North American English","sc":"help","ex":{"en":"Could you do me a favour and pick up Sam from school today?","cn":"今天你能帮我个忙去学校接萨姆吗？"}},{"en":"approval or support for somebody/something","cn":"赞同；支持","g":"[uncountable]","lab":"formal","sc":"approval","ex":{"en":"Artists sought the favour of wealthy patrons.","cn":"艺术家谋求富有的赞助人的支持。"}},{"en":"treatment that is generous to one person or group in a way that seems unfair to others","cn":"优惠；特别照顾；偏袒","g":"[uncountable]","sc":"better treatment","ex":{"en":"As an examiner, she showed no favour to any candidate.","cn":"作为主考人她没有偏袒任何应试者。"}},{"en":"a small gift given to children at a party","cn":"（送给孩子的）聚会小礼品，派对礼物","g":"[countable, usually plural]","lab":"North American English","sc":"party gift"},{"en":"agreement to have sex with somebody","cn":"同意性交","g":"[plural]","lab":"old-fashioned","sc":"sex","ex":{"en":"demands for sexual favours","cn":"对性交的要求"}},{"en":"to prefer one system, plan, way of doing something, etc. to another","cn":"较喜欢；选择","sc":"prefer","ex":{"en":"Many countries favour a presidential system of government.","cn":"很多国家选择总统制政府。"},"pos":"verb"},{"en":"to treat one person, group or organization better than you treat others, especially in an unfair way","cn":"优惠；特别照顾；偏袒","sc":"treat better","ex":{"en":"The treaty seems to favour the US.","cn":"这项条约似乎偏向美国。"},"pos":"verb"},{"en":"to provide suitable conditions for a particular person, group, etc.","cn":"有助于；有利于","sc":"help","ex":{"en":"The warm climate favours many types of tropical plants.","cn":"温暖的气候对多种热带植物生长有利。"},"pos":"verb"},{"en":"to look like one of your parents or older relations","cn":"外貌像，长得像（父母或长辈）","lab":"old-fashioned or North American English, informal，，","sc":"look like parent","ex":{"en":"She definitely favours her father.","cn":"她酷似她父亲。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"赞同;支持;喜爱","en":"If you regard something or someone with favour, you like or support them.","ex":{"en":"It remains to be seen if the show will still find favour with a 1990s audience","cn":"这个节目是否能继续赢得 90 后观众的喜爱，还要拭目以待。"}},{"pos":"N-COUNT 可数名词","cn":"恩惠;帮忙","en":"If you do someone a favour, you do something for them even though you do not have to.","ex":{"en":"I've come to ask you to do me a favour","cn":"我来这儿是想请你帮个忙。"}},{"pos":"N-PLURAL 复数名词","cn":"与人发生性关系","en":"If you say that one person gives or sells their favours to another, you mean that they have sex.","ex":{"en":"In her extreme youth, Maria had sold her sexual favours for money.","cn":"玛丽亚在非常年轻的时候，曾靠卖淫来赚钱。"}},{"pos":"VERB 动词","cn":"更喜爱;宁愿;倾向于","en":"If you favour something, you prefer it to the other choices available.","ex":{"en":"The French say they favour a transition to democracy","cn":"法国人说他们倾向于向民主过渡。"}},{"pos":"VERB 动词","cn":"偏爱;偏袒;宠爱","en":"If you favour someone, you treat them better or in a kinder way than you treat other people.","ex":{"en":"The Government came under fire yesterday for favouring elitist arts groups in the South-east","cn":"昨天，政府因为偏袒东南部的一些精英艺术群体而遭到抨击。"}},{"pos":"PHRASE 短语","cn":"支持;赞成","en":"If you are in favour of something, you support it and think that it is a good thing.","ex":{"en":"I wouldn't be in favour of income tax cuts","cn":"我不会支持削减所得税。"}},{"pos":"PHRASE 短语","cn":"认为…正确;认为…有理","en":"If someone makes a judgment in your favour, they say that you are right about something.","ex":{"en":"If the commission rules in Mr Welch's favour the case will go to the European Court of Human Rights.","cn":"如果委员会裁定韦尔奇有理，这个案件将送交欧洲人权法庭。"}},{"pos":"PHRASE 短语","cn":"对…有利","en":"If something is in your favour, it helps you or gives you an advantage.","ex":{"en":"The protection that farmers have enjoyed amounts to a bias in favour of the countryside","cn":"农民所受的保护几乎变成了对乡村的偏袒。"}},{"pos":"PHRASE 短语","cn":"(舍弃某物)宁愿选择;选…(而不选…)","en":"If one thing is rejected in favour of another, the second thing is done or chosen instead of the first.","ex":{"en":"The policy was rejected in favour of a more cautious approach.","cn":"这项政策未被采纳，取而代之的是一项较为谨慎的策略。"}},{"pos":"PHRASE 短语","cn":"受宠／失宠;得势／失势","en":"If someone or something is in favour, people like or support them. If they are out of favour, people no longer like or support them."}]},"examples":[{"en":"‘Do you think they'll win?’ ‘Do me a favour! They haven't got a single decent player.’ “","cn":"你认为他们会赢吗？” “得了吧！他们连一个像样的运动员都没有。”"},{"en":"Most of the ‘don't knows’ in the opinion polls came down in favour of (= eventually chose to support) the Democrats.","cn":"在民意测验中多数未作决定的选民最终决定支持民主党人。"}]},"fault":{"media":{"uk":"media/uk/fault__gb_1.mp3","us":"media/us/fault__us_1.mp3"},"oxford":{"phon":"fɔːlt","pos":"noun","senses":[{"en":"the responsibility for something wrong that has happened or been done","cn":"责任；过错；过失","g":"[uncountable]","sc":"responsibility","ex":{"en":"Why should I say sorry when it's not my fault?","cn":"不是我的错为什么要我道歉？"}},{"en":"a bad or weak aspect of somebody’s character","cn":"弱点；缺点","g":"[countable]","sc":"in somebody’s character","ex":{"en":"He's proud of his children and blind to their faults.","cn":"他为孩子们感到自豪，对他们的缺点视而不见。"}},{"en":"something that is wrong or not perfect; something that is wrong with a machine or system that stops it from working correctly","cn":"缺陷；毛病；故障","g":"[countable]","sc":"something wrong","ex":{"en":"The book's virtues far outweigh its faults.","cn":"这本书优点远远大于缺点。"}},{"en":"a mistake made when serving","cn":"发球失误","g":"[countable]","sc":"in tennis","ex":{"en":"He has served a number of double faults in this set.","cn":"他在这盘发球出现了一些双误。"}},{"en":"a place where there is a break that is longer than usual in the layers of rock in the earth’s crust","cn":"（地壳岩层的）断层","g":"[countable]","sc":"geology","ex":{"en":"the San Andreas fault","cn":"圣安德烈亚斯断层"}},{"en":"to find a mistake or a weakness in somebody/something","cn":"发现错误；找出缺点","ex":{"en":"Her colleagues could not fault her dedication to the job.","cn":"她的同事认为她的敬业精神是无可挑剔的。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"责任;过失;过错","en":"If a bad or undesirable situation is your fault, you caused it or are responsible for it.","ex":{"en":"There was no escaping the fact: it was all his fault","cn":"这全是他的错，这是无法回避的事实。"}},{"pos":"N-COUNT 可数名词","cn":"错误;失误","en":"A fault is a mistake in what someone is doing or in what they have done.","ex":{"en":"It is a big fault to think that you can learn how to manage people in business school.","cn":"以为在商学院能学会如何管理人是一大错误。"}},{"pos":"N-COUNT 可数名词","cn":"缺点;毛病","en":"A fault in someone or something is a weakness in them or something that is not perfect.","ex":{"en":"His manners had always made her blind to his faults.","cn":"他的彬彬有礼总是使她对他的缺点视而不见。"}},{"pos":"VERB 动词","cn":"(无可)挑剔，找茬儿，指责","en":"If you cannot fault someone, you cannot find any reason for criticizing them or the things that they are doing.","ex":{"en":"You can't fault them for lack of invention","cn":"你不能因为他们缺乏创新就指责他们。"}},{"pos":"N-COUNT 可数名词","cn":"(地壳的)断层","en":"A fault is a large crack in the surface of the earth.","ex":{"en":"...the San Andreas Fault.","cn":"圣安德烈亚斯断层"}},{"pos":"N-COUNT 可数名词","cn":"(网球的)发球失误","en":"A fault in tennis is a service that is wrong according to the rules."},{"pos":"PHRASE 短语","cn":"有过错;有责任","en":"If someone or something is at fault, they are to blame or are responsible for a particular situation that has gone wrong.","ex":{"en":"He could never accept that he had been at fault","cn":"他怎么也无法承认是他的错。"}},{"pos":"PHRASE 短语","cn":"挑剔;找茬儿;指责","en":"If you find fault with something or someone, you look for mistakes and complain about them.","ex":{"en":"I was disappointed whenever the cook found fault with my work.","cn":"每当厨师挑剔我干的活儿时，我都非常沮丧。"}},{"pos":"PHRASE 短语","cn":"(好得)过分，过头","en":"If you say that someone has a particular good quality to a fault, you are emphasizing that they have more of this quality than is usual or necessary.","ex":{"en":"Jefferson was generous to a fault","cn":"杰斐逊大方得过了头。"}}]},"examples":[{"en":"He's proud of his children and blind to their faults.","cn":"他为孩子们感到自豪，对他们的缺点视而不见。"},{"en":"The system, for all its faults, is the best available at the moment.","cn":"这个系统虽然缺点不少，却是现有最好的一个。"}]},"facetiously":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not being serious about something that should be taken seriously, so that people think you do not care","cn":""},{"en":"actions or behaviour that are playful are not serious, but they are fun and friendly","cn":""}]},"examples":[{"en":"Don’t be so facetious!","cn":"","src":"ld"}],"media":{"uk":"media/uk/facetiously__gb_1.mp3","us":"media/us/facetiously__us_1.mp3"},"oxford":{"phon":"fəˈsiːʃəsli","pos":"adverb","senses":[{"en":"in a way that tries to appear funny and clever at a time when other people do not think it is appropriate, and when it would be better to be serious","cn":"乱引人发笑的；不分场合耍聪明的"}]}},"face":{"media":{"img":["media/ldoce/img/face.jpg","media/pic/face_body_comp.jpg"],"uk":"media/uk/face__gb_1.mp3","us":"media/us/face__us_1.mp3"},"oxford":{"phon":"feɪs","pos":"noun","senses":[{"en":"the front part of the head, where the eyes, nose and mouth are","cn":"脸；面孔","sc":"front of head","ex":{"en":"a pretty/pale/round face","cn":"漂亮的／苍白的／圆圆的脸"}},{"en":"an expression that is shown on somebody’s face","cn":"面部表情","sc":"expression","ex":{"en":"a smiling/happy/sad face","cn":"笑脸；幸福／悲伤的脸"}},{"en":"used to refer to a person of the type mentioned","cn":"（某类型的）人","sc":"person","ex":{"en":"She looked around for a familiar face.","cn":"她环顾四周想找个熟人。"}},{"en":"having the type of face or expression mentioned","cn":"有…面容的；有…表情的","sc":"-faced","ex":{"en":"pale-faced","cn":"面色苍白的"}},{"en":"a side or surface of something","cn":"（某物的）面，表面","sc":"side/surface","ex":{"en":"the north face of the mountain","cn":"山的北坡"}},{"en":"the front part of a clock or watch","cn":"钟面；表盘","sc":"front of clock","ex":{"en":"a dial like the face of a clock","cn":"像钟面一样的表盘"}},{"en":"the particular character of something","cn":"（事物的某种）特征","sc":"character/aspect","ex":{"en":"the changing face of Britain","cn":"大不列颠变化中的特征"}},{"en":"a particular aspect of something","cn":"方面","sc":"character/aspect","ex":{"en":"Social deprivation is the unacceptable face of capitalism.","cn":"社会贫困是资本主义令人不可接受的方面。"}},{"en":"to be opposite somebody/something; to have your face or front pointing towards somebody/something or in a particular direction","cn":"面对；面向；正对","g":"[transitive, intransitive]","sc":"be opposite","ex":{"en":"She turned and faced him.","cn":"她转过身来面对着他。"},"pos":"verb"},{"en":"if you face a particular situation, or it faces you, you have to deal with it","cn":"面临，必须对付（某情况）","g":"[transitive]","sc":"somebody/something difficult","ex":{"en":"Farmers face serious challenges in these conditions.","cn":"在这种情况下，农民面临重重难关。"},"pos":"verb"},{"en":"to accept that a difficult situation exists, although you would prefer not to","cn":"承认，正视（现实）","g":"[transitive]","sc":"somebody/something difficult","ex":{"en":"It's time to face reality—we failed.","cn":"该正视现实了——我们失败了。"},"pos":"verb"},{"en":"if you can’t face something unpleasant, you feel unable or unwilling to deal with it","cn":"（感到不能）对付；（不愿）处理","g":"[transitive]","sc":"somebody/something difficult","ex":{"en":"I just can't face work today.","cn":"我今天就是没法工作。"},"pos":"verb"},{"en":"to talk to or deal with somebody, even though this is difficult or unpleasant","cn":"（明知不好办而）交谈，应付","g":"[transitive]","sc":"somebody/something difficult","ex":{"en":"How can I face Tom? He'll be so disappointed.","cn":"我怎样才能和汤姆谈呢？他会很失望的。"},"pos":"verb"},{"en":"to cover a surface with another material","cn":"（以另一物）覆盖表面","g":"[transitive, usually passive]","sc":"cover surface","ex":{"en":"a brick building faced with stone","cn":"石料贴面的砖建筑物"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"脸;面孔","en":"Your face is the front part of your head from your chin to the top of your forehead, where your mouth, eyes, nose, and other features are.","ex":{"en":"He rolled down his window and stuck his face out","cn":"他摇下车窗，把头探了出去。"}},{"pos":"N-COUNT 可数名词","cn":"面容;神色;神情","en":"If your face is happy, sad, or serious, for example, the expression on your face shows that you are happy, sad, or serious.","ex":{"en":"He was walking around with a sad face","cn":"他四处走着，神色哀伤。"}},{"pos":"N-COUNT 可数名词","cn":"崖面;山侧;(建筑物的)墙面","en":"The face of a cliff, mountain, or building is a vertical surface or side of it.","ex":{"en":"...the north face of the Eiger","cn":"艾格尔山北坡"}},{"pos":"N-COUNT 可数名词","cn":"钟面;表盘","en":"The face of a clock or watch is the surface with the numbers or hands on it, which shows the time."},{"pos":"N-SING 单数名词","cn":"(地区、机构或活动领域的)外观，面貌","en":"If you say that the face of an area, institution, or field of activity is changing, you mean its appearance or nature is changing.","ex":{"en":"...the changing face of the British countryside","cn":"英国乡村的日新月异"}},{"pos":"N-SING 单数名词","cn":"(活动，信仰、制度等的)方面","en":"If you refer to something as the particular face of an activity, belief, or system, you mean that it is one particular aspect of it, in contrast to other aspects.","ex":{"en":"Brothels, she insists, are the acceptable face of prostitution","cn":"她坚持认为，妓院是卖淫可为人接受的一种形式。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"面子;脸面","en":"If you lose face, you do something which makes you appear weak and makes people respect or admire you less. If you do something in order to save face, you do it in order to avoid appearing weak and losing people's respect or admiration.","ex":{"en":"England doesn't want a war but it doesn't want to lose face","cn":"英格兰不想打仗，但也不想丢面子。"}},{"pos":"PHRASE 短语","cn":"(计划之事出乎意料地)告吹，砸锅，泡汤","en":"If something that you have planned blows up in your face, it goes wrong unexpectedly, with the result that you suffer.","ex":{"en":"Can't you see this could blow up in your face?","cn":"你难道看不出这事会砸锅？"}},{"pos":"PHRASE 短语","cn":"徒劳拼命地干;徒劳无功","en":"If you say that someone can do something until they are blue in the face, you are emphasizing that however much they do it, it will not make any difference.","ex":{"en":"You can criticise him until you're blue in the face, but you'll never change his personality.","cn":"即使你苦口婆心地批评他，也改变不了他的个性。"}},{"pos":"PHRASE 短语","cn":"面朝下／仰面","en":"If someone or something is face down, their face or front points downwards. If they are face up, their face or front points upwards.","ex":{"en":"All the time Stephen was lying face down and unconscious in the bath tub","cn":"斯蒂芬一直脸朝下趴在浴缸里，不省人事。"}},{"pos":"PHRASE 短语","cn":"(表示强调或夸张)全世界","en":"You can use the expression 'on the face of the earth' to mean 'in the whole world', when you are emphasizing a statement that you are making or making a very exaggerated statement.","ex":{"en":"No human being on the face of the earth could do anything worse than what he did.","cn":"世界上再没有人能做出比他更坏的事情来。"}},{"pos":"PHRASE 短语","cn":"绝迹;灭绝","en":"If you say that something will be wiped off the face of the earth or disappear from the face of the earth, you mean that it will stop existing.","ex":{"en":"If a nuclear war breaks out, every living thing will be wiped off the face of the Earth.","cn":"如果爆发核战争，地球上的所有生物都将灭绝。"}},{"pos":"PHRASE 短语","cn":"面对面;直面","en":"If you come face to face with someone, you meet them and can talk to them or look at them directly.","ex":{"en":"We were strolling into the town when we came face to face with Jacques DuBois","cn":"我们信步向镇子走去，迎面碰上雅克·杜波依斯。"}},{"pos":"PHRASE 短语","cn":"面对,面临(困难或现实)","en":"If you come face to face with a difficulty or reality, you cannot avoid it and have to deal with it.","ex":{"en":"Eventually, he came face to face with discrimination again","cn":"最终，他又一次遭遇歧视。"}},{"pos":"PHRASE 短语","cn":"完全违背;与(公认的观念或规则)相冲突","en":"If an action or belief flies in the face of accepted ideas or rules, it seems to completely oppose or contradict them.","ex":{"en":"...scientific principles that seem to fly in the face of common sense","cn":"似乎有悖常识的科学原理"}},{"pos":"PREP-PHRASE 短语介词","cn":"面对;在…面前","en":"If you take a particular action or attitude in the face of a problem or difficulty, you respond to that problem or difficulty in that way.","ex":{"en":"The Prime Minister has called for national unity in the face of the violent anti-government protests","cn":"面对强烈的反政府抗议，首相呼吁全国团结一致。"}},{"pos":"PHRASE 短语","cn":"公然嘲笑;公开蔑视","en":"If someone laughs in your face, they are openly disrespectful towards you.","ex":{"en":"With juveniles under eighteen, there's little we can do. We can't keep them in custody. They just laugh in your face.","cn":"对18岁以下的青少年，我们几乎无计可施。我们不能拘留他们。他们只会公然嘲笑你。"}},{"pos":"PHRASE 短语","cn":"不高兴的神情;严肃的神情;板起的脸","en":"If you have a long face, you look very unhappy or serious.","ex":{"en":"He came to me with a very long face.","cn":"他拉长了脸来找我。"}},{"pos":"PHRASE 短语","cn":"做鬼脸,扮鬼脸（英国英语中亦使用pull a face）","en":"If you make a face, you show a feeling such as dislike or disgust by putting an exaggerated expression on your face, for example by sticking out your tongue. In British English, you can also say pull a face .","ex":{"en":"Opening the door, she made a face at the musty smell","cn":"她打开门后闻到一股难闻的霉味，不禁做了个鬼脸。"}},{"pos":"PHRASE 短语","cn":"乍看起来;最初看来","en":"You say on the face of it when you are describing how something seems when it is first considered, in order to suggest that people's opinion may change when they know or think more about the subject.","ex":{"en":"On the face of it that seems to make sense. But the figures don't add up","cn":"乍一看,似乎讲得通，但这些数字对不起来。"}},{"pos":"PHRASE 短语","cn":"（对坏情况）显得满不在乎，做出无所谓的样子(美国英语中亦作 put on a good face)","en":"If you put a brave face on a bad situation or put on a brave face, you try not to show how disappointed or upset you are about the situation. In American English you can also say put on a good face.","ex":{"en":"Friends will see you are putting on a brave face and might assume you've got over your grief","cn":"朋友们看到你一脸轻松，也许会以为你已经走出悲伤。"}},{"pos":"PHRASE 短语","cn":"(尤指错误地)反对","en":"You can say that someone has set their face against something to indicate that they are opposed to it, especially when you want to suggest that they are wrong.","ex":{"en":"This Government has set its face against putting up income tax.","cn":"这届政府执意反对提高所得税。"}},{"pos":"PHRASE 短语","cn":"(不受欢迎地、不情愿地或再次)露面，到场","en":"If you show your face somewhere, you go there and see people, although you are not welcome, are rather unwilling to go, or have not been there for some time.","ex":{"en":"If she shows her face again back in Massachusetts she'll find a warrant for her arrest waiting","cn":"如果她重又在马萨诸塞州露面，等待她的将是一纸拘捕令。"}},{"pos":"PHRASE 短语","cn":"强绷笑脸","en":"If you manage to keep a straight face, you manage to look serious, although you want to laugh.","ex":{"en":"What went through Tom's mind I can't imagine, but he did manage to keep a straight face","cn":"不知道汤姆想到了啥，但他确实忍住没笑。"}},{"pos":"PHRASE 短语","cn":"当着…的面","en":"If you say something to someone's face you say it openly in their presence.","ex":{"en":"Her opponent called her a liar to her face.","cn":"她的对手当着她面说她是撒谎精。"}},{"pos":"PHRASE 短语","cn":"脸上带着明显的…表情","en":"If a feeling is written all over your face or is written across your face, it is very obvious to other people from your expression.","ex":{"en":"Relief and gratitude were written all over his face","cn":"他一脸释然与感激。"}},{"pos":"","cn":"","en":"to shut the door in someone's face→see: ; to have egg on your face→see: ; to cut off your nose to spite your face→see: ; shut your face→see: ; a slap in the face→see: ;"},{"pos":"VERB 动词","cn":"面向;面对;朝着","en":"If someone or something faces a particular thing, person, or direction, they are positioned opposite them or are looking in that direction.","ex":{"en":"They stood facing each other","cn":"他们面对面站着。"}},{"pos":"VERB 动词","cn":"面对;面向","en":"If you face someone or something, you turn so that you are looking at them.","ex":{"en":"She stood up from the table and faced him","cn":"她从桌前站起来，面对着他。"}},{"pos":"VERB 动词","cn":"(不得不)面对，正视","en":"If you have to face a person or group, you have to stand or sit in front of them and talk to them, although it may be difficult and unpleasant.","ex":{"en":"Christie looked relaxed and calm as he faced the press","cn":"克里斯蒂面对记者，显得镇定自若。"}},{"pos":"VERB 动词","cn":"面临;面对;摆在…面前","en":"If you face or are faced with something difficult or unpleasant, or if it faces you, it is going to affect you and you have to deal with it.","ex":{"en":"Williams faces life in prison if convicted of attempted murder","cn":"如被判谋杀未遂，威廉斯将面临终身监禁。"}},{"pos":"VERB 动词","cn":"(使)直面，接受，正视(真理或事实等)","en":"If you face the truth or face the facts, you accept that something is true. If you face someone with the truth or with the facts, you try to make them accept that something is true.","ex":{"en":"Although your heart is breaking, you must face the truth that a relationship has ended","cn":"虽然你伤透了心，但也必须面对现实，一段感情已结束了。"}},{"pos":"VERB 动词","cn":"接受;容忍","en":"If you cannot face something, you do not feel able to do it because it seems so difficult or unpleasant.","ex":{"en":"I couldn't face the prospect of spending a Saturday night there, so I decided to press on","cn":"想到周六晚上要在那儿度过我就受不了，于是我决定要抓紧。"}},{"pos":"PHRASE 短语","cn":"让我们面对现实;承认(事实)吧","en":"You use the expression 'let's face it' when you are stating a fact or making a comment about something which you think the person you are talking to may find unpleasant or be unwilling to admit.","ex":{"en":"She was always attracted to younger men. But, let's face it, who is not?","cn":"她总是会被较年轻的男人吸引。不过，说实话，谁又不是呢？"}},{"pos":"","cn":"","en":"face the music→see: ;"},{"pos":"","cn":"","en":"相关词组：face down face up to"}]},"examples":[{"en":"It doesn't matter how well qualified you are, if your face doesn't fit, you don't stand a chance.","cn":"资历多好也没用，如果人家看你不对眼，你就不会有机会。"},{"en":"Sue's face was a picture (= she looked very surprised, angry, etc.) as she listened to her husband's speech.","cn":"苏听她丈夫讲话时，脸上露出又惊又气的表情。"}]},"fast":{"media":{"uk":"media/uk/fast__gb_1.mp3","us":"media/us/fast__us_1.mp3","img":["media/ldoce/img/fast.jpg"]},"oxford":{"phon":"fɑːst","pos":"adjective","senses":[{"en":"moving or able to move quickly","cn":"快的；迅速的；敏捷的","sc":"quick","ex":{"en":"a fast car/horse","cn":"速度快的汽车／马"}},{"en":"happening in a short time or without delay","cn":"迅速发生的；立即发生的","sc":"quick","ex":{"en":"We've recorded the fastest rate of increase for several years.","cn":"我们创下了几年来最高的增长率。"}},{"en":"able to do something quickly","cn":"动作迅速的；头脑灵活的","sc":"quick","ex":{"en":"a fast learner","cn":"领悟快的学习者"}},{"en":"producing or allowing quick movement","cn":"可供快速运动的","sc":"surface","ex":{"en":"It's a very fast road and people do not realize what speed they are doing.","cn":"这是条快车道，人们没有意识到自己的速度有多快。"}},{"en":"showing a time later than the true time","cn":"走得快","g":"[not before noun]","sc":"watch/clock","ex":{"en":"I'm early—my watch must be fast.","cn":"我早了，我的表肯定快了。"}},{"en":"very sensitive to light, and therefore useful when taking photographs in poor light or of something that is moving very quickly","cn":"感光快的","lab":"specialist","sc":"photographic film"},{"en":"safely fixed in position","cn":"系牢的；停靠稳妥的","sc":"fixed","ex":{"en":"He made the boat fast.","cn":"他把船系牢了。"}},{"en":"not likely to change or to come out when washed","cn":"不褪色的","sc":"colours in clothes"},{"en":"quickly","cn":"快速","lab":"formal","sc":"quickly","ex":{"en":"Don't drive so fast!","cn":"别把车开得这么快！"},"pos":"adverb"},{"en":"in a short time; without delay","cn":"不久；立即","sc":"quickly","ex":{"en":"Children grow up so fast these days.","cn":"如今孩子们长得真快。"},"pos":"adverb"},{"en":"doing the thing mentioned quickly","cn":"…快速的；…迅速的","sc":"fast-","ex":{"en":"a fast-flowing stream","cn":"湍急的溪流"},"pos":"adverb"},{"en":"completely","cn":"完全","sc":"completely","ex":{"en":"Within a few minutes she was fast asleep (= sleeping deeply).","cn":"几分钟后她就沉睡了。"},"pos":"adverb"},{"en":"to eat little or no food for a period of time, especially for religious or medical reasons","cn":"（尤因宗教或医疗原因）节食，禁食，斋戒","ex":{"en":"Muslims fast during Ramadan.","cn":"伊斯兰教徒在斋月期间斋戒。"},"pos":"verb"},{"en":"a period during which you do not eat food, especially for religious or health reasons","cn":"禁食期；斋戒期","ex":{"en":"to go on a fast","cn":"开始禁食"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"快的;迅速的","en":"Fast means happening, moving, or doing something at great speed. You also use fast in questions or statements about speed.","ex":{"en":"...fast cars with flashing lights and sirens","cn":"闪着灯、鸣着笛、飞速行驶的车辆"}},{"pos":"ADV-GRADED 副词","cn":"迅速地;立即","en":"You use fast to say that something happens without any delay.","ex":{"en":"When you've got a crisis like this you need professional help — fast!","cn":"当你遇到这样的危急情况，就需要专业救援了——要快！"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(钟表)偏快的，走得快的","en":"If a watch or clock is fast, it is showing a time that is later than the real time.","ex":{"en":"That clock's an hour fast.","cn":"那个钟快了一个小时。"}},{"pos":"ADV-GRADED 副词","cn":"紧紧地;牢牢地;死死地","en":"If you hold something fast, you hold it tightly and firmly. If something is stuck fast, it is stuck very firmly and cannot move.","ex":{"en":"She climbed the staircase cautiously, holding fast to the rail","cn":"她紧紧地抓着栏杆，小心翼翼地爬楼梯。"}},{"pos":"ADV-GRADED 副词","cn":"坚定地;毫不动摇地","en":"If you hold fast to a principle or idea, or if you stand fast, you do not change your mind about it, even though people are trying to persuade you to.","ex":{"en":"We can only try to hold fast to the age-old values of honesty, decency and concern for others","cn":"我们只能努力坚守那些古老的价值观：诚实、正派、关心他人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(颜色或染料)不褪色的，不掉色的","en":"If colours or dyes are fast, they do not come out of the fabrics they are used on when they get wet.","ex":{"en":"The fabric was ironed to make the colours fast.","cn":"为防止掉色，织物已经过熨烫。"}},{"pos":"ADJ 形容词","cn":"骄奢淫逸的;刺激而快乐的","en":"A fast way of life is one which involves a lot of enjoyable and expensive or dangerous activities.","ex":{"en":"Life in Detroit no longer satisfied him; he wanted the fast life of California.","cn":"他不再满意底特律的生活，想要过加利福尼亚那种刺激快乐的生活。"}},{"pos":"VERB 动词","cn":"斋戒;禁食;绝食","en":"If you fast, you eat no food for a period of time, usually for either religious or medical reasons, or as a protest.","ex":{"en":"I fasted for a day and half and asked God to help me.","cn":"我斋戒了一天半，祈求上帝伸出援手。"}},{"pos":"PHRASE 短语","cn":"熟睡的;沉睡的","en":"Someone who is fast asleep is completely asleep.","ex":{"en":"When he went upstairs five minutes later, she was fast asleep.","cn":"他5分钟后上楼时，她已睡熟。"}},{"pos":"PHRASE 短语","cn":"玩猫腻;玩弄","en":"If you say that someone is playing fast and loose, you are expressing disapproval of them for behaving in a deceitful, immoral, or irresponsible way.","ex":{"en":"There have been people who have played fast and loose with the rules.","cn":"有人在玩弄这些规则。"}},{"pos":"PHRASE 短语","cn":"欺骗;哄骗;愚弄","en":"If you say that someone has pulled a fast one on you, you mean that they have cheated or tricked you.","ex":{"en":"No doubt someone had pulled a fast one on her over a procedural matter.","cn":"无疑有人在程序性问题上骗了她。"}},{"pos":"","cn":"","en":"to make a fast buck→see: ; fast lane→see: ;"}]},"examples":[{"en":"In his latest movie, the action is fast and furious.","cn":"在他的最新电影中，情节起伏跌宕。"},{"en":"Britain is fast becoming a nation of fatties.","cn":"英国不久就要变成一个胖子国了。"}]},"fashion":{"media":{"uk":"media/uk/fashion__gb_1.mp3","us":"media/us/fashion__us_1.mp3"},"oxford":{"phon":"ˈfæʃn","pos":"noun","senses":[{"en":"a popular style of clothes, hair, etc. at a particular time or place; the state of being popular","cn":"（衣服、发式等的）流行款式，时兴式样；流行","g":"[uncountable, countable]","lab":"North American English also","ex":{"en":"the latest fashion trends","cn":"时装的最新趋势"}},{"en":"the business of making or selling clothes in new and different styles","cn":"时装业","g":"[uncountable]","ex":{"en":"They all want to work in fashion.","cn":"他们都想在时装业工作。"}},{"en":"a popular way of behaving, doing an activity, etc.","cn":"（行为、活动等的）时尚，时兴","g":"[countable]","ex":{"en":"This theory, though recent, is more than a passing fashion.","cn":"这个理论虽然最近才出现，但并不会昙花一现。"}},{"en":"to make or shape something, especially with your hands","cn":"（尤指用手工）制作，使成形，塑造","ex":{"en":"She fashioned a pot from the clay.","cn":"她用黏土制成一个罐。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"时装领域;时尚界","en":"Fashion is the area of activity that involves styles of clothing and appearance.","ex":{"en":"There are 20 full-colour pages of fashion for men","cn":"书中有 20 张有关男性时尚的彩色插页。"}},{"pos":"N-COUNT 可数名词","cn":"时装;时尚","en":"A fashion is a style of clothing or a way of behaving that is popular at a particular time.","ex":{"en":"In the early seventies I wore false eyelashes, as was the fashion","cn":"70 年代初我戴假睫毛，这在当时是时尚。"}},{"pos":"N-SING 单数名词","cn":"以…方式;以…方法","en":"If you do something in a particular fashion or after a particular fashion, you do it in that way.","ex":{"en":"There is another drug called DHE that works in a similar fashion","cn":"另外还有一种叫 DHE 的药物，药效也差不多。"}},{"pos":"VERB 动词","cn":"制作;制成","en":"If you fashion an object or a work of art, you make it.","ex":{"en":"Stone Age settlers fashioned necklaces from sheep's teeth.","cn":"石器时代的移居者用羊的牙做成项链。"}},{"pos":"PHRASE 短语","cn":"差强人意;马马虎虎","en":"If you say that something was done after a fashion, you mean that it was done, but not very well.","ex":{"en":"She was educated — after a fashion — at home","cn":"她算得上是受过教育——家庭教育。"}},{"pos":"PHRASE 短语","cn":"时兴／过时","en":"If something is in fashion, it is popular and approved of at a particular time. If it is out of fashion, it is not popular or approved of.","ex":{"en":"That sort of house is back in fashion","cn":"那种房子又时兴起来了。"}}]},"examples":[{"en":"She was proved right, in dramatic fashion, when the whole department resigned.","cn":"整个部门的人都辞了职，这惹人注目的事证明她是对的。"},{"en":"The fashion at the time was for teaching mainly the written language.","cn":"那时教学时兴的主要是书面语。"}]},"fails":{"lemma":"fail","media":{"uk":"media/uk/fail__gb_1.mp3","us":"media/us/fail__us_1.mp3"}},"fail":{"media":{"uk":"media/uk/fail__gb_1.mp3","us":"media/us/fail__us_1.mp3"},"oxford":{"phon":"feɪl","pos":"verb","senses":[{"en":"to not be successful in achieving something","cn":"失败；未能（做到）","g":"[intransitive, transitive]","sc":"not succeed","ex":{"en":"Many diets fail because they are boring.","cn":"许多规定饮食因单调乏味都不奏效。"}},{"en":"to not pass a test or an exam; to decide that somebody/something has not passed a test or an exam","cn":"不及格；评定不及格","g":"[transitive, intransitive]","sc":"test/exam","ex":{"en":"What will you do if you fail?","cn":"如果你考试不及格，你打算怎样做？"}},{"en":"to not do something","cn":"未做；未履行（某事）","g":"[intransitive]","sc":"not do something","ex":{"en":"People failed to recognize her talent.","cn":"人们未能认识到她的才能。"}},{"en":"to stop working","cn":"出故障；失灵","g":"[intransitive]","sc":"of machines/parts of body","ex":{"en":"The brakes on my bike failed half way down the hill.","cn":"我的自行车下山至中途车闸失灵了。"}},{"en":"to become weak","cn":"衰退","g":"[intransitive]","sc":"of health/sight/light","ex":{"en":"Her eyesight is failing.","cn":"她的视力日渐衰退。"}},{"en":"to disappoint somebody; to be unable to help when needed","cn":"使失望；有负于；无能为力","g":"[transitive]","lab":"figurative","sc":"disappoint somebody","ex":{"en":"When he lost his job, he felt he had failed his family.","cn":"他失去工作以后，感到辜负了家庭。"}},{"en":"to not be enough when needed or expected","cn":"不足；缺乏","g":"[intransitive]","sc":"not be enough","ex":{"en":"The crops failed again last summer.","cn":"上个夏季庄稼又歉收了。"}},{"en":"to be unable to continue","cn":"倒闭；破产","g":"[intransitive]","sc":"of company/business","ex":{"en":"Several banks failed during the recession.","cn":"经济衰退期间有几家银行倒闭了。"}},{"en":"the result of an exam in which a person is not successful","cn":"（考试）不及格","g":"[countable]","ex":{"en":"I got three passes and one fail.","cn":"我考试三门及格，一门不及格。"},"pos":"noun"},{"en":"a mistake or lack of success in doing something","cn":"失误；失败","g":"[countable, uncountable]","lab":"informal","ex":{"en":"The show was an epic fail.","cn":"这场演出惨不忍睹。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"失败;未能够;未做成","en":"If you fail to do something that you were trying to do, you are unable to do it or do not succeed in doing it.","ex":{"en":"The Workers' Party failed to win a single governorship","cn":"劳工党连一个州长职位也未能赢得。"}},{"pos":"VERB 动词","cn":"(活动、尝试、计划等)失败，不成功","en":"If an activity, attempt, or plan fails, it is not successful.","ex":{"en":"We tried to develop plans for them to get along, which all failed miserably","cn":"我们试图计划让他们好好相处，但均以惨败告终。"}},{"pos":"VERB 动词","cn":"没有做，未做(应做的事)","en":"If someone or something fails to do a particular thing that they should have done, they do not do it.","ex":{"en":"Some schools fail to set any homework","cn":"有些学校没有布置任何作业。"}},{"pos":"VERB 动词","cn":"出故障;失灵","en":"If something fails, it stops working properly, or does not do what it is supposed to do.","ex":{"en":"The lights mysteriously failed, and we stumbled around in complete darkness","cn":"灯不知怎么地不亮了，我们在一片黑暗中跌跌撞撞地走着。"}},{"pos":"VERB 动词","cn":"(企业)倒闭，破产;(机构)解体;(体系)崩溃","en":"If a business, organization, or system fails, it becomes unable to continue in operation or in existence.","ex":{"en":"So far this year, 104 banks have failed.","cn":"今年到目前为止，已有 104 家银行倒闭。"}},{"pos":"VERB 动词","cn":"(健康状况、体质等)衰弱，虚弱，衰退","en":"If something such as your health or a physical quality is failing, it is becoming gradually weaker or less effective.","ex":{"en":"He was 58, and his health was failing rapidly","cn":"他 58 岁，身体正在迅速衰老。"}},{"pos":"VERB 动词","cn":"辜负;使失望","en":"If someone fails you, they do not do what you had expected or trusted them to do.","ex":{"en":"We waited twenty-one years, don't fail us now.","cn":"我们等了 21 年了，如今不要让我们失望。"}},{"pos":"VERB 动词","cn":"不履行，未尽(职责)","en":"If someone fails in their duty or fails in their responsibilities, they do not do everything that they have a duty or a responsibility to do.","ex":{"en":"Lawyers are accused of failing in their duties to advise clients of their rights","cn":"律师们被控未尽到告知当事人其正当权利的职责。"}},{"pos":"VERB 动词","cn":"(品质或能力)有负于;(使)不如愿;不够","en":"If a quality or ability that you have fails you, or if it fails, it is not good enough in a particular situation to enable you to do what you want to do.","ex":{"en":"For once, the artist's fertile imagination failed him","cn":"这位画家丰富的想象力曾一度枯竭。"}},{"pos":"VERB 动词","cn":"不及格","en":"If someone fails a test, examination, or course, they perform badly in it and do not reach the standard that is required. →see usage note at:","ex":{"en":"I lived in fear of failing my end-of-term exams.","cn":"我总是担心期末考试不及格。"}},{"pos":"VERB 动词","cn":"评定…不及格;使不及格","en":"If someone fails you in a test, examination, or course, they judge that you have not reached a high enough standard in it.","ex":{"en":"...the two men who had failed him during his first year of law school.","cn":"在法学院一年级时让他不及格的两个人"}},{"pos":"PHRASE 短语","cn":"如果其他一切都不奏效的话;假如其他都行不通","en":"You say if all else fails to suggest what could be done in a certain situation if all the other things you have tried are unsuccessful.","ex":{"en":"If all else fails, I could always drive a truck.","cn":"如果其他都不行，我总还可以开卡车。"}},{"pos":"PHRASE 短语","cn":"(用以表示不赞成)不明白，看不出","en":"You can use I fail to see or I fail to understand in order to introduce a statement which indicates that you do not agree with what someone has said or done.","ex":{"en":"That's how it was in my day and I fail to see why it should be different now.","cn":"我那时候就是这样的，我搞不懂为什么现在非要弄得不一样。"}},{"pos":"PHRASE 短语","cn":"总是;一直","en":"You use without fail to emphasize that something always happens.","ex":{"en":"He attended every meeting without fail.","cn":"他逢会必到。"}},{"pos":"PHRASE 短语","cn":"(用以强调命令或承诺)一定，必须","en":"You use without fail to emphasize an order or a promise.","ex":{"en":"On the 30th you must without fail hand in some money for Alex","cn":"30 日那天你必须替亚历克斯交一些钱。"}}]},"examples":[{"en":"If all else fails, you can always sell your motorbike.","cn":"如果所有别的办法都不行，你总还可以卖掉摩托车。"},{"en":"His last months in office were marred by failing health.","cn":"由于健康恶化，他最后几个月的工作大受影响。"}]},"fade":{"media":{"uk":"media/uk/fade__gb_1.mp3","us":"media/us/fade__us_1.mp3"},"oxford":{"phon":"feɪd","pos":"verb","senses":[{"en":"to become or to make something become paler or less bright","cn":"（使）变淡，变暗","g":"[intransitive, transitive]","ex":{"en":"The curtains had faded in the sun.","cn":"窗帘已经给晒褪了色。"}},{"en":"to disappear gradually","cn":"逐渐消逝；逐渐消失","g":"[intransitive]","ex":{"en":"Her smile faded.","cn":"她的笑容逐渐消失。"}},{"en":"if a sports player, team, actor, etc. fades, they stop playing or performing as well as they did before","cn":"（运动员、运动队、演员等）走下坡路，衰退，衰落","g":"[intransitive]","ex":{"en":"Black faded on the final bend.","cn":"布莱克在最后一个弯道处速度慢了下来。"}}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)褪色;(使)变暗淡","en":"When a coloured object fades or when the light fades it, it gradually becomes paler.","ex":{"en":"All colour fades — especially under the impact of direct sunlight","cn":"所有颜色都会褪色——尤其是在阳光直射下。"}},{"pos":"VERB 动词","cn":"(光线)逐渐暗淡;(声音)逐渐减弱","en":"When light fades, it slowly becomes less bright. When a sound fades, it slowly becomes less loud.","ex":{"en":"Seaton lay on his bed and gazed at the ceiling as the light faded","cn":"光线渐渐暗了下去，西顿躺在床上，凝视着天花板。"}},{"pos":"VERB 动词","cn":"(所注视之物)逐渐暗淡，逐渐模糊直至消失","en":"When something that you are looking at fades, it slowly becomes less bright or clear until it disappears.","ex":{"en":"They observed the comet for 70 days before it faded from sight","cn":"他们观察了这颗彗星 70 天，直至其慢慢从视线中消失。"}},{"pos":"VERB 动词","cn":"变得不为人注意;变得无关紧要","en":"If someone or something fades, for example, into the background, they become hardly noticeable or very unimportant.","ex":{"en":"She had a way of fading into the background when things got rough","cn":"情况一有不妙，她总能退到幕后。"}},{"pos":"VERB 动词","cn":"(记忆)逐渐模糊;(感情)逐渐变淡;(可能性)逐渐变小","en":"If memories, feelings, or possibilities fade, they slowly become less intense or less strong.","ex":{"en":"Sympathy for the rebels, the government claims, is beginning to fade","cn":"政府宣称，对叛乱分子的同情开始消退。"}},{"pos":"VERB 动词","cn":"(笑容)慢慢收敛","en":"If someone's smile fades, they slowly stop smiling.","ex":{"en":"Jay nodded, his smile fading.","cn":"杰伊点点头，笑容慢慢隐去了。"}},{"pos":"PHRASAL VERB 短语动词","cn":"淡出;变得不再引人注目(直至完全消失)","en":"When something fades out, it slowly becomes less noticeable or less important until it disappears completely.","ex":{"en":"He thought her campaign would probably fade out soon in any case.","cn":"他认为不管怎样，她的竞选活动都可能会很快归于沉寂。"}},{"pos":"PHRASAL VERB 短语动词","cn":"(光线)逐渐暗淡;(画面)淡出; (声音)渐弱","en":"When light, an image, or a sound fades out, it disappears after gradually becoming weaker.","ex":{"en":"You'll need to be able to project two images onto the screen as the new one fades in and the old image fades out.","cn":"你得能将两个图像投射到屏幕上，让新的渐渐淡入，旧的渐渐淡出。"}},{"pos":"","cn":"","en":"相关词组：fade away fade out"}]},"examples":[{"en":"All other issues fade into insignificance compared with the struggle for survival.","cn":"与挣扎求存相比，所有其他问题都显得不重要了。"},{"en":"In the last weeks of her life she simply faded away.","cn":"她在生命的最后几个星期已是草枯灯油尽了。"}]},"fate":{"media":{"uk":"media/uk/fate__gb_1.mp3","us":"media/us/fate__us_1.mp3"},"oxford":{"phon":"feɪt","pos":"noun","senses":[{"en":"the things, especially bad things, that will happen or have happened to somebody/something","cn":"命中注定的事（尤指坏事）；命运的安排","g":"[countable]","ex":{"en":"The fate of the three men is unknown.","cn":"这三个人命运未卜。"}},{"en":"the power that is believed to control everything that happens and that cannot be stopped or changed","cn":"命运；天数；定数；天意","g":"[uncountable]","ex":{"en":"Fate was kind to me that day.","cn":"那天我很幸运。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"命运;宿命;定数;天意","en":"Fate is a power that some people believe controls and decides everything that happens, in a way that cannot be prevented or changed. You can also refer to the fates .","ex":{"en":"I see no use quarrelling with fate.","cn":"我看不出和命运抗争有什么用。"}},{"pos":"N-COUNT 可数名词","cn":"(人或物的)命运，遭际","en":"A person's or thing's fate is what happens to them.","ex":{"en":"The Russian Parliament will hold a special session later this month to decide his fate","cn":"俄罗斯议会本月晚些时候将举行特别会议决定他的命运。"}},{"pos":"PHRASE 短语","cn":"注定要失败;在劫难逃","en":"If something seals a person's or thing's fate, it makes it certain that they will fail or that something unpleasant will happen to them.","ex":{"en":"The call for a boycott could be enough to seal the fate of next week's general election","cn":"抵制选举的呼吁足以注定下周大选失败的命运。"}},{"pos":"","cn":"","en":"to tempt fate→see: ;"}]},"examples":[{"en":"By a strange twist of fate , Andy and I were on the same plane.","cn":"由于命运的奇特安排，我和安迪乘坐了同一架飞机。"},{"en":"She sat outside, waiting to find out her fate.","cn":"她坐在外面，等待命运对她作出的安排。"}]},"fairly":{"media":{"uk":"media/uk/fairly__gb_1.mp3","us":"media/us/fairly__us_1.mp3"},"oxford":{"phon":"ˈfeəli","pos":"adverb","senses":[{"en":"to some extent but not very","cn":"一定地；相当地","lab":"North American English","ex":{"en":"fairly simple/easy/straightforward","cn":"相当简单／容易／直接"}},{"en":"in a fair and reasonable way; honestly","cn":"公平合理地；公正地","ex":{"en":"He has always treated me very fairly.","cn":"他待我一直很公正。"}},{"en":"used to emphasize something that you are saying","cn":"（用以加强语气）确实，的确","lab":"old-fashioned","ex":{"en":"The time fairly raced by.","cn":"时间过得真快。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"相当;还;尚","en":"Fairly means to quite a large degree. For example, if you say that something is fairly old, you mean that it is old but not very old.","ex":{"en":"Both ships are fairly new","cn":"两艘船都还比较新。"}},{"pos":"ADV 副词","cn":"(用在形容词和副词前，代替very,表示强调，但比 very 语气弱)有些，有点，还算","en":"You use fairly instead of 'very' to add emphasis to an adjective or adverb without making it sound too forceful.","ex":{"en":"Were you always fairly bright at school?","cn":"你在学校一直还算聪明吧？"}},{"pos":"ADV 副词","cn":"(表示强调)在很大程度上，简直","en":"Fairly is used to emphasize that something happens to a very great degree or extent.","ex":{"en":"He fairly flew across the room","cn":"他简直是飞过了房间。"}},{"pos":"ADV-GRADED 副词","cn":"简直;几乎可以说","en":"You use fairly to suggest that a statement is probably or possibly true, and therefore deserves to be accepted or considered.","ex":{"en":"It can no doubt be fairly argued that Sir John, whose pay is linked to performance, is entitled to every penny","cn":"毋庸置疑，既然约翰爵士的薪水是与业绩挂钩的，他的每一分钱都是理所应得的。"}}]},"examples":[{"en":"I know him fairly well, but I wouldn't say we were really close friends.","cn":"我相当了解他，但并不是说我们是真正的密友。"},{"en":"Her attitude could fairly be described as hostile.","cn":"公平而论，她的态度可以说是怀有敌意。"}]},"fatty":{"oxford":{"phon":"ˈfæti","pos":"adjective","senses":[{"en":"containing a lot of fat; consisting of fat","cn":"富含脂肪的；肥胖的；脂肪的","ex":{"en":"fatty foods","cn":"高脂食物"}},{"en":"an offensive word for a person who you think is fat","cn":"胖子","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(食物)含脂肪多的,肥的,高脂的","en":"Fatty food contains a lot of fat.","ex":{"en":"Don't eat fatty food or chocolates","cn":"不要吃高脂食物或巧克力。"}},{"pos":"ADJ 形容词","cn":"(酸、组织等)含脂肪的","en":"Fatty acids or fatty tissues, for example, contain or consist of fat.","ex":{"en":"...fatty acids","cn":"脂肪酸"}},{"pos":"N-COUNT 可数名词","cn":"胖子;胖墩;肥仔","en":"If you call someone a fatty, you are criticizing or insulting them for being fat.","ex":{"en":"Consuming this amount of food could turn these fit players into fatties","cn":"这些体格健壮的运动员吃这么多会变成胖子的。"}}]},"media":{"uk":"media/uk/fatty__gb_1.mp3","us":"media/us/fatty__us_1.mp3"},"examples":[{"en":"Britain is fast becoming a nation of fatties.","cn":"英国很快就会变成胖子国。"},{"en":"fatty foods","cn":"高脂食物"}]},"factory":{"media":{"uk":"media/uk/factory__gb_1.mp3","us":"media/us/factory__us_1.mp3"},"oxford":{"phon":"ˈfæktri","pos":"noun","senses":[{"en":"a building or group of buildings where goods are made, mainly by machine","cn":"工厂；制造厂","ex":{"en":"a car factory","cn":"汽车制造厂"}},{"en":"a person or organization that continuously produces a large quantity of a particular thing","cn":"工厂：连续生产大量特定物品的个人或组织","lab":"disapproving","ex":{"en":"This record label has become a real hit factory (= one that produces a lot of successful songs).","cn":"该唱片公司已成为一家真正的热门工厂（=生产许多成功歌曲的工厂）。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"工厂","en":"A factory is a large building where machines are used to make large quantities of goods.","ex":{"en":"He owned furniture factories in New York State.","cn":"他在纽约州有几家家具厂。"}}]},"examples":[{"en":"Raw materials were carried to the works by barge.","cn":"原材料由驳船运到工厂。"},{"en":"a cotton/paper/textile/woollen mill","cn":"棉纺厂；造纸厂；纺织厂；毛纺厂"}]},"familial":{"media":{"uk":"media/uk/familial__gb_1.mp3","us":"media/us/familial__us_1.mp3"},"oxford":{"phon":"fəˈmɪliəl","pos":"adjective","senses":[{"en":"related to or typical of a family","cn":"家庭的；家族的","lab":"formal"},{"en":"affecting several members of a family","cn":"家族性的；家庭遗传的","lab":"medical","ex":{"en":"familial left-handedness","cn":"家族遗传的左撇子"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"家庭（或家族）的;家庭(或家族)特有的","en":"Familial means relating to families in general, or typical of a family.","ex":{"en":"Gerard also took on wider familial respon-sibilities.","cn":"杰勒德还承担了更多的家庭责任。"}}]},"examples":[{"en":"familial left-handedness","cn":"家族遗传的左撇子"},{"en":"familial obligations","cn":"家庭责任"}]},"factotum":{"media":{"uk":"media/uk/factotum__gb_1.mp3","us":"media/us/factotum__us_1.mp3"},"oxford":{"phon":"fækˈtəʊtəm","pos":"noun","senses":[{"en":"a person employed to do a wide variety of jobs for somebody","cn":"勤杂工；事务总管","ex":{"en":"I became her assistant and general factotum.","cn":"我成了她的助手和总杂役。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"勤杂工;事务总管","en":"A factotum is a servant who is employed to do a wide variety of jobs for someone."}]}},"facilitate":{"media":{"uk":"media/uk/facilitate__gb_1.mp3","us":"media/us/facilitate__us_1.mp3"},"oxford":{"phon":"fəˈsɪlɪteɪt","pos":"verb","senses":[{"en":"to make an action or a process possible or easier","cn":"促进；促使；使便利","ex":{"en":"The new trade agreement should facilitate more rapid economic growth.","cn":"新贸易协定应当会加快经济发展。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"促进;使便利","en":"To facilitate an action or process, especially one that you would like to happen, means to make it easier or more likely to happen.","ex":{"en":"The new airport will facilitate the development of tourism","cn":"新机场将促进旅游业的发展。"}}]},"examples":[{"en":"The new trade agreement should facilitate more rapid economic growth.","cn":"新贸易协定应当会加快经济发展。"},{"en":"Structured teaching facilitates learning.","cn":"有条理的教导有利于学习。"}]},"fastening":{"oxford":{"phon":"ˈfɑːsnɪŋ","pos":"noun","senses":[{"en":"a device, such as a button or a zip, used to close a piece of clothing; a device used to close a window, bag, etc. tightly","cn":"纽扣；拉链；扣件"},{"en":"the place where something, especially a piece of clothing, fastens; the way something fastens","cn":"（尤指衣服的）扣处，扣法","ex":{"en":"The trousers have a fly fastening.","cn":"这条裤子是前开口的。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"紧固件;扣件","en":"A fastening is something such as a clasp or zip that you use to fasten something and keep it shut.","ex":{"en":"The sundress has a neat back zip fastening.","cn":"这件背心裙背部有一个巧妙的拉链。"}}]},"media":{"uk":"media/uk/fastening__gb_1.mp3","us":"media/us/fastening__us_1.mp3"},"examples":[{"en":"The trousers have a fly fastening.","cn":"这条裤子是前开口的。"}],"base":"fasten"},"farm":{"media":{"uk":"media/uk/farm__gb_1.mp3","us":"media/us/farm__us_1.mp3"},"oxford":{"phon":"fɑːm","pos":"noun","senses":[{"en":"an area of land, and the buildings on it, used for growing crops and/or keeping animals","cn":"农场","lab":"North American English","ex":{"en":"a 200-hectare farm","cn":"一个 200 公顷的农场"}},{"en":"the main house on a farm, where the farmer lives","cn":"农场住宅，农舍（农场主的住房）"},{"en":"a place where particular fish or animals are kept in order to produce young","cn":"养殖场；饲养场","ex":{"en":"a trout/mink farm","cn":"鳟鱼养殖场；水貂饲养场"}},{"en":"to use land for growing crops and/or keeping animals","cn":"务农；种田；从事畜牧业","g":"[intransitive, transitive]","ex":{"en":"The family has farmed in Kent for over two hundred years.","cn":"这个家族在肯特务农两百多年了。"},"pos":"verb"},{"en":"to keep fish or birds in order to produce young and sell them for food","cn":"饲养；养殖","g":"[transitive]","ex":{"en":"Salmon are farmed in net pens near coasts.","cn":"鲑鱼是在海岸附近的网箱里养殖的。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"农场;牧场","en":"A farm is an area of land, together with the buildings on it, that is used for growing crops or raising animals, usually in order to sell them.","ex":{"en":"Farms in France are much smaller than those in the United States or even Britain.","cn":"法国的农场比美国甚至是英国的农场都要小很多。"}},{"pos":"VERB 动词","cn":"耕种;在…上从事畜牧业","en":"If you farm an area of land, you grow crops or keep animals on it.","ex":{"en":"They farmed some of the best land in Scotland","cn":"他们耕种着苏格兰最好的一部分土地。"}},{"pos":"N-COUNT 可数名词","cn":"养殖场;饲养地","en":"A mink farm or a fish farm, for example, is a place where a particular kind of animal or fish is bred and kept in large quantities in order to be sold.","ex":{"en":"...trout fresh from a local trout farm.","cn":"刚刚从当地鲑鱼养殖场捕捞的新鲜鲑鱼"}},{"pos":"","cn":"","en":"相关词组：farm out"}]},"examples":[{"en":"The company farms out a lot of work to freelancers.","cn":"这家公司把大量工作包给了个体人员。"},{"en":"The family has farmed in Kent for over two hundred years.","cn":"这个家族在肯特务农两百多年了。"}]},"fatigue":{"media":{"uk":"media/uk/fatigue__gb_1.mp3","us":"media/us/fatigue__us_1.mp3"},"oxford":{"phon":"fəˈtiːɡ","pos":"noun","senses":[{"en":"a feeling of being extremely tired, usually because of hard work or exercise","cn":"极度疲劳；极度劳累","g":"[uncountable]","ex":{"en":"physical and mental fatigue","cn":"精疲力竭"}},{"en":"a feeling of not wanting to do a particular activity any longer because you have done too much of it","cn":"厌倦","g":"[uncountable]","ex":{"en":"Launching too many charity appeals risks bringing on compassion fatigue (= a loss of the ability to feel pity for other people’s suffering).","cn":"发起太多的慈善呼吁可能会导致同情心疲劳（=丧失同情他人痛苦的能力）。"}},{"en":"weakness in metal or wood caused by repeated bending or stretching","cn":"（金属或木材的）疲劳","g":"[uncountable]","ex":{"en":"The wing of the plane showed signs of metal fatigue.","cn":"机翼显示出金属疲劳的迹象。"}},{"en":"loose clothes worn by soldiers","cn":"（士兵穿的）工作服","g":"[plural]","ex":{"en":"soldiers in combat fatigues","cn":"身穿作战服的军人"}},{"en":"duties, such as cleaning and cooking, that soldiers have to do, especially as a punishment","cn":"士兵杂役（如做打扫、帮厨，尤指作为惩罚）","g":"[plural]","lab":"especially North American English","ex":{"en":"We were all put on cookhouse fatigues for a week.","cn":"我们都穿上了一周的厨房工作服。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"疲惫;疲劳;疲倦","en":"Fatigue is a feeling of extreme physical or mental tiredness.","ex":{"en":"She continued to have severe stomach cramps, aches, fatigue, and depression","cn":"她仍然患有严重的胃痉挛，感觉疼痛、疲乏、抑郁。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"疲劳;厌倦","en":"You can say that people are suffering from a particular kind of fatigue when they have been doing something for a long time and feel they can no longer continue to do it.","ex":{"en":"...compassion fatigue caused by endless TV and celebrity appeals.","cn":"没完没了的电视节目和名人呼吁而导致的同情心疲劳"}},{"pos":"N-PLURAL 复数名词","cn":"(士兵的)作训服，工作服","en":"Fatigues are clothes that soldiers wear when they are fighting or when they are doing routine jobs.","ex":{"en":"He never expected to return home wearing US combat fatigues.","cn":"他从没想到会穿着美国军服回家。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(金属或木材的)疲劳","en":"Fatigue in metal or wood is a weakness in it that is caused by repeated stress. Fatigue can cause the metal or wood to break.","ex":{"en":"The problem turned out to be metal fatigue in the fuselage.","cn":"问题原来是飞机机身出现金属疲劳。"}}]},"examples":[{"en":"I was dropping with fatigue and could not keep my eyes open.","cn":"我快要累倒了，眼睛也睁不开了。"},{"en":"Driver fatigue was to blame for the accident.","cn":"这个事故是驾驶员疲劳所致。"}]},"fascination":{"media":{"uk":"media/uk/fascination__gb_1.mp3","us":"media/us/fascination__us_1.mp3"},"oxford":{"phon":"ˌfæsɪˈneɪʃn","pos":"noun","senses":[{"en":"a very strong attraction, that makes something very interesting","cn":"魅力；极大的吸引力","g":"[countable, usually singular]","ex":{"en":"London has a fascination all of its own.","cn":"伦敦有一种独特的魅力。"}},{"en":"the state of being very attracted to and interested in somebody/something","cn":"入迷；着迷","g":"[uncountable, singular]","lab":"informal","ex":{"en":"The girls listened in fascination as the story unfolded.","cn":"故事情节逐渐展开，小女孩都入迷地听着。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"入迷;着迷;酷爱","en":"Fascination is the state of being greatly interested in or delighted by something.","ex":{"en":"I've had a lifelong fascination with the sea and with small boats.","cn":"我一生都对大海和小船着迷。"}},{"pos":"N-COUNT 可数名词","cn":"魅力;令人着迷的事物","en":"A fascination is something that fascinates people.","ex":{"en":"...a series focusing on the fascinations of the British Museum.","cn":"主要讲述大英博物馆魅力的系列节目"}}]},"examples":[{"en":"The fascination of the game lies in trying to guess what your opponent is thinking.","cn":"这个游戏的魅力就在于要努力去猜对手在想什么。"},{"en":"The girls listened in fascination as the story unfolded.","cn":"故事情节逐渐展开，小女孩都入迷地听着。"}]},"father":{"media":{"uk":"media/uk/father__gb_1.mp3","us":"media/us/father__us_1.mp3"},"oxford":{"phon":"ˈfɑːðə(r)","pos":"noun","senses":[{"en":"a male parent of a child or an animal; a person who is acting as the father to a child","cn":"父亲；爸爸","lab":"old-fashioned","ex":{"en":"My father died in 2017.","cn":"我父亲于 2017 年去世。"}},{"en":"a person’s ancestors (= people who are related to you who lived in the past)","cn":"祖先","g":"[plural]","lab":"literary","ex":{"en":"the land of our fathers","cn":"我们祖先的土地"}},{"en":"the first man to introduce a new way of thinking about something or of doing something","cn":"创始人；奠基者；先驱；鼻祖","ex":{"en":"Henry Moore is considered to be the father of modern British sculpture.","cn":"亨利·穆尔被认为是现代英国雕塑之父。"}},{"en":"used by Christians to refer to God","cn":"天父；上帝","ex":{"en":"Father, forgive us.","cn":"天父，宽恕我们吧。"}},{"en":"the title of a priest, especially in the Roman Catholic Church and the Orthodox Church","cn":"（尤指天主教和东正教的）神父","ex":{"en":"Father Dominic","cn":"多米尼克神父"}},{"en":"to become the father of a child by making a woman pregnant","cn":"成为父亲；做父亲","ex":{"en":"He claims to have fathered over 20 children.","cn":"他声称有 20 多个亲生子女。"},"pos":"verb"},{"en":"to create new ideas or a new way of doing something","cn":"创立（新思想）；创造，发明（新方法）","pos":"verb"}]},"collins":{"senses":[{"pos":"N-FAMILY 家庭成员名词","cn":"父亲;爸爸","en":"Your father is your male parent. You can also call someone your father if he brings you up as if he was this man.","ex":{"en":"His father was a painter","cn":"他父亲是个画家。"}},{"pos":"VERB 动词","cn":"成为…的父亲;是…的父亲","en":"When a man fathers a child, he makes a woman pregnant and their child is born.","ex":{"en":"She claims Mark fathered her child","cn":"她宣称马克是孩子的父亲。"}},{"pos":"N-COUNT 可数名词","cn":"发明者;鼻祖;创始人;奠基人","en":"The man who invented or started something is sometimes referred to as the father of that thing.","ex":{"en":"...Max Dupain, regarded as the father of modern photography.","cn":"被视为现代摄影之父的马克斯·杜培"}},{"pos":"N-VOC; N-TITLE; N-COUNT称呼名词；头衔名词；可数名词","cn":"神父","en":"In some Christian churches, priests are addressed or referred to as Father .","ex":{"en":"I would like your advice on a matter of conscience, Father.","cn":"我想就一件有关良心的事征求您的建议，神父。"}},{"pos":"N-PROPER 专有名词","cn":"(基督教)天父，上帝","en":"Christians often refer to God as our Father or address him as Father .","ex":{"en":"...Our Father in Heaven.","cn":"我们的天父"}}]},"examples":[{"en":"Henry Moore is considered to be the father of modern British sculpture.","cn":"亨利 · 穆尔被认为是现代英国雕塑之父。"},{"en":"Our new boss is a father of three (= he has three children).","cn":"我们的新老板是三个孩子的父亲。"}]},"faster":{"lemma":"fast"},"failings":{"lemma":"fail"},"fancied":{"lemma":"fancy"},"falling":{"lemma":"fall"},"fashioned":{"lemma":"fashion"},"farmhands":{"lemma":"farmhand"},"faces":{"lemma":"face"},"faults":{"lemma":"fault"},"facts":{"lemma":"fact"},"families":{"lemma":"family"},"favorite":{"lemma":"favourite","media":{"uk":"media/ldoce/hwd/bre/6/ld41favorite.mp3","us":"media/ldoce/hwd/ame/b/favorite1.mp3"}},"fabrics":{"lemma":"fabric"},"fathered":{"lemma":"father"},"favor":{"lemma":"favour","media":{"uk":"media/ldoce/hwd/bre/c/favor0205.mp3","us":"media/ldoce/hwd/ame/a/favor1.mp3"}},"faculties":{"lemma":"faculty"},"favored":{"lemma":"favoured","media":{"uk":"media/ldoce/hwd/bre/5/favored0205.mp3","us":"media/ldoce/hwd/ame/f/favored.mp3"}},"faded":{"lemma":"fade"},"faucets":{"oxford":{"phon":"ˈfɔːsɪt","pos":"noun","senses":[{"en":"a device that controls the flow of water from a pipe","cn":"龙头；旋塞"}]}},"facilities":{"lemma":"facility"},"failures":{"lemma":"failure"},"factories":{"lemma":"factory"},"fasting":{"oxford":{"phon":"ˈfɑːstɪŋ","pos":"noun","senses":[{"en":"the practice of eating little or no food for a period of time, especially for religious or health reasons","cn":"禁食；斋戒","ex":{"en":"A day of prayer and fasting was ordained.","cn":"规定了祈祷和禁食的一天。"}}]},"base":"fast"},"factored":{"lemma":"factor"},"faced":{"lemma":"face"},"factors":{"lemma":"factor"},"farms":{"lemma":"farm"},"favouritism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"偏心;偏袒;偏爱","en":"If you accuse someone of favouritism, you disapprove of them because they unfairly help or favour one person or group much more than another.","ex":{"en":"Maria loved both the children. There was never a hint of favouritism.","cn":"玛丽亚对两个孩子都疼爱有加，向来一视同仁。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when a teacher, parent, manager etc treats one person in a much better way than the others because they like that person, not because that person deserves it","cn":""},{"en":"if a particular person or group gets preferential treatment , they are treated better than other people and therefore have an advantage over them","cn":""},{"en":"when someone in authority gives jobs or special treatment to members of their family - use this to show disapproval","cn":""}]},"collocations":{"phrases":["VERB + FAVOURITISM show | accuse sb of","PREP. ~ to/towards She denied showing favouritism to any of her students.","PHRASES accusations of favouritism He resigned over accusations of favouritism."]},"media":{"uk":"media/ldoce/hwd/bre/c/favoritism0205.mp3","us":"media/ldoce/hwd/ame/4/favoritism.mp3"},"examples":[{"en":"The students accused the teacher of favouritism.","cn":"学生指责老师有偏心。"},{"en":"their favouritism towards their first son","cn":"他们对长子的偏爱"}],"oxford":{"phon":"ˈfeɪvərɪtɪzəm","pos":"noun","senses":[{"en":"the act of unfairly treating one person better than others because you like them better","cn":"偏爱；偏袒","ex":{"en":"The students accused the teacher of favouritism.","cn":"学生指责老师偏心。"}}]}},"facet":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"部分;方面","en":"A facet of something is a single part or aspect of it.","ex":{"en":"The caste system shapes nearly every facet of Indian life.","cn":"种姓制度决定了印度生活的几乎每一个方面。"}},{"pos":"N-COUNT 可数名词","cn":"(钻石等宝石的)琢面，饰面，切面","en":"The facets of a diamond or other precious stone are the flat surfaces that have been cut on its outside."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of several parts of someone’s character, a situation etc 〔","cn":"性格﹑情况等的〕方面"},{"en":"consisting of many different parts","cn":"多方面的"},{"en":"one of the flat sides of a cut jewel 〔","cn":"宝石的〕琢面﹐刻面﹐小平面"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A facet is one side or aspect of something. If you’re thinking about quitting your day job to become a circus performer, you should first consider every facet of what your new life would be like."}]},"collocations":{"phrases":["ADJ. essential, important | common | tiny | interesting | hidden","VERB + FACET have She has another important facet to her personality."]},"media":{"uk":"media/ldoce/hwd/bre/b/facet0205.mp3","us":"media/ldoce/hwd/ame/b/facet.mp3"},"examples":[{"en":"Now let's look at another facet of the problem.","cn":"现在咱们看问题的另一面。"},{"en":"He has travelled extensively in China, recording every facet of life.","cn":"他在中国游历颇广﹐记录下了生活的方方面面。"}],"oxford":{"phon":"ˈfæsɪt","pos":"noun","senses":[{"en":"a particular part or aspect of something","cn":"（事物的）部分，方面","ex":{"en":"Now let's look at another facet of the problem.","cn":"现在咱们看问题的另一面。"}},{"en":"one of the flat sides of a jewel","cn":"（宝石的）小平面，琢面"}]}},"fairness":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"公平;公道;公正","en":"Fairness is the quality of being reasonable, right, and just.","ex":{"en":"He says the new document will guarantee fairness for blacks in Georgia.","cn":"他说这个新文件将保证佐治亚州的黑人受到公平对待。"}},{"pos":"PHRASE 短语","cn":"说句公道话;公平地说;公正地说","en":"You use fairness in expressions such as in fairness to and in all fairness when you want to add a favourable comment about someone or something that you have just mentioned and to correct a false impression that you might have given.","ex":{"en":"In fairness to Bates, he always made it very clear that Webb was only on trial until the end of the season","cn":"替贝茨说句公道话，他意思一直很明确，韦布在本赛季结束前只是试用。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when something is done or decided in a way that is fair and right","cn":""},{"en":"when a situation is dealt with in a way that is fair and right, especially as the result of an official or legal decision","cn":""},{"en":"if there is fair play in a situation, activity, game etc, people behave fairly and no one tries to cheat","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Fairness is the quality of making judgments that are free from discrimination. Judges, umpires, and teachers should all strive to practice fairness ."}]},"collocations":{"phrases":["ADJ. strict","VERB + FAIRNESS achieve, ensure, guarantee a way of achieving fairness to the accused","FAIRNESS + VERB call for sth, demand sth, require sth Fairness demanded an equal division of the winnings.","PREP. in (all) ~ In all fairness to him, I should say that most of his story is true. | with ~ They were all treated with strict fairness. |","PHRASES a sense of fairness Children have a very strong sense of fairness."]},"media":{"uk":"media/ldoce/hwd/bre/d/fairness0205.mp3","us":"media/ldoce/hwd/ame/9/laadfairness.mp3"},"examples":[{"en":"A tan emphasized the fairness of her hair.","cn":"晒黑的皮肤更加衬托出了她的头发颜色有多浅。"},{"en":"In all fairness to him, he did try to stop her leaving.","cn":"不能怪他，他确实曾设法阻止她离开。"}],"oxford":{"phon":"ˈfeənəs","pos":"noun","senses":[{"en":"the quality of treating people equally or in a way that is reasonable","cn":"公正性；公平合理性","ex":{"en":"The fairness of the judicial system is being questioned.","cn":"司法制度的公正性受到质疑。"}},{"en":"a pale colour of skin or hair","cn":"（皮肤）白皙；（头发）浅色","ex":{"en":"A tan emphasized the fairness of her hair.","cn":"晒黑的皮肤更加衬托出了她那浅色的头发。"}}]}},"fax":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"传真机","en":"A fax or a fax machine is a piece of equipment used to copy documents by sending information electronically along a telephone line, and to receive copies that are sent in this way.","ex":{"en":"...a modern reception desk with telephone and fax","cn":"有电话和传真机的现代化接待处"}},{"pos":"VERB 动词","cn":"用传真机发送","en":"If you fax a document to someone, you send it from one fax machine to another.","ex":{"en":"I faxed a copy of the agreement to each of the investors","cn":"我给每个投资人都传真了一份合同。"}},{"pos":"N-COUNT 可数名词","cn":"传真件","en":"You can refer to a copy of a document that is transmitted by a fax machine as a fax .","ex":{"en":"I sent him a long fax, saying I didn't need a maid.","cn":"我给他发了一份很长的传真，说我不需要女仆。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a letter or message that is sent in electronic form down a telephone line and then printed using a special machine","cn":"传真（信件）"},{"en":"a machine used for sending and receiving faxes","cn":"传真机"},{"en":"the system of sending letters and messages using a fax machine","cn":"传真通信﹐传真"}]},"collocations":{"phrases":["ADJ. incoming","VERB + FAX send (sb) | get, receive","FAX + NOUN machine | number | line | signal Our fax machine differentiates between an incoming fax signal and a voice call. | message | mode","PREP. by ~ There was still time to receive copies by fax. | ~ from, ~ to"]},"media":{"uk":"media/ldoce/hwd/bre/e/fax_n0205.mp3","us":"media/ldoce/hwd/ame/7/fax1.mp3"},"examples":[{"en":"You can send faxes by email from your computer.","cn":"你可以通过计算机用电子邮件发送传真信件。"},{"en":"Could you fax me the latest version?","cn":"你可不可以把最新版本传真给我？"}],"oxford":{"phon":"fæks","pos":"noun","senses":[{"en":"a machine that sends and receives documents in an electronic form along phone wires and then prints them","cn":"传真机","g":"[countable]","ex":{"en":"The office equipment included a photocopier and a fax, but no computer.","cn":"办公设备包括复印机和传真机，但没有电脑。"}},{"en":"a system for sending documents using scanned images over a phone line or the internet","cn":"传真（系统）","g":"[uncountable]","ex":{"en":"In those days we often sent documents by fax.","cn":"那时候我们经常用传真发送文件。"}},{"en":"a letter or message sent by fax","cn":"传真信件；传真电文；明电","g":"[countable]","lab":"British English","ex":{"en":"You can still send faxes via email.","cn":"现在仍然可以用电子邮件发送传真。"}},{"en":"to send somebody a document, message, etc. by fax","cn":"传真（文档、信件等）","ex":{"en":"Could you fax me the latest version?","cn":"你可不可以把最新版本传真给我？"},"pos":"verb"}]}},"fanatic":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(政治、宗教等的)狂热分子","en":"If you describe someone as a fanatic, you disapprove of them because you consider their behaviour or opinions to be very extreme, for example in the way they support particular religious or political ideas.","ex":{"en":"I am not a religious fanatic but I am a Christian.","cn":"我不是宗教狂热分子，但我是基督徒。"}},{"pos":"N-COUNT 可数名词","cn":"(对某一活动、运动、生活方式)入迷者，痴狂者","en":"If you say that someone is a fanatic, you mean that they are very enthusiastic about a particular activity, sport, or way of life.","ex":{"en":"Both Rod and Phil are football fanatics.","cn":"罗德和菲尔两人都是足球迷。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"同 fanatical","en":"Fanatic means the same as fanatical ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who has extreme opinions, especially about politics or religion","cn":""},{"en":"someone who agrees with and supports very extreme religious or political aims, is completely certain that their opinions are right, and who is thought to be dangerous","cn":""},{"en":"someone who believes very deeply in a set of political aims and ideas, and will not accept or support any changes to them, even if this is unreasonable or unhelpful","cn":""}]},"vocab":{"pos":"n adj","senses":[{"en":"If you’re apt to come off as a little zany and express extreme enthusiasm for a particular idea or thing, you may be described as a fanatic . \"She’s a real vegetable fanatic ; I’ve never seen someone so enthusiastic about gardening methods."}]},"collocations":{"phrases":["ADJ. real | cricket, fitness, football, keep-fit, health, sports He's a real football fanatic. | religious"]},"media":{"uk":"media/ldoce/hwd/bre/6/fanatic0205.mp3","us":"media/ldoce/hwd/ame/d/fanatic.mp3"},"examples":[{"en":"She's fanatical about healthy eating.","cn":"她对健康饮食着了迷。"},{"en":"a fitness/crossword, etc. fanatic","cn":"热衷于健美、纵横填字游戏等的人"}],"oxford":{"phon":"fəˈnætɪk","pos":"adjective","senses":[{"en":"holding, expressing or connected with extreme or dangerous opinions","cn":"极端分子；狂热信徒","ex":{"en":"fanatic followers of the cult leader","cn":"邪教领袖的狂热追随者"}},{"en":"a person who holds extreme or dangerous opinions","cn":"极端分子；狂热信徒","lab":"disapproving","ex":{"en":"religious fanatics","cn":"宗教极端分子"},"pos":"noun"},{"en":"a person who is extremely enthusiastic about something","cn":"入迷者","lab":"informal","ex":{"en":"a fitness/crossword fanatic","cn":"热衷于健美／纵横字谜的人"},"pos":"noun"}]}},"fan":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"迷(尤指对某位名人或某项体育运动极为喜爱和感兴趣的人)","en":"If you are a fan of someone or something, especially a famous person or a sport, you like them very much and are very interested in them.","ex":{"en":"If you're a Billy Crystal fan, you'll love this movie","cn":"如果你是比利·克里斯托的影迷，你会喜爱这部影片。"}},{"pos":"N-COUNT 可数名词","cn":"扇子","en":"A fan is a flat object that you hold in your hand and wave in order to move the air and make yourself feel cooler."},{"pos":"VERB 动词","cn":"给…扇风","en":"If you fan yourself or your face when you are hot, you wave a fan or other flat object in order to make yourself feel cooler.","ex":{"en":"She would have to wait in the truck, fanning herself with a piece of cardboard","cn":"她只得在卡车里等着，用一块纸板给自己扇风。"}},{"pos":"N-COUNT 可数名词","cn":"电扇;风扇","en":"A fan is a piece of electrical or mechanical equipment with blades that go round and round. It keeps a room or machine cool or gets rid of unpleasant smells.","ex":{"en":"He cools himself in front of an electric fan.","cn":"他在电扇前让自己凉快些。"}},{"pos":"N-COUNT 可数名词","cn":"扇形","en":"You can describe anything that has the shape of a wide 'V' with a curved part above it as a fan .","ex":{"en":"...its fan of tail feathers.","cn":"它扇形的尾羽"}},{"pos":"VERB 动词","cn":"把(火)扇旺;把(火)吹旺","en":"If you fan a fire, you wave something flat next to it in order to make it burn more strongly. If a wind fans a fire, it blows on it and makes it burn more strongly.","ex":{"en":"Kneeling in front of the open hearth, old Maria was fanning the smoldering fire","cn":"老玛丽亚跪在壁炉前的空地上，扇着闷燃的炉火。"}},{"pos":"VERB 动词","cn":"(故意)煽动，激发(恐惧、仇恨、热情等)","en":"If someone fans an emotion such as fear, hatred, or passion, they deliberately do things to make people feel the emotion more strongly.","ex":{"en":"He said students were fanning social unrest with their violent protests.","cn":"他说学生们的暴力抗议会煽动起社会动乱。"}},{"pos":"","cn":"","en":"to fan the flames→see: ; the shit hit the fan→see: ;"},{"pos":"PHRASAL VERB 短语动词","cn":"四散;散开","en":"If a group of people or things fan out, they move forwards away from a particular point in different directions.","ex":{"en":"The main body of British, American, and French troops had fanned out to the west","cn":"英、美、法部队的主力已经向西面散开。"}},{"pos":"PHRASAL VERB-ERG","cn":"(使)展开(或打开)成圆形(或半圆形)","en":"If something fans out, or if you fan it out, it spreads out or opens out into the shape of a circle or half circle.","ex":{"en":"She suddenly raised her arms and spun, so the dress's full skirt fanned out in a bright circle","cn":"她突然举起双臂旋转起来，连衣裙的裙身呈圆形完全展开，明艳照人。"}},{"pos":"","cn":"","en":"相关词组：fan out"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who likes a particular sport, team, or famous entertainer very much","cn":""},{"en":"someone who likes a particular activity very much","cn":""},{"en":"someone who likes a subject, activity, performer etc very much, is very interested in them and knows a lot about them","cn":""}]},"collocations":{"phrases":["ADJ. adoring, ardent, avid, big, dedicated, devoted, great, keen, loyal, number one, real I'm a big fan of Italian food. one of the team's b","VERB + FAN delight The big band sound of Syd Lawrence and his Orchestra will delight fans. | disappoint, let down Fans will not be disappoin","FAN + VERB converge on sth, gather, turn out/up Soccer fans converged on the capital for the cup final. More than 40,000 fans turned up for ","FAN + NOUN club, letter, mail 2 machine that creates a current of air","ADJ. electric | cooling | extractor | ceiling, overhead","FAN + NOUN belt, heater"]},"media":{"uk":"media/ldoce/hwd/bre/1/brelasdefan.mp3","us":"media/ldoce/hwd/ame/f/fan1.mp3","img":["media/thumb/fan.jpg"]},"examples":[{"en":"His reluctance to answer her questions simply fanned her curiosity.","cn":"他不爽快地回答她的问题，这就激起了她的好奇心。"},{"en":"His writings fanned the flames of racism.","cn":"他的写作煽起了种族主义情绪。"}],"oxford":{"phon":"fæn","pos":"noun","senses":[{"en":"a person who admires somebody/something or enjoys watching or listening to somebody/something very much","cn":"迷；粉丝；狂热爱好者","ex":{"en":"sports/music fans","cn":"体育迷；音乐迷"}},{"en":"a machine that creates a current of air","cn":"风扇","ex":{"en":"to switch on the electric fan","cn":"开电扇"}},{"en":"a thing that you hold in your hand and wave to create a current of cool air","cn":"扇子"},{"en":"to make air blow onto somebody/something by waving a fan, your hand, etc.","cn":"扇（风）","ex":{"en":"He fanned himself with a newspaper to cool down.","cn":"他用一张报纸给自己扇凉。"},"pos":"verb"},{"en":"to make a fire burn more strongly by blowing on it","cn":"扇，吹（使火更旺）","ex":{"en":"Fanned by a westerly wind, the fire spread rapidly through the city.","cn":"火借助西风迅速蔓延全城。"},"pos":"verb"},{"en":"to make a feeling, an attitude, etc. stronger","cn":"煽起；激起","lab":"literary","ex":{"en":"His reluctance to answer her questions simply fanned her curiosity.","cn":"他不爽快地回答她的问题，这就激起了她的好奇心。"},"pos":"verb"}]}},"faeces":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"粪便;排泄物","en":"Faeces is the solid waste substance that people and animals get rid of from their body by passing it through the anus."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"solid waste material from the bowel s","cn":"粪便"}]},"collocations":{"phrases":["ADJ. fresh | dog, human, etc.","QUANT. mass, piece","VERB + FAECES be excreted in, be expelled in, be passed in The larvae may be excreted in the faeces. | collect A sample of fresh faeces shou","FAECES + NOUN sample","PREP. in the ~ The amount of blood in the faeces was measured."]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdefeces.mp3","us":"media/ldoce/hwd/ame/9/amelasdefaeces.mp3"},"oxford":{"phon":"ˈfiːsiːz","pos":"noun","senses":[{"en":"solid waste material that leaves the body through the anus","cn":"粪便","ex":{"en":"A sample of fresh faeces should be collected each day.","cn":"应该每天收集新粪便的样本。"}}]}},"fantastic":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极好的;极妙的;了不起的","en":"If you say that something is fantastic, you are emphasizing that you think it is very good or that you like it a lot.","ex":{"en":"I have a fantastic social life","cn":"我的社交生活丰富多彩。"}},{"pos":"ADJ 形容词","cn":"(数量)极大的，极多的","en":"A fantastic amount or quantity is an extremely large one.","ex":{"en":"...fantastic amounts of money.","cn":"大笔的钱"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"奇异的;奇妙的;荒诞的","en":"You describe something as fantastic or fantastical when it seems strange and wonderful or unlikely.","ex":{"en":"Unlikely and fantastic legends grew up around a great many figures, both real and fictitious","cn":"围绕着许许多多或真实或虚构的人物，产生了一些不可思议、荒诞离奇的传说。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"extremely good, in a way that makes you feel excited and happy – used mainly in spoken English","cn":""},{"en":"extremely good – used mainly in spoken English","cn":""},{"en":"extremely good – used especially about the quality of something. Excellent is more formal than fantastic/terrific or great , and is used in both spoken and written English","cn":""}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"The adjective fantastic has two meanings — extraordinarily brilliant or ludicrously far-fetched. So when your boss calls your suggestion of work-at-home-in-your-bathrobe-Fridays for the whole office fantastic , be sure you know which one he means."}]},"collocations":{"phrases":["VERBS be, feel, look, smell, sound, taste I felt fantastic after my swim. This cake tastes fantastic.","ADV. really, truly We had a really fantastic holiday. | absolutely, just, quite The sense of freedom was absolutely fantastic. 2 strange","VERBS be, look, sound","ADV. rather It may sound rather fantastic, but it's the truth. | increasingly The plot gets increasingly fantastic as the film goes on."]},"media":{"uk":"media/ldoce/hwd/bre/1/fantastic0205.mp3","us":"media/ldoce/hwd/ame/0/fantastic.mp3"},"examples":[{"en":"The response to our appeal was fantastic.","cn":"我们的呼吁引起十分强烈的反应。"},{"en":"You've got the job? Fantastic!","cn":"你得到那工作了？太好了！"}],"oxford":{"phon":"fænˈtæstɪk","pos":"adjective","senses":[{"en":"extremely good; excellent","cn":"极好的；了不起的","lab":"informal","ex":{"en":"He's done a fantastic job.","cn":"他做得非常好。"}},{"en":"very large; larger than you expected","cn":"很大的；大得难以置信的","lab":"informal","ex":{"en":"The response to our appeal was fantastic.","cn":"我们的呼吁引起十分强烈的反应。"}},{"en":"strange and showing a lot of imagination","cn":"怪诞的；荒诞不经的；富于想象的","g":"[usually before noun]","lab":"less frequent","ex":{"en":"fantastic dreams of forests and jungles","cn":"关于森林和热带丛林的怪梦"}},{"en":"impossible to put into practice; impossible to believe","cn":"不切实际的；难以置信的","ex":{"en":"a fantastic scheme/project","cn":"不切实际的计划／方案"}}]}},"farce":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"荒诞剧;滑稽剧;闹剧","en":"A farce is a humorous play in which the characters become involved in complicated and unlikely situations."},{"pos":"N-UNCOUNT 不可数名词","cn":"(表演或写作的一种风格)荒诞,滑稽","en":"Farce is the style of acting and writing that is typical of farces.","ex":{"en":"The plot often borders on farce.","cn":"情节常常近乎荒诞。"}},{"pos":"N-SING 单数名词","cn":"滑稽的场面(或事件);闹剧","en":"If you describe a situation or event as a farce, you mean that it is so disorganized or ridiculous that you cannot take it seriously.","ex":{"en":"The elections have been reduced to a farce.","cn":"竞选演变为一场闹剧。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an event or a situation that is very badly organized or does not happen properly, in a way that is silly and unreasonable","cn":"闹剧﹐荒唐可笑的事"},{"en":"a humorous play or film in which the characters are involved in complicated and silly situations, or the style of writing or acting that is used","cn":"滑稽戏﹔笑剧﹔闹剧（风格）"}]},"vocab":{"pos":"1 n 2 v n","senses":[{"en":"A farce is a broad satire or comedy, though now it's used to describe something that is supposed to be serious but has turned ridiculous. If a defendant is not treated fairly, his lawyer might say that the trial is a farce ."}]},"collocations":{"phrases":["ADJ. complete, total The whole procedure has become a complete farce. | French, Whitehall (both figurative) It was like a Whitehall farce th","VERB + FARCE become, degenerate into, end in, turn into The debate degenerated into farce when opposing speakers started shouting at each ot"]},"media":{"uk":"media/ldoce/hwd/bre/3/farce0205.mp3","us":"media/ldoce/hwd/ame/f/farce.mp3"},"examples":[{"en":"The trial was a complete farce.","cn":"这次审判完全是一场闹剧。"},{"en":"a bedroom farce (= a funny play about sex)","cn":"床上笑剧"}],"oxford":{"phon":"fɑːs","pos":"noun","senses":[{"en":"a funny play for the theatre based on silly and unlikely situations and events; this type of writing or performance","cn":"滑稽戏（剧本）；闹剧（剧本）；笑剧（剧本）","ex":{"en":"a bedroom farce (= a funny play about sex)","cn":"床上笑剧"}},{"en":"a situation or an event that is so unfair or badly organized that it becomes silly","cn":"荒唐的事情；闹剧","ex":{"en":"The trial was a complete farce.","cn":"这次审判完全是一场闹剧。"}}]}},"famine":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"饥馑;饥荒","en":"Famine is a situation in which large numbers of people have little or no food, and many of them die.","ex":{"en":"Thousands of refugees are trapped by war, drought and famine","cn":"成千上万的难民陷于战争、旱灾和饥荒之中。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sudden shaking of the Earth’s surface that often causes a lot of damage","cn":""},{"en":"a very large amount of water that covers an area that is usually dry","cn":""},{"en":"a long period of dry weather when there is not enough water for plants and animals to live","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A famine is a severe shortage of food, but not the \"I forgot to go to the grocery store and there's nothing to eat in the house\" type of shortage. A famine is usually caused by crop failure or disaster."}]},"collocations":{"phrases":["ADJ. great, severe, terrible | widespread | imminent, impending Against a background of impending famine, heavy fighting took place.","VERB + FAMINE face, suffer Four million people are now facing famine. countries that regularly suffer famines | cause, produce | relieve","FAMINE + VERB strike When famine strikes, it is often women and children who suffer the most.","FAMINE + NOUN relief | victim","PREP. during a/the ~ Thousands of people died during the terrible famine of that year.","PHRASES a threat of famine"]},"media":{"uk":"media/ldoce/hwd/bre/2/famine0205.mp3","us":"media/ldoce/hwd/ame/4/famine.mp3"},"examples":[{"en":"disasters such as floods and famine","cn":"水灾和饥荒这一类灾难"},{"en":"the threat of widespread famine in the area","cn":"区内大范围的饥荒威胁"}],"oxford":{"phon":"ˈfæmɪn","pos":"noun","senses":[{"en":"a lack of food during a long period of time in a region","cn":"饥荒","ex":{"en":"a severe famine","cn":"严重饥荒"}}]}},"fanfare":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(宣告特别事件时演奏的)响亮短曲","en":"A fanfare is a short, loud tune played on trumpets or other similar instruments to announce a special event.","ex":{"en":"The ceremony opened with a fanfare of trumpets.","cn":"仪式以一曲嘹亮的小号短曲开场。"}},{"pos":"N-VAR 可变名词","cn":"大张旗鼓的宣传","en":"If something happens with a fanfare, it happens or is announced with a lot of publicity. If something happens without a fanfare, it happens without a lot of fuss or publicity.","ex":{"en":"The company was privatised with a fanfare of publicity","cn":"公司的私有化搞得沸沸扬扬。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short loud piece of music played on a trumpet to introduce an important person or event 〔","cn":"大人物进场或重要事件开始时用小号吹奏的〕响亮短曲﹐号角花彩"},{"en":"a lot of activity, advertising, or discussion relating to an event 〔","cn":"与某一事件有关的〕喧闹﹐宣传﹐热议"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Fanfare is a loud, proud burst of something to get attention. If you open up a carpet store with one of those sky-sweeping lights, lots of balloons, and a brass band, you’re doing it with great fanfare ."}]},"collocations":{"phrases":["ADJ. great (often figurative) The new building was opened with great fanfare in January 1895. | trumpet","VERB + FANFARE give, play","FANFARE + VERB sound A trumpet fanfare sounded and the procession began.","PHRASES a fanfare of trumpets"]},"media":{"uk":"media/ldoce/hwd/bre/d/fanfare0205.mp3","us":"media/ldoce/hwd/ame/8/fanfare.mp3"},"examples":[{"en":"The product was launched amid much fanfare worldwide.","cn":"这个产品在世界各地隆重推出。"},{"en":"The deal was announced with much fanfare.","cn":"热热闹闹地宣布成交。"}],"oxford":{"phon":"ˈfænfeə(r)","pos":"noun","senses":[{"en":"a short loud piece of music that is played to celebrate somebody/something important arriving","cn":"号角花彩，号角齐鸣（欢迎仪式等上奏的响亮短曲）","g":"[countable]","ex":{"en":"A fanfare of trumpets will sound for the Queen.","cn":"将为女王吹响号角。"}},{"en":"a large amount of activity and discussion in the media to celebrate somebody/something","cn":"（媒体的）大肆宣扬，炒作","g":"[uncountable, countable]","ex":{"en":"The product was launched amid much fanfare worldwide.","cn":"这个产品在世界各地隆重推出。"}}]}},"faction":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(大团体中的)派系，派别，小集团","en":"A faction is an organized group of people within a larger group, which opposes some of the ideas of the larger group and fights for its own ideas.","ex":{"en":"A peace agreement will be signed by the leaders of the country's warring factions.","cn":"该国各敌对派系领导人将签署和平协议。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"派系之争;内讧","en":"Faction is also used to describe argument and disagreement within a group of people.","ex":{"en":"Faction and self-interest appear to be the norm.","cn":"派系之争和自私自利看来非常普遍。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a group of people within a larger political or religious organization who have different aims from many of the other people within it","cn":""},{"en":"a group of people in a political or religious organization who have ideas that most people in the organization do not agree with or think are extreme","cn":""},{"en":"a small group of people who leave a larger political or religious group to form their own smaller group, because they do not agree with the larger group's beliefs, aims, methods etc","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Fractions are smaller parts of whole numbers: one-quarter, one-tenth, one-half, and a faction is a smaller portion of a larger group that breaks away from it. A faction might take a fraction of the people from a large group and start a new group."}]},"collocations":{"phrases":["ADJ. dominant, leading, main, major | internal | competing, opposing, rival, warring | breakaway | dissident, rebel | disaffected | military","VERB + FACTION lead","PREP. ~ in the largest faction in the civil war | ~ within the dominant faction within the government"]},"media":{"uk":"media/ldoce/hwd/bre/3/faction0205.mp3","us":"media/ldoce/hwd/ame/2/faction.mp3"},"examples":[{"en":"a party divided by faction and intrigue","cn":"因派系和阴谋诡计搞得四分五裂的政党"},{"en":"rival factions within the administration","cn":"政府中的对立派别"}],"oxford":{"phon":"ˈfækʃn","pos":"noun","senses":[{"en":"a small group of people within a larger one, whose members have some different aims and beliefs to those of the larger group","cn":"（大团体中的）派系，派别，小集团","g":"[countable]","ex":{"en":"There are rival factions within the administration.","cn":"政府中有对立派别。"}},{"en":"opposition, disagreement, etc. that exists between small groups of people within an organization or political party","cn":"派系斗争；内讧","g":"[uncountable]","lab":"formal","ex":{"en":"a party divided by faction and intrigue","cn":"因派系和阴谋诡计搞得四分五裂的政党"}},{"en":"films, books, etc. that combine fact with fiction (= imaginary events)","cn":"纪实与虚构相结合的电影（或书等）","g":"[uncountable]"}]}},"farewell":{"collins":{"senses":[{"pos":"CONVENTION 惯用语","cn":"同 goodbye","en":"Farewell means the same as goodbye .","ex":{"en":"They said their farewells there at the cafe.","cn":"他们在咖啡馆道别。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to say goodbye to someone, or to say the last things that you want to say to them before you leave each other","cn":""},{"en":"if two or more people say their goodbyes , they say the last things they want to say to each other before leaving each other for a long time","cn":""},{"en":"to wave to someone as they go away from you or as you leave them","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If you’re saying goodbye to someone you might not see for long time, say farewell , preferably while waving a hankie from the Queen Mary before it sails across the Atlantic. Farewell is a fancy way to say goodbye."}]},"collocations":{"phrases":["ADJ. fond | emotional, tearful | sad | silent I said a silent farewell to my village as I left for the city. | final","VERB + FAREWELL bid sb/sth, say, wish sb We bade them a final farewell. | wave I waved farewell to my friends from the deck of the ship. | m","FAREWELL + NOUN appearance This famous warplane is about to make its farewell appearance. | address, speech | performance, tour the band's f","PREP. in ~ He raised his hand in farewell. | ~ to She was sorry to bid farewell to Portugal."]},"media":{"uk":"media/ldoce/hwd/bre/9/farewell_n0205.mp3","us":"media/ldoce/hwd/ame/1/farewell.mp3"},"examples":[{"en":"The troops were farewelled at a ceremony in Darwin.","cn":"为军队举办的送别仪式在达尔文举行。"},{"en":"She said her farewells and left.","cn":"她告别后就离开了。"}],"oxford":{"phon":"ˌfeəˈwel","pos":"noun","senses":[{"en":"the act of saying goodbye to somebody","cn":"告别；辞行","ex":{"en":"She said her farewells and left.","cn":"她告别后就离开了。"}},{"en":"goodbye","cn":"再见","pos":"exclamation"},{"en":"to arrange a ceremony or party for somebody because they are leaving","cn":"为…举行送别仪式（或宴会）","ex":{"en":"The troops were farewelled at a ceremony in Darwin.","cn":"为军队举办的送别仪式在达尔文举行。"},"pos":"verb"}]}},"fad":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一时的风尚;风靡一时之物","en":"You use fad to refer to an activity or topic of interest that is very popular for a short time, but which people become bored with very quickly.","ex":{"en":"Hamnett does not believe environmental concern is a passing fad.","cn":"哈姆内特不相信对环境的关注是昙花一现。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a style of clothes, hair, behaviour etc that is fashionable. Fashion is also used as an uncountable noun, when talking about all of these styles in general","cn":""},{"en":"if there is a vogue for something, or it is in vogue , it is fashionable. Vogue sounds more formal and typical of the language that more educated speakers use than fashion","cn":""},{"en":"a way of doing something or a way of thinking that is becoming fashionable or popular","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If it’s all the rage, everybody’s into it, your parents don’t get it and teenage girls across the globe are trying to outdo each other with it, it’s officially a fad ."}]},"collocations":{"phrases":["ADJ. current, latest, new | passing | management | food Most children have food fads at some time.","PREP. ~ for the fad for cookery programmes"]},"media":{"uk":"media/ldoce/hwd/bre/2/fad0205.mp3","us":"media/ldoce/hwd/ame/0/fad.mp3"},"examples":[{"en":"Rap music proved to be more than just a passing fad.","cn":"事实证明，说唱音乐并不是昙花一现。"},{"en":"the latest/current fad","cn":"最新/当前的时尚"}],"oxford":{"phon":"fæd","pos":"noun","senses":[{"en":"something that people are interested in for only a short period of time","cn":"一时的风尚；短暂的狂热","ex":{"en":"the latest/current fad","cn":"最新／当前的时尚"}}]}},"false":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不正确的;虚假的;错误的","en":"If something is false, it is incorrect, untrue, or mistaken.","ex":{"en":"It was quite clear the President was being given false information by those around him","cn":"很明显，总统身边的人在不断向他传递错误信息。"}},{"pos":"ADJ 形容词","cn":"人造的;伪造的;假的","en":"You use false to describe objects which are artificial but which are intended to look like the real thing or to be used instead of the real thing.","ex":{"en":"...the items she'd secreted in the false bottom of her suitcase.","cn":"她藏在手提箱底部暗格中的物品"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人)虚伪的;(举动)装腔作势的","en":"If you describe a person or their behaviour as false, you are criticizing them for being insincere or for hiding their real feelings.","ex":{"en":"She bowed her head and smiled in false modesty","cn":"她低着头，故作谦卑地笑着。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not real, but intended to seem real and deceive people","cn":"假的﹐伪造的"},{"en":"made to look or seem like something else, especially something worth a lot more money","cn":"伪造的﹐假冒的"},{"en":"a forged official document or bank note has been illegally made to look like a real one 〔","cn":"文件﹑钞票〕伪造的"}]},"vocab":{"pos":"1 adj adv 2 adj 3 ad","senses":[{"en":"Something that's false is wrong or untrue. If you spread false rumors about a friend, you're telling lies."}]},"collocations":{"phrases":["VERBS be, look, prove, sound","ADV. absolutely, completely, entirely, quite, totally, utterly The gossip about her later proved to be entirely false. | partly | certainly,","PHRASES true or false Lagos is the capital of Nigeria. True or false? 2 not showing your true feelings","VERBS be, ring, sound Ella's enthusiasm rang false.","ADV. horribly, very She managed a horribly false smile. | slightly Helen's voice sounded slightly false."]},"media":{"uk":"media/ldoce/hwd/bre/9/false_las2_br.mp3","us":"media/ldoce/hwd/ame/b/false1.mp3"},"examples":[{"en":"They didn't want to raise any false hopes , but they believed her husband had escaped capture.","cn":"他们并不想让人心存奢望，但是他们相信她的丈夫已逃脱追捕。"},{"en":"Predictions of an early improvement in the housing market proved false.","cn":"认为房屋市场很快就好转的预测结果证明是错误的。"}],"oxford":{"phon":"fɔːls","pos":"adjective","senses":[{"en":"wrong; not correct or true","cn":"错误的；不正确的；不真实的","sc":"not true","ex":{"en":"A whale is a fish. True or false?","cn":"鲸鱼是鱼，对还是错？"}},{"en":"not natural","cn":"非天生","sc":"not natural","ex":{"en":"false teeth/eyelashes","cn":"假牙；假睫毛"}},{"en":"not real or what somebody claims it is, but made to look real to cheat people","cn":"假的；伪造的","sc":"not real","ex":{"en":"He had been travelling with a false passport.","cn":"他一直持假护照旅行。"}},{"en":"wrong or not accurate, because it is based on something that is not true or correct","cn":"错误的；不准确的","g":"[usually before noun]","sc":"wrong/not accurate","ex":{"en":"a false argument/assumption/belief","cn":"错误的论据／假设／信念"}},{"en":"not real or sincere","cn":"表里不一的；不真诚的","sc":"not sincere","ex":{"en":"false modesty","cn":"假谦虚"}},{"en":"not faithful","cn":"不忠实","lab":"literary","sc":"not faithful","ex":{"en":"a false lover","cn":"不忠诚的情人"}}]}},"fang":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(某些动物的)尖牙，尖齿","en":"Fangs are the two long, sharp, upper teeth that some animals have.","ex":{"en":"The cobra sank its venomous fangs into his hand.","cn":"眼镜蛇狠狠咬了他一口，毒牙刺进他手上的皮肤。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long sharp tooth of an animal such as a snake or wild dog 〔","cn":"野狗等的〕尖牙﹔〔蛇的〕毒牙"}]},"vocab":{"pos":"n","senses":[{"en":"A fang is a long, sharp tooth that is used to do harm. Vampires have them, venomous snakes have them... you could have them, too, if your Halloween costume includes a set of pointy teeth."}]},"collocations":{"phrases":["ADJ. long | sharp","VERB + FANG bare, show The wolf growled and bared its sharp fangs. | sink The snake sank its fangs into its victim."]},"media":{"uk":"media/ldoce/hwd/bre/6/fang0205.mp3","us":"media/ldoce/hwd/ame/a/fang.mp3"},"oxford":{"phon":"fæŋ","pos":"noun","senses":[{"en":"either of two long sharp teeth at the front of the mouths of some animals, such as a snake or dog","cn":"尖牙；犬齿；（蛇的）毒牙","ex":{"en":"The snake sank its fangs into its victim.","cn":"蛇将毒牙刺入猎物身体中。"}}]}}});
